def _frozen(indexes: Iterable[int]) -> frozenset[int]:
    """frozenset(x) keeps x itself when it already is one (filters are compared by identity and a BlankSet keeps its flag)."""
    return indexes if isinstance(indexes, frozenset) else frozenset(indexes)


class BlankSet(frozenset):
    """Allowed row indexes of one column that also select the virtual blank member (a row of BLANKs) when blank is true."""

    blank: bool = False
    peer: bool = False  # the blank member was reached as the partner of an orphan row of a one-to-one table (it keeps no many-side orphans)
    many: bool = False  # the blank member was reached from a many-side row with an unknown key (it keeps no one-to-one partner orphans)

    def __new__(cls, rows: Iterable[int] = (), blank: bool = False, peer: bool = False, many: bool = False) -> "BlankSet":
        instance = super().__new__(cls, rows)
        instance.blank = blank
        instance.peer = peer
        instance.many = many
        return instance


class _LogicalBlankText(str):
    """The empty text a logical operator's BLANK becomes beside a text in a table constructor: it reads as "" everywhere found, but FORMAT of it is an error in live Power BI (Task 27)."""


class MeasureError(ValueError):
    """A measure definition is invalid or cannot be evaluated for this table."""


class _TableValue(tuple):
    """(context, rows) of a table stored in a VAR."""


class MeasureRuntimeError(MeasureError):
    """A data-dependent evaluation error that Power BI's IFERROR would catch."""


class _DivisionError(MeasureRuntimeError):
    """x/0 or x/BLANK(): Infinity or NaN in Power BI, an error for IFERROR."""


class _CurrencyDivisionError(_DivisionError):
    """A constant Currency numerator divided by 0 (Part F): Power BI folds it, so ISBLANK reads it as not BLANK."""


class _CurrencyOverflowError(MeasureRuntimeError):
    """Part B: a Currency times Infinity or NaN, which Power BI reports as 'too large or too small' (IFERROR catches it)."""


class _StaticTypeFailure:
    """Marks an arithmetic, ^ / POWER or Currency-range failure: a type test (ISNUMBER, ISDOUBLE ...) of the expression is answered by its static type
    instead (live Power BI), while a failure of any other function (ISNUMBER(SQRT(-1))) still propagates."""


class _PowerFailure(_StaticTypeFailure, MeasureRuntimeError):
    """The ^ operator or POWER could not produce a number from finite operands (live Power BI hides it from a type test when both operands are
    constants; an operand that is Infinity or NaN, or that reads rows, lets the error through, except a zero base to a negative power)."""

    zero_base = False  # zero to a power of zero or less
    row_dependent = False  # an operand reads rows, set where the call is evaluated


def _stamp_row_dependence(failure: "_PowerFailure", operands: Iterable[Any], held: Callable[[str], Any], in_row: bool = False) -> None:
    failure.row_dependent = any(not _reads_no_data(operand, held) for operand in operands)


class _CurrencyRangeFailure(_StaticTypeFailure, _CurrencyOverflowError):
    """A Currency times a Double (or a date, or a text) beyond the Currency range."""

    reads_rows = False  # Task 21 Part B: a product that reads rows is shown by ISCURRENCY (measured), a constant one is answered by its type


class _TextRangeFailure(_StaticTypeFailure, MeasureRuntimeError):
    """Task 21 Part G: a text number beyond the Double range in + - * (a type test of it is answered by its type)."""


class _TextConversionFailure(_StaticTypeFailure, MeasureRuntimeError):
    """Task 37 Part B: a text value in arithmetic (+ - * ^) that cannot be converted to a number."""


class _ConvertFailure(_StaticTypeFailure, MeasureRuntimeError):
    """Task 37 Part B: a CONVERT failure whose static target type answers a type test."""


class _IntegerRangeFailure(_StaticTypeFailure, MeasureRuntimeError):
    """Part D: INT, FLOOR or CEILING of a value whose Integer result is beyond the 64-bit range (a type test of it is answered by its static type: ISINTEGER(INT(1E19)) is True, ISDOUBLE False, measured)."""


class _CalculateTableFilterRefusal(MeasureError):
    """A CALCULATETABLE in a Boolean filter whose hoist-or-transition reading was not established (see dax_ct_filters)."""


class _CurrencyConversionError(_CurrencyOverflowError):
    """Task 20 F5: CURRENCY(x) of a Double beyond the Currency range."""


class _HardError(MeasureError):
    """An error Power BI throws instead of returning: IFERROR and ISERROR cannot catch it.

    Raised for an error inside a row expression (SUMX, FILTER, TOPN, IN, ...) or from a VAR that is used.
    """


