def logical_conjuncts(node: tuple[Any, ...]) -> list[tuple[Any, ...]]:
    """The operands of a top-level && chain or AND(a, b), left to right; any other expression is its own single conjunct."""
    if node[0] == "logical" and node[1] == "&&":
        return logical_conjuncts(node[2]) + logical_conjuncts(node[3])
    if node[0] == "call" and node[1] == "AND" and len(node[2]) == 2:
        return logical_conjuncts(node[2][0]) + logical_conjuncts(node[2][1])
    return [node]


def _is_pure_logical(node: Any) -> bool:
    """True when node is a pure logical operator (&&, ||, AND, OR, NOT) which in DAX can never produce BLANK."""
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind == "logical":
        return True
    if kind == "call" and node[1] in {"AND", "OR", "NOT"}:
        return True
    return False


# live Power BI (Task 16 review, 1,008 answers): which empty texts the engine folds when it compiles. An operator over a folded one is typed True/False
# (ISLOGICAL(2.5&&UPPER("")) is True); over one of these, read at run time, it is not (ISLOGICAL(2.5&&LEFT("a",0)) is False). A VAR is always folded.
_NOT_FOLDED_TEXT_CALLS = frozenset({"LEFT", "RIGHT", "MID", "REPT", "REPLACE", "FORMAT", "SELECTEDVALUE"})
_FOLDED_TEXT_CALLS = frozenset({
    "UPPER", "LOWER", "TRIM", "CONCATENATE", "SUBSTITUTE", "IF", "IF.EAGER", "SWITCH", "COALESCE", "IFERROR", "CALCULATE", "CONVERT",
    "EVALUATEANDLOG", "TRUE", "FALSE", "BLANK", "MAX", "MIN",
})


# Task 37: live Power BI, a grid of 1,344 answers (7 BLANK forms x 8 texts x 6 operators x both orders x ISERROR / ISNUMBER).
# What it showed for a BLANK beside a text in arithmetic:
#   * A runtime error (ISERROR True) is raised by + - ^ whenever the text is not a number, however it is made (a literal, TRIM(""), LEFT("a",0),
#     MAX of a text column, the failing VALUE("x")); * never converts the text (it gives BLANK or a typed number); / is unchanged.
#   * ISNUMBER of that failing expression is True ("typed", the error is not seen) only when every part is folded when the formula is compiled:
#     a literal text or TRIM("") is folded, LEFT("a",0) and VALUE("x") are not (ISNUMBER shows the error). A logical BLANK over a folded ""
#     ((1&&""), AND(1,""), (COUNTROWS(Facts)&&"") ...: "K1") also hides the error of a text read from data (MAX(Facts[Note])); the literal BLANK()
#     ("K0") does not; a logical BLANK over a text read at run time ((TRUE()&&LEFT("a",0)): "K2") hides nothing.
#   * K1 * a folded text is a number-typed BLANK (ISNUMBER True) whether the logical reads data or not; beside any other text, and for K0 and K2,
#     the product is the plain BLANK (ISNUMBER False).
#   * x ^ BLANK is x ^ 0, a number; BLANK ^ x does not convert a numeric text and is the plain BLANK except after K1.
# Text kinds: "folded" (non-numeric literal or TRIM / UPPER ...), "number" (a numeric text), "runtime" (empty LEFT / RIGHT / MID ...),
# "data" (MAX / MIN of a text column), "failing" (VALUE of a text that is no number).  Returns "T" / "F" / "E" (ISNUMBER raises the error).
def _isnumber_blank_text(operator: str, blank_kind: str, text_kind: str, blank_first: bool) -> str:
    if operator in {"+", "-"}:
        if text_kind == "number":
            return "T"
        if text_kind == "folded":
            return "E" if blank_kind == "K2" else "T"
        if text_kind == "data":
            return "T" if blank_kind == "K1" else "E"
        return "E"
    if operator == "*":
        return "T" if blank_kind == "K1" and text_kind in {"folded", "number"} else "F"
    if operator == "^":
        if text_kind == "number":
            return "T" if blank_kind == "K1" or not blank_first else "F"
        if text_kind == "folded":
            return "T" if blank_kind == "K1" or (blank_kind == "K0" and not blank_first) else "E"
        if text_kind == "data":
            return "T" if blank_kind == "K1" and blank_first else "E"
        return "E"
    raise ValueError(operator)


def _read_at_run_time(node: Any) -> bool | None:
    """Does this operand reach a text the engine does not fold?  None: a function not measured."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "let":
        return False
    if node[0] == "reference":
        return None
    if node[0] == "call":
        if node[1] in _NOT_FOLDED_TEXT_CALLS:
            return True
        if node[1] in {"MAX", "MIN"}:
            return False
        if node[1] not in _FOLDED_TEXT_CALLS:
            return None
        parts = [_read_at_run_time(child) for child in node[2]]
    elif node[0] in {"number", "string", "boolean", "blank", "var"}:
        return False
    else:
        parts = [_read_at_run_time(child) for child in node[1:] if isinstance(child, tuple)]
    return True if True in parts else None if None in parts else False


def _all_true_false(branches: Any, variables: dict[str, Any] | None) -> bool:
    """Every branch but a BLANK is True/False: one branch of another type makes a Variant (live Power BI, Task 16 review: MAXX({IF(TRUE(),2.5&&"",1)},[Value]) is BLANK)."""
    typed = [branch for branch in branches if branch != ("blank",)]
    return bool(typed) and all(_is_true_false_column_node(branch, variables) for branch in typed)


def _is_true_false_column_node(node: Any, variables: dict[str, Any] | None = None) -> bool:
    """A column or expression of this node is True/False, unwrapping let, var, CALCULATE, IF, SWITCH, COALESCE."""
    seen: set[str] = set()
    local: dict[str, Any] = {}
    while isinstance(node, tuple) and node:
        if node[0] == "let":
            local.update({str(name): value for name, value in node[1]})
            node = node[2]
        elif node[0] == "var" and node[1] not in seen and (node[1] in local or (variables and node[1] in variables)):
            seen.add(node[1])
            node = local.get(node[1], (variables or {}).get(node[1]))
        elif node[:2] == ("call", "CALCULATE") and len(node[2]) == 1:
            node = node[2][0]
        elif node[0] == "call" and node[1] in {"IF", "IF.EAGER"} and len(node[2]) in {2, 3}:
            return _all_true_false(node[2][1:], {**(variables or {}), **local})
        elif node[:2] == ("call", "IFERROR") and len(node[2]) == 2:
            return _all_true_false(node[2], {**(variables or {}), **local})
        elif node[:2] == ("call", "SWITCH") and len(node[2]) >= 3:
            branches = [node[2][i] for i in range(2, len(node[2]), 2)]
            if len(node[2]) % 2 == 0:
                branches.append(node[2][-1])
            return _all_true_false(branches, {**(variables or {}), **local})
        elif node[:2] == ("call", "COALESCE") and node[2]:
            return _all_true_false(node[2], {**(variables or {}), **local})
        else:
            return _is_pure_logical(node)
    return False


def _consume_infinity(thunk: Any) -> Any:
    """Refuse to let an Infinity/NaN flow into a comparison, ISBLANK or SWITCH.

    Power BI compares Infinity (IF(1/0>1, ...) is true). The local engine has no
    Infinity, so it must not let IFERROR turn that case into a quietly different
    answer; raising a plain MeasureError makes the formula visibly unsupported.
    """
    try:
        return thunk()
    except _DivisionError as exc:
        raise MeasureError(
            "A division by zero feeds a comparison, ISBLANK or SWITCH; Power BI treats it "
            "as Infinity, which the local engine does not model."
        ) from exc


_CURRENCY_LIMIT = Decimal("922337203685477.5807")  # the Currency type's range
_TYPE_TESTS = frozenset({"ISINTEGER", "ISINT64", "ISDOUBLE", "ISDECIMAL", "ISCURRENCY", "ISNUMBER", "ISTEXT", "ISNONTEXT", "ISLOGICAL", "ISDATETIME", "ISBOOLEAN", "ISSTRING", "ISNUMERIC", "ISBLANK"})
_DATETIME_CLAMP_LOW = dax_dates.from_datetime(datetime(100, 1, 1))  # Task 19 Part A: CONVERT of -Infinity or a too small number
_CURRENCY_INFINITY = object()  # any value but None: ISBLANK of a constant Currency / 0 is False (Part F)


def _constant_currency(node: tuple[Any, ...]) -> bool:
    """Part F: True for a numerator Power BI folds at compile time.

    CURRENCY of a number (or of a minus on one), and + - * of those and numbers, with at least one CURRENCY.
    """

    def plain_number(part: tuple[Any, ...]) -> bool:
        if part[0] == "call" and part[1] == "DATE":
            return all(argument[0] == "number" for argument in part[2])  # a date literal folds as a number does
        return part[0] == "number" or (part[0] == "unary" and part[1] == "-" and part[2][0] == "number")

    if node[0] == "call" and node[1] == "CURRENCY" and len(node[2]) == 1:
        return plain_number(node[2][0])
    if node[0] == "binary" and node[1] in {"+", "-", "*"}:
        left, right = node[2], node[3]
        return (
            (_constant_currency(left) or plain_number(left))
            and (_constant_currency(right) or plain_number(right))
            and (_constant_currency(left) or _constant_currency(right))
        )
    return False


def _constant_arithmetic(node: Any) -> bool:
    """Numbers, CURRENCY of a number, and + - * / and unary +/- of those: an operand that reads nothing."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "number":
        return True
    if node[0] == "unary" and node[1] in {"+", "-"}:
        return _constant_arithmetic(node[2])
    if node[0] == "binary" and node[1] in {"+", "-", "*", "/"}:
        return _constant_arithmetic(node[2]) and _constant_arithmetic(node[3])
    if node[0] == "call" and node[1] == "DATE":
        return all(_constant_arithmetic(argument) for argument in node[2])
    return node[0] == "call" and node[1] == "CURRENCY" and len(node[2]) == 1 and _constant_arithmetic(node[2][0])


def _reaches_currency_division(node: Any) -> bool:
    """Corrections rule 2: True when ISBLANK's argument reaches a constant Currency division through + - * / and unary minus alone.

    Every other operand on the way must be a constant; the divisor of the division itself may read data.  IF, COALESCE, a VAR or a
    data-reading operand in between leaves the answer an error, which stays refused as on main.
    """
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "unary" and node[1] == "-":
        return _reaches_currency_division(node[2])
    if node[0] == "let":  # VAR z=0 RETURN CURRENCY(1)/z: the VAR holds the divisor; a RETURN that is the VAR itself does not reach the division
        return _reaches_currency_division(node[2])
    if node[0] != "binary" or node[1] not in {"+", "-", "*", "/"}:
        return False
    if node[1] == "/" and _constant_currency(node[2]):
        return True
    return (_reaches_currency_division(node[2]) and _constant_arithmetic(node[3])) or (
        _reaches_currency_division(node[3]) and _constant_arithmetic(node[2])
    )


def _isblank_consume(thunk: Any, argument: Any) -> bool:
    """ISBLANK's test of its argument (Part F): only the ISBLANK call uses this; _consume_infinity stays for the rest."""
    if not _reaches_currency_division(argument):
        return _consume_infinity(thunk) is None

    def guarded() -> Any:
        try:
            return thunk()
        except _CurrencyDivisionError:
            return _CURRENCY_INFINITY  # caught before _consume_infinity turns it into a refusal

    return _consume_infinity(guarded) is None


@dataclass(frozen=True)
class VisualAxisContext:
    """The report selection behind one chart category filter."""

    table_id: str
    column: str
    selected_rows: frozenset[int] | None
    blank_allowed: bool | None
    filter_table_ids: frozenset[str]


def _reject_power_query_error(value: Any, column: str, row: int | None) -> None:
    if not is_cell_error(value):
        return
    location = f" at row {row}" if row is not None else ""
    raise MeasureError(
        f"Column {column!r} contains a Power Query cell error{location}: {value.message}. "
        "Remove or replace the error before evaluating this DAX expression."
    )


