def _calls_function(node: Any, name: str) -> bool:
    """Whether a call to ``name`` appears anywhere inside the expression tree."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] == name:
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_calls_function(child, name) for child in children if isinstance(child, tuple))


def _divides_by_number(node: Any) -> bool:
    """Whether a / appears in the expression (a Currency divided by a number is still Currency-built for XNPV's BLANK rule)."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "binary" and node[1] == "/":
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_divides_by_number(child) for child in children if isinstance(child, tuple))


def _has_constant_zero_division(node: Any) -> bool:
    """Whether a division by the constant 0 (1/0, x/0) appears anywhere in the expression tree."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] == "IFERROR":
        return False  # IFERROR(1/0, BLANK()) is not the NaN of 1/0*0 (Power BI gives BLANK there)
    if node[0] == "binary" and node[1] == "/" and len(node) == 4 and node[3][0] == "number" and node[3][1] == 0:
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_has_constant_zero_division(child) for child in children if isinstance(child, tuple))


def _nested_nan_extreme(node: Any) -> bool:
    """Task 45 Part C: whether a MAXX / MINX over a derived table (constructor, DATATABLE, ROW, UNION) with a division by constant zero sits in the expression."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] in {"MAXX", "MINX"} and len(node[2]) >= 2:
        table = node[2][0]
        derived = table[0] == "tableconstructor" or (table[0] == "call" and table[1] in {"DATATABLE", "ROW", "UNION"})
        if derived and _has_constant_zero_division(node[2][1]):
            return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_nested_nan_extreme(child) for child in children if isinstance(child, tuple))


def _literal_number(node: Any) -> Any:
    """The Decimal value of a number literal, optionally signed, else None."""
    if not isinstance(node, tuple) or not node:
        return None
    if node[0] == "number":
        return node[1]
    if node[0] == "unary" and node[1] in {"-", "+"} and len(node) == 3:
        inner = _literal_number(node[2])
        if inner is None:
            return None
        return -inner if node[1] == "-" else inner
    return None


def _statically_failing_call(node: Any) -> bool:
    """Task 45 Part B: a call of SQRT / LOG / LN / LOG10 / POWER whose constant arguments lie outside its domain (SQRT(-1), LOG(0), POWER(0, -1)), which raises in Power BI whatever the row."""
    if not isinstance(node, tuple) or len(node) != 3 or node[0] != "call" or not isinstance(node[2], tuple):
        return False
    name, arguments = node[1], [_literal_number(argument) for argument in node[2]]
    if name == "SQRT":
        return len(arguments) == 1 and arguments[0] is not None and arguments[0] < 0
    if name in {"LN", "LOG10", "LOG"} and arguments and arguments[0] is not None and arguments[0] <= 0:
        return True
    if name == "LOG" and len(arguments) == 2 and arguments[1] is not None and (arguments[1] <= 0 or arguments[1] == 1):
        return True
    if name == "POWER" and len(arguments) == 2 and arguments[0] is not None and arguments[1] is not None:
        if arguments[0] == 0 and arguments[1] < 0:
            return True
        return arguments[0] < 0 and arguments[1] != arguments[1].to_integral_value()
    return False


def _has_failing_scalar(node: Any) -> bool:
    """Task 45 Part B: whether the tree holds an ERROR call or a call that statically raises an argument error."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and (node[1] == "ERROR" or _statically_failing_call(node)):
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_has_failing_scalar(child) for child in children if isinstance(child, tuple))


def _zero_division_beside_other_operand(node: Any) -> bool:
    """Task 45 Part C: whether a + or - holds a division by constant zero on one side and, on the other, a COUNTROWS or BLANK() operand (a BLANK): BLANK minus NaN is NaN in Power BI."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "binary" and node[1] in {"+", "-"} and len(node) == 4:
        left_nan, right_nan = _has_constant_zero_division(node[2]), _has_constant_zero_division(node[3])
        if left_nan != right_nan:
            other = node[3] if left_nan else node[2]
            if _calls_function(other, "COUNTROWS") or _calls_function(other, "BLANK"):
                return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_zero_division_beside_other_operand(child) for child in children if isinstance(child, tuple))


_ITERATOR_NAMES = frozenset({"SUMX", "AVERAGEX", "MAXX", "MINX", "COUNTX", "COUNTAX", "PRODUCTX", "CONCATENATEX", "GEOMEANX", "MEDIANX"})


def _nested_failing_iterator(node: Any) -> bool:
    """Task 45 Part B: whether the expression holds an iterator over a table that can have rows whose body calls ERROR or a statically failing function such as SQRT(-1) (an empty FILTER(t, FALSE()) cannot)."""
    if not isinstance(node, tuple) or not node:
        return False
    if _blank_cancels_failing_operand(node):
        return False  # a BLANK operand cancels the failing iterator beside it
    if node[0] == "call" and node[1] in _ITERATOR_NAMES and len(node[2]) >= 2:
        table = node[2][0]
        statically_empty = table[0] == "call" and table[1] == "FILTER" and len(table[2]) == 2 and table[2][1] == ("boolean", False)
        if not statically_empty and _has_failing_scalar(node[2][1]):
            return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_nested_failing_iterator(child) for child in children if isinstance(child, tuple))


def _static_blank_node(node: Any) -> bool:
    """Task 45 Part B: a node that is BLANK whatever the row: BLANK(), a VAR bound to one, IF(FALSE(), x) without an else, DIVIDE(number, 0 or BLANK())."""
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind == "blank" or node == ("call", "BLANK", ()):
        return True
    if kind == "call" and node[1] in {"IF", "IF.EAGER"} and len(node[2]) == 2 and node[2][0] == ("boolean", False):
        return True
    if kind == "call" and node[1] == "DIVIDE" and len(node[2]) == 2 and node[2][0][0] == "number":
        denominator = node[2][1]
        return denominator == ("blank",) or denominator == ("call", "BLANK", ()) or (denominator[0] == "number" and denominator[1] == 0)
    if kind == "let" and len(node) == 3 and isinstance(node[2], tuple) and node[2][0] == "var":
        bound = dict(node[1]).get(node[2][1])
        return bound is not None and _static_blank_node(bound)
    return False


def _blank_cancels_failing_operand(node: Any) -> bool:
    """Task 45 Part B: BLANK * failing and failing * BLANK are BLANK (BLANK / failing too, with the BLANK on the left); a failing operand is an ERROR call."""
    if not isinstance(node, tuple) or len(node) != 4 or node[0] != "binary" or node[1] not in {"*", "/"}:
        return False
    left, right = node[2], node[3]

    def failing(operand: Any) -> bool:
        return _calls_function(operand, "ERROR") and not _calls_function(operand, "IFERROR")

    if _static_blank_node(left) and failing(right):
        return True
    return node[1] == "*" and _static_blank_node(right) and failing(left)

def _builds_currency(node: Any) -> bool:
    """Whether the expression calls CURRENCY outside a CONVERT (CONVERT(CURRENCY(x),DOUBLE) is a plain double)."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] == "CONVERT":
        return False
    if node[0] == "call" and node[1] == "CURRENCY":
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_builds_currency(child) for child in children if isinstance(child, tuple))


_XNPV_LAST_DAY = 2958465  # 9999-12-31: Power BI answers erratically for later dates (probed in iteration 91), so the local engine refuses them


def _bare_column_as_table(node: Any) -> bool:
    """Whether TOPN / FILTER / an X-iterator is given a plain column where a table belongs (Power BI: a single value for the column cannot be determined)."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call":
        position = 1 if node[1] == "TOPN" else 0 if node[1] in {"FILTER", "SUMX", "AVERAGEX", "MAXX", "MINX", "COUNTX", "COUNTAX", "CONCATENATEX"} else None
        if position is not None and len(node[2]) > position and isinstance(node[2][position], tuple) and node[2][position][0] == "reference" and node[2][position][1]:
            return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_bare_column_as_table(child) for child in children if isinstance(child, tuple))


def _keepfilters_inside_time_function(node: Any) -> bool:
    """Whether KEEPFILTERS sits inside a date-set function (PREVIOUSQUARTER(KEEPFILTERS(Cal[Date]))): a Power BI error wherever it is written."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] in _TIME_FILTER_FUNCTIONS and any(
        isinstance(argument, tuple) and argument[:2] == ("call", "KEEPFILTERS") for argument in node[2]
    ):
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_keepfilters_inside_time_function(child) for child in children if isinstance(child, tuple))


def _iterator_body_reads_a_table_column(node: Any) -> bool:
    """Whether an X-iterator anywhere in this expression has a body that reads a column by table name outside an aggregation."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] in {"SUMX", "AVERAGEX", "MAXX", "MINX", "COUNTX", "COUNTAX", "CONCATENATEX"} and len(node[2]) >= 2:
        if any(reference[1] for reference in _direct_column_references(node[2][1])):
            return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_iterator_body_reads_a_table_column(child) for child in children if isinstance(child, tuple))


def _has_kind(node: Any, kinds: set[str]) -> bool:
    """True when a node of one of these kinds occurs anywhere in this node."""
    if not isinstance(node, tuple) or not node:
        return False
    if isinstance(node[0], str) and node[0] in kinds:
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_has_kind(child, kinds) for child in children if isinstance(child, tuple))


def _has_call_named(node: Any, names: set[str] | frozenset[str]) -> bool:
    """True when a call of one of these functions occurs anywhere in this node."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and len(node) > 1 and node[1] in names:
        return True
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_has_call_named(child, names) for child in children if isinstance(child, tuple))


def _iter_reference_nodes(node: Any) -> Iterable[tuple[Any, ...]]:
    if not isinstance(node, tuple) or not node:
        return
    if node[0] == "reference":
        yield node
        return
    # a call's argument list is a tuple of nodes, so its first element is a node, not a kind name
    children = node if isinstance(node[0], tuple) else node[1:]
    for child in children:
        if isinstance(child, tuple):
            yield from _iter_reference_nodes(child)


def _validate_relationship_modifier_filters(
    filter_arguments: tuple[tuple[Any, ...], ...],
) -> None:
    """Validate Boolean and supported date filters beside a relationship modifier."""
    for filter_argument in filter_arguments:
        if (
            filter_argument[0] == "call"
            and filter_argument[1] in _TIME_FILTER_FUNCTIONS
        ):
            _validate_literal_positions(filter_argument)
            continue
        predicate, _keep = _calculate_filter_argument(filter_argument)
        _calculate_boolean_filter_column(predicate)


def _is_divide_alternate_constant(node: tuple[Any, ...]) -> bool:
    """DIVIDE accepts a numeric literal, non-empty string, TRUE(), or BLANK() as its alternate result."""
    if node[0] in {"number", "blank"}:
        return True
    if node[0] == "string" and bool(node[1]):
        return True
    if node[0] == "boolean" and node[1] is True:
        return True
    return (
        node[0] == "unary"
        and node[1] in {"+", "-"}
        and node[2][0] == "number"
    )


# Scalar math verified against Power BI Desktop 2.157.879.0 (ADOMD, iteration 64).
# value is (minimum, maximum) argument count.
_SCALAR_MATH_ARITY = {
    "INT": (1, 1), "TRUNC": (1, 2), "SIGN": (1, 1), "SQRT": (1, 1),
    "EXP": (1, 1), "LN": (1, 1), "MOD": (2, 2), "POWER": (2, 2),
    "CEILING": (2, 2), "FLOOR": (2, 2),
}


def _to_15_digits_half_up(value: float) -> float:
    """A Double at 15 significant digits, an exact tie going away from zero (measured, Task 38 round 4: CEILING(3^25*2^15,5) is 27763953154228248, its quotient
    5552790630845645 is cut to ...650, not to the half-even ...640 that Python's own formatting gives)."""
    if not math.isfinite(value) or value == 0:
        return value
    exact = Decimal(value)
    with localcontext() as context:
        context.prec = 60
        quantum = Decimal(1).scaleb(exact.adjusted() - 14)
        return float((exact / quantum).to_integral_value(rounding=ROUND_HALF_UP) * quantum)


def _round_to_multiple(
    function: str, number: Decimal | None, significance: Decimal | None
) -> Decimal | None:
    """CEILING/FLOOR to a multiple, following Power BI's sign and blank rules."""
    if number is None:
        return None
    if number == 0:
        return Decimal(0)
    if significance is None or significance == 0:
        if function == "CEILING":
            return Decimal(0)
        raise MeasureRuntimeError("FLOOR needs a significance other than zero.")
    if number > 0 and significance < 0:
        raise MeasureRuntimeError(
            f"{function} needs a significance with the same sign as the number."
        )
    if 2 ** 53 <= abs(number) < 2 ** 63:
        q = float(abs(number)) / float(abs(significance))
        q15 = _to_15_digits_half_up(q)
        whole = math.ceil(q15) if function == "CEILING" else math.floor(q15)
        prod = float(whole) * float(abs(significance))
        if number < 0:  # measured: FLOOR and CEILING of a negative number beyond 2^53 are both the negated magnitude result
            prod = -prod
        if significance == significance.to_integral_value():
            return Decimal(int(prod))
        return Decimal(prod)
    rounding = ROUND_CEILING if function == "CEILING" else ROUND_FLOOR
    with localcontext() as exact:
        exact.prec = max(_EXACT_PRECISION, number.adjusted() + 30)  # keep every integer digit
        step = abs(significance)
        if significance < 0:  # both negative: round the magnitude, keep the sign
            return -(abs(number) / step).to_integral_value(rounding=rounding) * step
        return (number / step).to_integral_value(rounding=rounding) * step


def _non_finite_power(base: Decimal, exponent: Decimal) -> Decimal:
    """Task 20 F2: x^y with an Infinity or NaN operand, as Power BI measures it.
    Finite base, non-finite exponent: +Infinity and a positive NaN are the error; -Infinity and a negative NaN (the NaN of 0/0) give 0
    for base >= 0 and the error for a negative base. Non-finite base, finite exponent: 0 gives 1, a positive exponent or one of size
    0.5 is the error; a negative one gives 0 for +Infinity, and for -Infinity or NaN a whole one (the error from -1E15 down, a size of 1E9 up to there
    unmeasured and refused) and the error for a fractional one. Both non-finite is the error."""
    error = MeasureRuntimeError("An argument of function 'POWER' has the wrong data type or the result is too large or too small.")
    if not base.is_finite():
        if not exponent.is_finite():
            raise error
        if exponent == 0:
            return Decimal(1)
        if exponent > 0 or abs(exponent) == Decimal("0.5"):
            raise error
        if base == Decimal("Infinity"):
            return Decimal(0)
        if exponent != exponent.to_integral_value():
            raise error
        if abs(exponent) >= 1000000000:
            if exponent <= Decimal("-1E15"):
                raise error
            raise dax_typed.refusal("A huge whole negative power of an Infinity or NaN is not modelled by the local engine.")
        return Decimal(0)
    if exponent.is_nan() and not exponent.is_signed() or exponent == Decimal("Infinity"):
        raise error
    if base >= 0:
        return Decimal(0)
    raise error


def _scalar_math_value(function: str, values: list[Decimal | None]) -> Decimal | None:
    """Evaluate a scalar math function with Power BI's blank handling.

    A blank first argument returns blank for INT, TRUNC, SIGN, SQRT, MOD and POWER;
    EXP(BLANK()) is 1 and POWER(x, BLANK()) is 1 (blank counts as zero there).
    Arguments that make Power BI raise an error raise MeasureError instead.
    LN(BLANK()) is -Infinity in Power BI, so it is rejected locally.
    """
    first = values[0]
    if function in {"MOD", "CEILING", "FLOOR"} and first is None and values[1] is not None and not values[1].is_finite():
        return None  # Task 20 F4: a BLANK first argument is BLANK beside an Infinity or a NaN
    if function == "CEILING" and first is not None and first.is_finite() and first == 0 and values[1] is not None and not values[1].is_nan():
        return Decimal(0)  # Task 20 F3: CEILING(0, Infinity) is 0, as CEILING(0, x) is
    if function != "POWER" and any(value is not None and not value.is_finite() for value in values):  # POWER: see the branch below
        if function == "TRUNC" and first is not None and not first.is_finite() and all(value is None or value.is_finite() for value in values[1:]):
            return Decimal("NaN") if first == Decimal("Infinity") else first  # Part E: TRUNC of +Infinity is NaN (measured); -Infinity stays as it was
        raise MeasureRuntimeError(
            f"An argument of function '{function}' has the wrong data type or the result is too large or too small."
        )
    if function in {"CEILING", "FLOOR"}:
        return _round_to_multiple(function, first, values[1])
    if function == "EXP":
        return (first or Decimal(0)).exp()
    if function == "LN":
        if first is None:
            return Decimal("-Infinity")
        if first <= 0:
            error = MeasureRuntimeError("LN needs a number greater than zero.")
            error.infinity = False
            raise error
        return first.ln()
    if function == "POWER":
        exponent = values[1] or Decimal(0)
        if first is None:
            if values[1] is None:
                raise MeasureRuntimeError("An argument of function 'POWER' has the wrong data type or the result is too large or too small.")
            return None
        if not first.is_finite() or not exponent.is_finite():
            return _non_finite_power(first, exponent)  # Task 20: an infinite or NaN operand (every numeric type reaches here)
        if first == 0 and exponent == 0 and first.is_signed():
            return Decimal(1)  # Task 20 F2: a Double minus zero (an Int64 or literal zero has no sign) to the power 0 is 1
        if first == 0 and first.is_signed() and exponent > 0:
            # a Double minus zero to a positive power (measured): 0.5 gives 0, any other fraction is the error, a whole one gives 0 up to 3E9 and is the
            # error from 1E14; the stretch between is unmeasured
            wrong = MeasureRuntimeError("An argument of function 'POWER' has the wrong data type or the result is too large or too small.")
            if exponent != Decimal("0.5"):
                if exponent != exponent.to_integral_value() or exponent >= Decimal("1E14"):
                    raise wrong
                if exponent > Decimal("3E9"):
                    raise dax_typed.refusal("A minus zero to a whole power between 3E9 and 1E14 is not modelled by the local engine.")
        if first == 0 and exponent <= 0:
            raise MeasureRuntimeError("POWER of zero needs a positive exponent.")
        if first < 0:
            if abs(exponent) >= 4294967295:  # Power BI refuses such exponents for a negative base
                raise MeasureRuntimeError(
                    "An argument of function 'POWER' has the wrong data type or the result is too large or too small."
                )
            if exponent != exponent.to_integral_value():
                # only an exact odd root (exponent 1/3, 1/5, -1/3 ...) has a real result: the negative of the root
                exponent_float = float(exponent)
                reciprocal = round(1 / exponent_float) if exponent_float else 0
                if not reciprocal % 2 or 1 / reciprocal != exponent_float:
                    raise MeasureRuntimeError(
                        "An argument of function 'POWER' has the wrong data type or the result is too large or too small."
                    )
                return -((-first) ** (Decimal(1) / Decimal(reciprocal)))  # the exact root: the exponent may be the binary double nearest 1/odd (Task 22)
        if abs(exponent) > 1000:  # Power BI computes POWER in double precision; huge exponents amplify the difference
            overflow = MeasureRuntimeError("POWER result is outside the supported numeric range.")
            try:
                if exponent == exponent.to_integral_value():
                    result, square, count = 1.0, float(first), int(abs(exponent))
                    while count:  # repeated squaring, as the engine does
                        if count & 1:
                            result *= square
                        square *= square
                        count >>= 1
                    if exponent < 0:
                        if not result:  # the reciprocal of an underflowed power is infinite
                            raise overflow
                        result = 1 / result if not math.isinf(result) else 0.0
                else:
                    result = math.pow(float(first), float(exponent))
            except (OverflowError, ValueError, ZeroDivisionError) as error:
                raise overflow from error
            if math.isinf(result) or math.isnan(result):
                raise overflow
            return Decimal(repr(result))
        if exponent < 0:  # measured: a negative power is one over the positive power, in doubles (2^-0.5 is 0.7071067811865475, one unit below the nearest)
            positive = float(first ** -exponent)
            if positive and not math.isinf(positive) and not math.isinf(1 / positive):
                return Decimal(repr(1 / positive))
        return first ** exponent
    if function == "MOD":
        divisor = values[1] or Decimal(0)
        if first is None:
            if values[1] is None:
                raise MeasureRuntimeError("MOD cannot divide by zero.")  # Task 20 F4: MOD(BLANK(),BLANK()) is the error
            return None
        if divisor == 0:
            raise MeasureRuntimeError("MOD cannot divide by zero.")
        with localcontext() as exact:
            exact.prec = _EXACT_PRECISION  # % needs the whole quotient to fit
            quotient_magnitude = abs(first / divisor)
            if quotient_magnitude >= Decimal("1.126E12"):  # measured 2026-11-02: also at small |x|, MOD(5,1E-30) is this error
                raise MeasureRuntimeError("An argument of function 'MOD' has the wrong data type or the result is too large or too small.")
            if quotient_magnitude > Decimal("1125899906844"):
                raise dax_typed.refusal("MOD of a quotient between 1125899906844 and 1.126E12 is not modelled by the local engine.")
            remainder = first % divisor  # sign follows the dividend
            if remainder != 0 and (remainder < 0) != (divisor < 0):
                remainder += divisor  # DAX: result takes the divisor's sign
        return remainder
    if first is None:
        return None
    if function == "INT":
        return first.to_integral_value(rounding=ROUND_FLOOR)
    if function == "SIGN":  # Part B: SIGN of a negative zero is -1 (measured)
        return Decimal(-1) if first.is_zero() and first.is_signed() else Decimal((first > 0) - (first < 0))
    if function == "SQRT":
        if first < 0:
            raise MeasureRuntimeError("SQRT needs a number that is zero or greater.")
        return first.sqrt()
    # TRUNC(number[, digits])
    digits = values[1] if len(values) > 1 and values[1] is not None else Decimal(0)
    if digits.is_finite():
        digits = digits.to_integral_value(rounding=ROUND_HALF_UP)  # live Power BI (iteration 88): fractional digits round like ROUND's (1.9 is 2, 1.1 is 1)
    if not digits.is_finite():
        raise MeasureRuntimeError("TRUNC digits must be a number.")
    if abs(first) >= Decimal("1E16"):
        return first  # Part E: a finite value beyond 1E16 is returned unchanged by TRUNC (TRUNC(1E300) is 1E+300, measured)
    if digits > 28:
        return first  # live Power BI (iteration 88): nothing is left to cut (digits 29 and 100 give the number itself)
    if digits < -28:
        return Decimal(0)
    with localcontext() as exact:
        exact.prec = _EXACT_PRECISION  # quantize must hold every kept digit
        return first.quantize(Decimal(1).scaleb(-int(digits)), rounding=ROUND_DOWN)


# Power BI computes in IEEE doubles; larger magnitudes are errors there.
_DOUBLE_MAX = Decimal("1.7976931348623157E+308")
_EXACT_PRECISION = 100
_INT64_RANGE = Decimal(2) ** 63  # Part D: an Integer result must lie within the 64-bit range; 2^63 itself is the error


def _has_power(node: Any, held: Callable[[str], Any], seen: frozenset[str] = frozenset()) -> bool:
    """True when a ^ or POWER of 1E15 or more (or of unknown size) appears in the expression (followed through VARs): Power BI's own power precision is Task 23."""
    if not isinstance(node, tuple) or not node:
        return False
    if (node[0] == "binary" and node[1] == "^") or (node[0] == "call" and node[1] == "POWER" and len(node[2]) == 2):
        operands = (node[2], node[3]) if node[0] == "binary" else tuple(node[2])
        literals = []
        for operand in operands:
            sign = 1
            while isinstance(operand, tuple) and operand and operand[0] == "unary" and operand[1] in {"+", "-"}:
                sign *= -1 if operand[1] == "-" else 1
                operand = operand[2]
            if not (isinstance(operand, tuple) and operand and operand[0] == "number"):
                return True  # an operand that is not a literal: the size of the power is not known here
            literals.append(sign * float(operand[1]))
        try:
            if abs(literals[0] ** literals[1]) < 1E15:
                return any(_has_power(operand, held, seen) for operand in operands)  # a small literal power (2^-0.5) is multiplied up later; the spec settles those
        except (OverflowError, ZeroDivisionError, ValueError):
            pass
        return True
    if node[0] == "var" and len(node) > 1 and isinstance(node[1], str) and node[1] not in seen:
        return _has_power(held(node[1]), held, seen | {node[1]})
    return any(_has_power(child, held, seen) for child in node if isinstance(child, tuple)) or any(_has_power(item, held, seen) for child in node if isinstance(child, list) for item in child)


def _contains_power(node: Any, held: Callable[[str], Any], seen: frozenset[str] = frozenset()) -> bool:
    """True when a ^ or POWER of any size appears in the expression (followed through VARs): a power of 7^14 times 2^14 is a product of powers each below 1E15."""
    if not isinstance(node, tuple) or not node:
        return False
    if (node[0] == "binary" and node[1] == "^") or (node[0] == "call" and node[1] == "POWER" and len(node[2]) == 2):
        return True
    if node[0] == "var" and len(node) > 1 and isinstance(node[1], str) and node[1] not in seen:
        return _contains_power(held(node[1]), held, seen | {node[1]})
    return any(_contains_power(child, held, seen) for child in node if isinstance(child, tuple)) or any(_contains_power(item, held, seen) for child in node if isinstance(child, list) for item in child)


def _refuse_quotient_band(arguments: Any, values: list[Any], held: Callable[[str], Any]) -> None:
    """QUOTIENT whose Double quotient is from 2^52 to 2^53 and whose operands hold a power (measured, Task 38): the result comes back one more when odd
    (QUOTIENT(2^52+1,1) is 4503599627370498, QUOTIENT(10^16+1,1.5) is 6666666666666668, QUOTIENT(POWER(7,14)*POWER(2,14)+1,1.5) is ...012 not ...011): refused.
    A literal 5E15 is modelled (QUOTIENT(5E15,1) is 5000000000000000)."""
    if len(values) == 2 and all(isinstance(value, Decimal) and value.is_finite() and not dax_dates.is_date(value) for value in values) and values[1] != 0:
        if 2 ** 52 <= abs(float(values[0]) / float(values[1])) < 2 ** 53 and (_contains_power(arguments[0], held) or _contains_power(arguments[1], held)):
            raise dax_typed.refusal("A QUOTIENT whose result is from 2^52 to 2^53 is not modelled by the local engine.")


def _refuse_power_beyond_1e15(node: Any, value: Any, held: Callable[[str], Any]) -> None:
    """INT, FLOOR, CEILING, QUOTIENT and CONVERT of a ^ or POWER result from 1E15 up to 2^53 (measured, Task 38): Power BI reads such a power as neither the exact
    binary value nor 15 digits (FLOOR(2^52,1) is 4503599627370500, INT(2^52-0.5) is 4503599627370495, CONVERT(2^52+1,INTEGER) is 4503599627370498): refused.
    From 2^53 up the double is exact and every measured answer (about 250 fresh ones) follows the binary value."""
    if isinstance(value, Decimal) and value.is_finite() and Decimal("1E15") <= abs(value) < 2 ** 53 and _has_power(node, held):
        raise dax_typed.refusal("A rounding to an integer of a power result from 1E15 to 2^53 is not modelled by the local engine.")


class _InexactPower(Exception):
    """A ^ or POWER inside a double expression whose exact value is not a double: Power BI's pow result cannot be reproduced."""


def _power_is_exact(base: float, exponent: float, result: float) -> bool:
    """True when base ^ exponent (an integer exponent) is exactly the double `result`, so any pow algorithm gives that same double."""
    from fractions import Fraction
    if exponent != int(exponent) or abs(exponent) > 1100 or not math.isfinite(result):
        return False
    try:
        return Fraction(base) ** int(exponent) == Fraction(result)
    except (ZeroDivisionError, OverflowError, ValueError):
        return False


def _double_arithmetic(node: Any, held: Callable[[str], Any], depth: int = 0) -> tuple[float, bool] | None:
    """The value of a constant expression of numbers, + - * / ^ and POWER computed in IEEE doubles, one rounding per operation, as Power BI does;
    returns (value, is_whole_number_literal_arithmetic) or None when the expression is anything else (a column, a function, text, a division by zero)."""
    if depth > 40 or not isinstance(node, tuple) or not node:
        return None
    kind = node[0]
    try:
        if kind == "number" and isinstance(node[1], Decimal) and node[1].is_finite():
            text = node[2] if len(node) > 2 and isinstance(node[2], str) else str(node[1])
            return float(node[1]), node[1] == node[1].to_integral_value() and not any(mark in text for mark in ".eE")
        if kind == "unary" and node[1] in {"+", "-"}:
            inner = _double_arithmetic(node[2], held, depth + 1)
            return None if inner is None else ((-inner[0] if node[1] == "-" else inner[0]), inner[1])
        if kind == "var" and len(node) > 1 and isinstance(node[1], str):
            return _double_arithmetic(held(node[1]), held, depth + 1)
        if kind == "binary" and node[1] in {"+", "-", "*", "/", "^"}:
            operands = (node[2], node[3])
            operator = node[1]
        elif kind == "call" and node[1] == "POWER" and len(node[2]) == 2:
            operands = (node[2][0], node[2][1])
            operator = "^"
        else:
            return None
        left, right = (_double_arithmetic(operand, held, depth + 1) for operand in operands)
        if left is None or right is None:
            return None
        a, b = left[0], right[0]
        if operator == "^":
            if a == int(a) and b == int(b) and 0 <= b <= 1100 and abs(a) <= 1e15:
                result = float(int(a) ** int(b))  # a whole power is the correctly rounded double (3^34 is ...568 though the C library's pow gives ...570)
            else:
                result = math.pow(a, b)
            if result and abs(result) >= 2 ** 53 and not _power_is_exact(a, b, result):
                raise _InexactPower()  # measured (Task 38 round 3): Power BI's own pow differs from the correctly rounded power by many ulps (INT(1.5^100), INT(13^17))
        elif operator == "/":
            result = a / b
        elif operator == "+":
            result = a + b
        elif operator == "-":
            result = a - b
        else:
            result = a * b
        if not math.isfinite(result):
            return None
        whole = left[1] and right[1] and operator in {"+", "-", "*"}
        if whole and abs(result) >= 2 ** 53:
            return None  # a sum of two Int64 values is an Int64 (it wraps), not a Double: not this rule
        return result, whole
    except (OverflowError, ZeroDivisionError, ValueError, MeasureError, KeyError, TypeError):
        return None


def _power_as_double(node: Any, value: Any, held: Callable[[str], Any]) -> Any:
    """Task 38 (measured, Power BI Desktop, about 1,150 fresh formulas): INT, CONVERT(.., INTEGER), QUOTIENT and MROUND read a power expression from 2^53 up as
    the double of the whole expression, every operation rounded to a double (INT(3^34+1) is 16677181699666568: 3^34 is 16677181699666568 as a double and the +1 does
    not survive; the engine's exact sum 16677181699666570 is wrong). An expression that cannot be computed in doubles here is refused when the exact value is not
    itself a double."""
    if not (isinstance(value, Decimal) and value.is_finite() and not dax_dates.is_date(value) and abs(value) >= 2 ** 53 and _has_power(node, held)):
        return value
    try:
        computed = _double_arithmetic(node, held)
    except _InexactPower:
        raise dax_typed.refusal("A power beyond 2^53 whose result is not exactly a double is not modelled by the local engine (Power BI's pow differs by many ulps).") from None
    if computed is None:
        if value != Decimal(float(value)):
            raise dax_typed.refusal("A power expression beyond 2^53 whose double arithmetic is not computable here is not modelled by the local engine.")
        return value
    if abs(computed[0]) < 2 ** 53:
        raise dax_typed.refusal("A power expression whose double and exact values straddle 2^53 is not modelled by the local engine.")
    return Decimal(computed[0])


def _read_double_as_integer_source(number: Decimal) -> Decimal:
    """How INT reads a finite Double (measured, Task 22 Part D): from 2^53 up its exact binary value (INT(9.223372036854775E18) is 9223372036854774784),
    below that a fraction is read at 15 significant digits (INT((0.1+2/3)*1E15) is 766666666666667, CEILING(4.5E15+0.5,1) is 4500000000000000)."""
    if abs(number) >= 2 ** 53:
        return Decimal(float(number))
    if number != number.to_integral_value():
        return Decimal(format(number, ".14e"))
    return number


def _scalar_math(function: str, values: list[Decimal | None]) -> Decimal | None:
    if function == "POWER":  # a failure of ^ or POWER is typed statically by a type test around it (see _StaticTypeFailure)
        try:
            return _scalar_math_checked(function, values)
        except MeasureRuntimeError as error:
            if all(value is None for value in values) or any(value is not None and not value.is_finite() for value in values):
                raise  # two BLANKs, or an Infinity or NaN operand: the error is not hidden from a type test
            failure = _PowerFailure(str(error))
            failure.zero_base = values[0] is not None and values[0] == 0 and (values[1] or Decimal(0)) <= 0
            raise failure from error
    return _scalar_math_checked(function, values)


def _scalar_math_checked(function: str, values: list[Decimal | None]) -> Decimal | None:
    result = _scalar_math_value(function, values)
    if result is None:
        return None
    if not result.is_finite():
        return result  # an Infinity argument that the function passes through (TRUNC)
    if function in {"INT", "FLOOR", "CEILING", "QUOTIENT", "MROUND"} and abs(result) >= _INT64_RANGE:
        if function in {"INT", "FLOOR", "CEILING"}:
            raise _IntegerRangeFailure("The result of a conversion or arithmetic operation is either too large or too small.")  # Part D: a type test of it is answered by its type
        raise MeasureRuntimeError("The result of a conversion or arithmetic operation is either too large or too small.")  # Part D: an Integer result beyond the 64-bit range is the error (IFERROR catches it)
    if function == "POWER" and result != 0 and abs(result) < _UNDERFLOW_DOUBLE:  # smaller than a Double can hold: 0 (the sign of a negative one is not measured)
        if result < 0:
            raise dax_typed.refusal("A negative POWER result below the Double range is not modelled by the local engine.")
        return Decimal(0)
    if result == 0 and function != "SQRT":
        return Decimal(0)  # no negative zero: Power BI shows 0 (Part B: SQRT(-(0.0)) is -0)
    if abs(result) > _DOUBLE_MAX:
        raise MeasureRuntimeError(f"{function} result is outside the supported numeric range.")
    return result


_UNDERFLOW_DOUBLE = Decimal("2.5E-324")  # Part B: half the smallest Double; a smaller product is a zero of its sign


def _checked_double(result: Decimal) -> Decimal:
    """A Double result: beyond the double range it is Infinity, below it a zero of the same sign (Part B)."""
    if not result.is_finite():
        return result
    if abs(result) < _UNDERFLOW_DOUBLE:
        return Decimal("-0") if result.is_signed() else Decimal(0)
    if abs(result) > _DOUBLE_MAX:
        return Decimal("Infinity") if result > 0 else Decimal("-Infinity")
    return result


def _format_tojson_double(val: Decimal) -> str:
    """A double cell of TOJSON (live Power BI, iteration 94): the shortest digits that read back as the double, cut (not
    rounded) after 4 decimals with at least one kept ("0.3", "1.0", "-0.0"); from 1e21 on an exponent form ("1.5e300")."""
    double = float(val)
    if abs(double) >= 1e15 and double != int(double):
        raise MeasureError("A fractional double of 1E15 or more is not modelled in the local engine.")
    if abs(double) >= 1e21:
        shortest = repr(double)
        # live Power BI (728 probes): when the shortest decimal lies (almost) exactly halfway between two doubles (1E23, 7E22, 5.55E21)
        # it prints the neighbouring double's digits (9.999999999999999e22); those values are refused
        tie_distance = abs(abs(Decimal(shortest) - Decimal(double)) / Decimal(math.ulp(double)) - Decimal("0.5"))
        if tie_distance < Decimal("0.003"):
            raise MeasureError("A double next to a rounding tie prints other digits in Power BI; that is not modelled in the local engine.")
        mantissa, _, exponent = shortest.partition("e")
        return f"{mantissa}e{int(exponent)}"  # 1.5e300, 1e21: no plus sign, no padding
    text = format(Decimal(repr(double)), "f")
    if text.startswith("-") and not double:
        text = "-0"
    whole, _, fraction = text.partition(".")
    return f"{whole}.{fraction[:4].rstrip('0') or '0'}"


# Column types the declared type of a loaded column or the static type of a computed one say something sure about.
_NUMERIC_KIND_BY_COLUMN_TYPE = {
    "whole_number": "int64", "int64": "int64", "integer": "int64",
    "decimal_number": "double", "double": "double",
    "currency": "currency", "fixed_decimal": "currency",
}
_CURRENCY_MAX = Decimal("922337203685477.5807")  # a Currency is an Int64 of ten-thousandths
_TOCSV_CONSTANT_TABLES = frozenset({"ROW", "DATATABLE", "GENERATESERIES", "CALENDAR", "CALENDARAUTO"}) | _INFO_FUNCTIONS
_TOCSV_DICTIONARY_TABLES = frozenset({"ALL", "ALLNOBLANKROW", "ALLSELECTED", "ALLEXCEPT"})  # FILTERS (Power BI sorts it) is refused; TREATAS is checked in _tocsv_row_order
_TOCSV_JOIN_TABLES = frozenset({"EXCEPT", "INTERSECT", "CROSSJOIN", "NATURALINNERJOIN", "NATURALLEFTOUTERJOIN", "GENERATE", "GENERATEALL"})
_TOCSV_SIGNED_ZERO_CALLS = frozenset({"CEILING", "FLOOR", "ISO.CEILING", "TRUNC", "ROUNDUP", "ROUNDDOWN", "DIVIDE", "POWER", "MOD"})


def _swi_tied_order_known(node: tuple[Any, ...], lookup: Any) -> bool:
    """True for an index table whose own row order (what breaks ties between equal order values) was checked against Power BI:
    the distinct values of one column, and FILTER / ADDCOLUMNS / CALCULATETABLE / SUMMARIZE / EXCEPT / INTERSECT / CROSSJOIN of those."""
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind == "var":
        held = lookup(node[1])
        return held is not None and _swi_tied_order_known(held, lookup)
    if kind == "table_call" and node[1] in {"VALUES", "DISTINCT"}:
        return node[2][0] == "reference"
    if kind == "call":
        function, arguments = node[1], node[2]
        if function in {"DATATABLE", "ROW"}:
            return True
        if function in {"TOPN", "SAMPLE", "SUMMARIZECOLUMNS"}:
            return False
        if function in {"ALL", "ALLNOBLANKROW"}:
            return len(arguments) == 1 and arguments[0][0] == "reference"
        if function in {"FILTER", "ADDCOLUMNS", "CALCULATETABLE", "TREATAS"} and arguments:
            return _swi_tied_order_known(arguments[0], lookup)
        if function in {"SUMMARIZE", "GROUPBY"} and len(arguments) >= 2 and arguments[0][0] == "table":
            return sum(1 for argument in arguments[1:] if argument[0] == "reference") == 1
        if function in {"EXCEPT", "INTERSECT", "NATURALINNERJOIN", "CROSSJOIN"} and arguments:
            return _swi_tied_order_known(arguments[0], lookup)
        if function in {"VALUES", "DISTINCT"} and arguments:
            return len(arguments) == 1 and arguments[0][0] == "reference"
    return False


def _sc_pure_aggregate(node: Any) -> bool:
    """An expression Power BI computes in the one grouping query that also builds the subtotals (live Power BI, Part C review): it is
    BLANK when the aggregates in it are. A plain aggregate of a column, COUNTROWS / an iterator over the plain table (or a FILTER of
    it), ABS / ROUND / minus of such an aggregate, * and / with a number, and + - * of two of them. x + 1, an IF, a comparison, a
    text join or a constant is never BLANK for a group without rows and is built another way."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "unary" and node[1] == "-":
        return _sc_pure_aggregate(node[2])
    if node[0] == "binary":
        left, right = node[2], node[3]
        if node[1] in {"+", "-"}:
            return _sc_pure_aggregate(left) and _sc_pure_aggregate(right)
        if node[1] == "*":
            return (_sc_pure_aggregate(left) and (_sc_pure_aggregate(right) or right[0] == "number")) or (left[0] == "number" and _sc_pure_aggregate(right))
        if node[1] == "/":
            return _sc_pure_aggregate(left) and (_sc_pure_aggregate(right) or right[0] == "number")
        return False
    if node[0] != "call":
        return False
    name, arguments = node[1], node[2]
    if name in {"SUM", "COUNT", "MIN", "MAX", "AVERAGE"}:
        return len(arguments) == 1 and arguments[0][0] == "reference" and bool(arguments[0][1])
    if name == "COUNTROWS":
        return len(arguments) == 1 and _rollup_expression_ok(node) and (arguments[0][0] == "table" or arguments[0][1] == "FILTER")
    if name in {"SUMX", "AVERAGEX", "MAXX", "MINX", "COUNTX"}:
        if not (_rollup_expression_ok(node) and len(arguments) == 2):
            return False
        body = arguments[1]
        return body[0] == "reference" or (
            body[0] == "binary" and body[1] == "*" and {body[2][0], body[3][0]} <= {"reference", "number"} and "reference" in {body[2][0], body[3][0]}
        )
    if name == "ABS":
        return len(arguments) == 1 and _sc_pure_aggregate(arguments[0])
    if name == "ROUND":
        return len(arguments) == 2 and _sc_pure_aggregate(arguments[0]) and arguments[1][0] == "number"
    if name == "DIVIDE":
        return len(arguments) == 2 and _sc_pure_aggregate(arguments[0]) and (_sc_pure_aggregate(arguments[1]) or arguments[1][0] == "number")
    return False


def _sc_rollup_order_rule(expressions: list[Any]) -> str:
    """How SUMMARIZECOLUMNS orders the subtotal rows of ROLLUPADDISSUBTOTAL (live Power BI, Part C review): "first" lists each
    subtotal level in the order its combinations first appear in the detail rows (all expressions are aggregates the grouping query
    computes in one pass); "dictionary" lists each level on its own in dictionary order (no expression, or expressions evaluated per
    level). Anything that reads the filter state of a group column changes the order of the detail rows too and is refused."""
    for expression in expressions:
        if not _rollup_expression_ok(expression) or _contains_function_call(expression, "ISSUBTOTAL"):
            raise MeasureError("Subtotal rows of SUMMARIZECOLUMNS are modelled only for aggregate expressions (SUM, COUNTROWS, MIN, MAX, AVERAGE ...).")
        if any(_contains_function_call(expression, name) for name in ("DISTINCTCOUNT", "COUNTA", "COUNTBLANK")):
            raise MeasureError("The row order of DISTINCTCOUNT / COUNTA / COUNTBLANK beside ROLLUPADDISSUBTOTAL is not modelled in the local engine.")
        if expression[0] == "call" and expression[1] == "IF" and expression[2] and expression[2][0][0] == "boolean":
            raise MeasureError("IF with a constant condition beside ROLLUPADDISSUBTOTAL is not modelled in the local engine.")
    return "first" if any(_sc_pure_aggregate(expression) for expression in expressions) else "dictionary"


_ROLLUP_AGGREGATES = frozenset({"SUM", "COUNT", "COUNTA", "COUNTBLANK", "MIN", "MAX", "AVERAGE", "DISTINCTCOUNT"})
_ROLLUP_ITERATORS = frozenset({"SUMX", "AVERAGEX", "MINX", "MAXX", "COUNTX", "COUNTAX"})
_ROLLUP_SCALARS = frozenset({"IF", "DIVIDE", "ABS", "ROUND", "NOT", "BLANK", "AND", "OR", "ISSUBTOTAL"})


def _rollup_expression_ok(node: Any, in_row: bool = False, in_iterator: bool = False) -> bool:
    """True for an expression added by SUMMARIZE ... ROLLUP whose subtotal values were measured against live Power BI (Part C review):
    aggregates of a column, COUNTROWS / iterators over the plain table or a FILTER of it, arithmetic, comparisons and IF over those, and
    ISSUBTOTAL outside any iterator. An expression that reads the filter state of a group column (SELECTEDVALUE, VALUES, ISINSCOPE,
    ISFILTERED, HASONEVALUE ...) or a measure is answered differently on subtotal rows and is refused."""
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind in {"number", "string", "boolean", "blank"}:
        return True
    if kind == "reference":
        return in_row and bool(node[1])
    if kind in {"binary", "comparison", "logical"}:
        return _rollup_expression_ok(node[2], in_row, in_iterator) and _rollup_expression_ok(node[3], in_row, in_iterator)
    if kind == "concat":
        return _rollup_expression_ok(node[1], in_row, in_iterator) and _rollup_expression_ok(node[2], in_row, in_iterator)
    if kind == "unary":
        return _rollup_expression_ok(node[2], in_row, in_iterator)
    if kind != "call":
        return False
    name, arguments = node[1], node[2]

    def plain_table(table: Any) -> bool:
        if table[0] == "table":
            return True
        return (
            table[0] == "call" and table[1] == "FILTER" and len(table[2]) == 2 and table[2][0][0] == "table"
            and _rollup_expression_ok(table[2][1], True, True)
        )

    if in_iterator:
        return name in {"IF", "DIVIDE", "ABS", "ROUND", "NOT", "BLANK", "AND", "OR"} and all(_rollup_expression_ok(a, in_row, True) for a in arguments)
    if name in _ROLLUP_AGGREGATES:
        return len(arguments) == 1 and arguments[0][0] == "reference" and bool(arguments[0][1])
    if name == "COUNTROWS":
        return not arguments or (len(arguments) == 1 and plain_table(arguments[0]))
    if name in _ROLLUP_ITERATORS:
        return len(arguments) == 2 and plain_table(arguments[0]) and _rollup_expression_ok(arguments[1], True, True)
    if name == "ISSUBTOTAL":
        return len(arguments) == 1 and arguments[0][0] == "reference" and bool(arguments[0][1])
    if name in _ROLLUP_SCALARS:
        return all(_rollup_expression_ok(a, in_row, False) for a in arguments)
    return False


def _rollup_issubtotal_columns(node: Any) -> list[str]:
    """The column names every ISSUBTOTAL call inside the expression names."""
    found: list[str] = []
    if isinstance(node, tuple) and node:
        if node[0] == "call" and node[1] == "ISSUBTOTAL" and node[2] and node[2][0][0] == "reference":
            found.append(str(node[2][0][2]))
        for child in node:
            if isinstance(child, tuple):
                found.extend(_rollup_issubtotal_columns(child))
            elif isinstance(child, list):
                for item in child:
                    found.extend(_rollup_issubtotal_columns(item))
    return found


def _tocsv_inline_vars(node: tuple[Any, ...]) -> tuple[Any, ...]:
    """A VAR block (kind "let") written out: its RETURN with every VAR replaced by the expression it holds, so the rows keep
    the order the held table expression has on its own. Later VARs may read earlier ones."""
    while isinstance(node, tuple) and node and node[0] == "let":
        held: dict[str, tuple[Any, ...]] = {}
        for name, value in node[1]:
            held[str(name)] = _replace_held(value, held)
        node = _replace_held(node[2], held)
    return node


def _tocsv_row_order(node: tuple[Any, ...]) -> str:
    """How Power BI orders the rows TOCSV / TOJSON print for a table expression (live probes, iteration 94).

    "constant", "dictionary", "grouped": the order the local engine produces already (cells built from constants, the
    distinct values of a column, the groups of SUMMARIZE). "scan": the rows of a loaded table in storage order, but
    REVERSED once a filter has removed rows. "scan_forward": ADDCOLUMNS over a whole loaded table (never reversed).
    "projection": SELECTCOLUMNS of plain columns, "topn": TOPN of a loaded table; both are checked further when the rows are
    known. Every other table expression raises: its order is not modelled."""
    kind = node[0]
    if kind == "let":
        # a VAR block orders its rows like the RETURN expression with every VAR replaced by the expression it holds
        inner_order = _tocsv_row_order(_tocsv_inline_vars(node))  # raises for a table whose row order is not modelled
        if inner_order == "scan":
            return "constant"  # live Power BI: a VAR-held scan or FILTER of a loaded table comes back in storage order, never reversed
        if inner_order in {"constant", "dictionary", "grouped"}:
            return inner_order
        raise MeasureError("The row order of a VAR-held table of this kind is not modelled in the local engine, so TOCSV / TOJSON refuse it.")
    if kind == "table":
        return "scan"
    if kind == "tableconstructor":
        if _tocsv_is_constant(node):  # a member that reads data (SUM(...)) makes Power BI sort the rows
            return "constant"
    elif kind == "table_call" and node[1] in {"VALUES", "DISTINCT"}:
        source = node[2]
        if source[0] == "table":
            return "scan" if node[1] == "VALUES" else "dictionary"
        if source[0] == "reference":
            return "dictionary"
    elif kind == "call":
        function, arguments = node[1], node[2]
        if function == "EVALUATEANDLOG" and arguments:
            return _tocsv_row_order(arguments[0])
        if function == "GENERATESERIES":
            def adds_exactly(operand: tuple[Any, ...]) -> bool:  # a whole number or a literal a double holds exactly (0.5, 1.5, 0.25)
                return _static_numeric_type(operand) == "int64" or (operand[0] == "number" and Decimal(float(operand[1])) == operand[1])

            first_type = _static_numeric_type(arguments[0]) if arguments else None
            if first_type == "datetime" or (arguments and adds_exactly(arguments[0]) and (len(arguments) < 3 or adds_exactly(arguments[2]))):
                return "constant"  # live Power BI adds a fractional step in a double (0.1, 0.2, then 0.30000000000000004 passes 0.3)
        elif function in _TOCSV_CONSTANT_TABLES:
            return "constant"
        elif function == "TREATAS" and len(arguments) >= 2 and arguments[0][0] == "tableconstructor" and _tocsv_is_constant(arguments[0]):
            members = [repr(member) for member in arguments[0][1]] if isinstance(arguments[0][1], (list, tuple)) else None
            if members is not None and len(members) == len(set(members)):
                return "dictionary"  # live Power BI keeps a repeated member as a repeated row; the local engine would merge them
        elif function in _TOCSV_DICTIONARY_TABLES:
            if function != "ALLEXCEPT" and len(arguments) > 1:
                raise MeasureError("The row order of a table of several columns is not modelled in the local engine, so TOCSV / TOJSON refuse it.")  # Power BI lists their combinations like SUMMARIZE
            return "dictionary"
        if function in {"FILTER", "CALCULATETABLE"} and arguments:
            if arguments[0][0] == "call" and arguments[0][1] in {"ALL", "ALLNOBLANKROW"} and len(arguments[0][2]) == 1 and arguments[0][2][0][0] == "table":
                return "scan"  # live Power BI: FILTER(ALL(table), condition) comes back in reverse storage order like FILTER(table, condition)
            base = _tocsv_row_order(arguments[0])
            if base in {"scan", "constant", "dictionary", "grouped"}:
                return base
        elif function == "SUMMARIZE" and not _contains_function_call(node, "CALCULATE") and (
            arguments[0][0] == "table" or not any(argument[0] == "string" for argument in arguments[1:])
        ):
            return "grouped"  # over a FILTER the local engine computes the added columns on the unfiltered rows, so only a bare table is trusted with them  # CALCULATE in a computed column intersects the group's filter in Power BI, not replaces it as the local engine does
        elif function == "SUMMARIZECOLUMNS" and any(
            isinstance(arg, tuple) and arg[0] == "call" and arg[1] == "ROLLUPADDISSUBTOTAL"
            for arg in arguments
        ):
            return "grouped"
        elif function == "ADDCOLUMNS" and arguments:
            base = _tocsv_row_order(arguments[0])
            if base == "scan" and arguments[0][0] == "table":
                return "scan_forward"
            if base in {"constant", "dictionary", "grouped", "scan_forward"}:
                return base
        elif function == "SUBSTITUTEWITHINDEX" and arguments:
            base = _tocsv_row_order(arguments[0])
            if arguments[0][0] == "call" and arguments[0][1] in _TOCSV_DICTIONARY_TABLES and len(arguments[0][2]) != 1:
                raise MeasureError("The row order of this table expression is not modelled in the local engine, so TOCSV / TOJSON refuse it.")
            if base in {"constant", "dictionary", "grouped", "scan_forward", "scan"}:
                return base
        elif function == "ADDMISSINGITEMS" and arguments:
            # the table keeps its own row order and the missing rows follow it (live Power BI, iteration 96): only a table whose own order is modelled
            inner = next((argument for argument in arguments if argument[0] != "reference"), None)
            if inner is not None and _tocsv_row_order(inner) in {"dictionary", "grouped"}:
                return "grouped"
        elif function == "SELECTCOLUMNS" and len(arguments) >= 3 and len(arguments) % 2 == 1 and arguments[0][0] == "table":
            references = [(argument[1] or "").casefold() + "\0" + str(argument[2]).casefold() for argument in arguments[2::2] if argument[0] == "reference"]
            if all(argument[0] == "string" for argument in arguments[1::2]) and len(references) == len(arguments[2::2]) == len(set(references)):
                return "projection"  # distinct plain columns: selecting one twice makes Power BI group the rows  # columns named in pairs; a constant beside them makes Power BI sort the rows
        elif function == "TOPN" and len(arguments) == 3 and arguments[0][0] == "number" and arguments[2][0] == "reference":
            if arguments[1][0] == "table" or (arguments[1][0] == "table_call" and arguments[1][1] == "VALUES" and arguments[1][2][0] == "reference"):
                return "topn"
        elif function == "UNION" and arguments and all(_tocsv_row_order(argument) == "constant" for argument in arguments) and not _tocsv_contains_blank(node):
            return "constant"  # a BLANK() cell makes Power BI read a date or TRUE() beside it as a number
        elif function in _TOCSV_JOIN_TABLES and arguments and all(_tocsv_row_order(argument) in {"constant", "dictionary", "grouped"} for argument in arguments):
            return "grouped"
    raise MeasureError("The row order of this table expression is not modelled in the local engine, so TOCSV / TOJSON refuse it.")


def _tocsv_scan_table_node(node: tuple[Any, ...]) -> tuple[tuple[Any, ...], bool]:
    """(the loaded table a "scan" expression reads, whether it was reached through ALL): a bare table, VALUES of it, or FILTER /
    CALCULATETABLE over either, or over ALL(table), which ignores the filters around it."""
    via_all = False
    while node[0] == "call" and node[1] in {"FILTER", "CALCULATETABLE", "EVALUATEANDLOG"} and node[2]:
        node = node[2][0]
    if node[0] == "call" and node[1] in {"ALL", "ALLNOBLANKROW"}:
        node, via_all = node[2][0], True
    if node[0] == "table_call" and node[1] == "VALUES":
        node = node[2]
    return node, via_all


def _tocsv_mentions_column(node: Any) -> bool:
    if not isinstance(node, tuple):
        return False
    if node and node[0] == "reference":
        return True
    return any(
        _tocsv_mentions_column(child) if isinstance(child, tuple) and child and isinstance(child[0], str)
        else any(_tocsv_mentions_column(item) for item in child) if isinstance(child, (tuple, list)) else False
        for child in node[1:]
    )


def _tocsv_contains_blank(node: Any) -> bool:
    if not isinstance(node, tuple):
        return False
    if node and node[0] in {"blank", "blank_comment"}:
        return True
    return any(
        _tocsv_contains_blank(child) if isinstance(child, tuple) and child and isinstance(child[0], str)
        else any(_tocsv_contains_blank(item) for item in child) if isinstance(child, (tuple, list)) else False
        for child in node[1:]
    )


def _tocsv_scan_filtered(node: tuple[Any, ...]) -> bool:
    """True when FILTER / CALCULATETABLE around a loaded table apply a real condition (live Power BI, iteration 94: that makes the
    scan come back reversed even when the condition keeps every row, while FILTER(table, TRUE()) is no filter at all).
    Conditions this cannot classify raise: their effect on the order is not modelled."""
    filtered = False
    while True:
        if node[0] == "call" and node[1] == "EVALUATEANDLOG" and node[2]:
            node = node[2][0]
        elif node[0] == "call" and node[1] == "FILTER" and len(node[2]) == 2:
            condition = node[2][1]
            if condition == ("boolean", False) or (condition != ("boolean", True) and _tocsv_mentions_column(condition)):
                filtered = True
            elif condition != ("boolean", True):
                raise MeasureError("The row order of FILTER with a constant condition is not modelled in the local engine.")
            node = node[2][0]
        elif node[0] == "call" and node[1] == "CALCULATETABLE" and node[2]:
            for modifier in node[2][1:]:
                if modifier[0] in {"comparison", "logical", "in", "not"} or (modifier[0] == "call" and modifier[1] == "NOT"):
                    filtered = True
                else:
                    raise MeasureError("The row order of CALCULATETABLE with this filter argument is not modelled in the local engine.")
            node = node[2][0]
        else:
            return filtered


def _literal_double(node: Any) -> float | None:
    """The double Power BI computes for constant arithmetic on literals (0.1+0.7 is 0.7999999999999999); None for anything else."""
    if not isinstance(node, tuple) or not node:
        return None
    if node[0] == "number":
        return float(node[1])
    if node[0] == "unary" and node[1] in {"+", "-"}:
        operand = _literal_double(node[2])
        return None if operand is None else -operand if node[1] == "-" else operand
    if node[0] == "binary" and node[1] in {"+", "-", "*", "/"}:
        left, right = _literal_double(node[2]), _literal_double(node[3])
        if left is None or right is None or (node[1] == "/" and right == 0):
            return None
        result = left + right if node[1] == "+" else left - right if node[1] == "-" else left * right if node[1] == "*" else left / right
        return result if math.isfinite(result) else None
    return None


def _tocsv_has_signed_zero_risk(node: Any, allowed: tuple[Any, ...] = ()) -> bool:
    """True when an arithmetic step in the expression could hand Power BI a negative zero (it prints -0 for a double)
    that the local decimals carry as 0. `allowed` lists the literal "-0.0" nodes the caller handles itself."""
    if not isinstance(node, tuple):
        return False
    if any(node is item for item in allowed):
        return False
    if node and node[0] in {"binary", "unary"}:
        return True
    if node and node[0] == "call" and node[1] in _TOCSV_SIGNED_ZERO_CALLS:
        return True
    return any(
        _tocsv_has_signed_zero_risk(child, allowed) if isinstance(child, tuple) else any(_tocsv_has_signed_zero_risk(item, allowed) for item in child)
        for child in node if isinstance(child, (tuple, list))
    )


_NON_CONSTANT_CALLS = frozenset({
    "CALCULATE", "CALCULATETABLE", "LOOKUPVALUE", "SELECTEDVALUE", "RELATED", "RELATEDTABLE", "COUNTROWS", "ISBLANK", "USERNAME", "USERPRINCIPALNAME",
    "NOW", "TODAY", "UTCNOW", "UTCTODAY", "RAND", "RANDBETWEEN",
})


def _tocsv_is_constant(node: Any, bound: frozenset[str] = frozenset()) -> bool:
    """True when the expression reads no table, column, measure or the clock: Power BI folds such a delimiter at compile time.
    A variable counts when it is bound inside the expression itself (VAR d = "," RETURN d)."""
    if not isinstance(node, tuple) or not node:
        return True
    kind = node[0]
    if kind in {"reference", "table", "table_call", "tablevalue", "tablecapture", "measure", "omitted"}:
        return False
    if kind == "var":
        return str(node[1]) in bound
    if kind == "let":
        inner = bound | {str(name) for name, _value in node[1]}
        return all(_tocsv_is_constant(value, bound) for _name, value in node[1]) and _tocsv_is_constant(node[2], inner)
    if kind == "call" and (
        node[1] in _AGGREGATING_CALLS or node[1] in _TABLE_FUNCTION_ARITY or node[1] in _ALL_ITERATORS or node[1] in _NON_CONSTANT_CALLS
    ):
        return False
    return all(
        _tocsv_is_constant(child, bound) if isinstance(child, tuple) and child and isinstance(child[0], str)
        else all(_tocsv_is_constant(item, bound) for item in child) if isinstance(child, (tuple, list)) else True
        for child in node[1:]
    )


def _datatable_cell_is_literal(node: Any) -> bool:
    """A DATATABLE cell Power BI accepts: a literal (not an expression, not even in parentheses)."""
    while isinstance(node, tuple) and node and node[0] == "unary" and node[1] in {"+", "-"} and node[2][0] == "number":
        node = node[2]
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] in {"number", "string", "boolean", "blank", "blank_comment"}:
        return True
    return node[0] == "table" and str(node[1]).upper() in {"TRUE", "FALSE"}


def _tocsv_max_rows(node: tuple[Any, ...]) -> int:
    """The row limit a literal second argument of TOCSV / TOJSON stands for (live Power BI, iteration 94).

    Only literals are constants for Power BI: a number, text, TRUE() / FALSE(), BLANK() or a sign in front of a number.
    A number rounds half away from zero, a text half to even; TRUE() is -1 (every row), BLANK() is 0, a value beyond
    Int64 is an error. A negative limit means every row."""
    sign = 1
    while node[0] == "unary" and node[1] in {"+", "-"}:
        sign *= -1 if node[1] == "-" else 1
        node = node[2]
    if node[0] == "blank" and sign == 1:
        return 0
    if node[0] == "boolean" and sign == 1:
        return -1 if node[1] else 0
    if node[0] == "number":
        literal = node[2] if len(node) > 2 and isinstance(node[2], str) else None
        value = node[1] * sign
        exact_integer = literal is not None and literal.isdigit()  # an Int64 literal compares exactly, anything else as a double
        if exact_integer:
            rounded = value
        else:
            double = float(value)
            if not -(2.0 ** 63) <= double < 2.0 ** 63:
                raise MeasureError("The following system error occurred: Out of present range. ")
            if -1 < double < 0:
                raise MeasureError("A row limit between -1 and 0 is not modelled in the local engine.")  # live Power BI: every row for a loaded table, none for a ROW
            rounded = Decimal(-1) if double < 0 else Decimal(math.floor(double + 0.5))  # half up on the double: 0.49999999999999994 gives 1
    elif node[0] == "string" and sign == 1:
        text = str(node[1]).strip()
        if not re.fullmatch(r"[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]+)?", text):
            raise MeasureError("The following system error occurred: Type mismatch. ")
        rounded = Decimal(text).to_integral_value(rounding=ROUND_HALF_EVEN)
    else:
        raise MeasureError("TOCSV / TOJSON expect a constant as argument number 2.")
    if not -(2 ** 63) <= rounded < 2 ** 63:
        raise MeasureError("The following system error occurred: Out of present range. ")
    return int(rounded)


def _power(base: Decimal | None, exponent: Decimal | None) -> Decimal | None:
    """The ^ operator: POWER's rules, BLANK()^n is blank and n^BLANK() is 1."""
    return _scalar_math("POWER", [base, exponent])


def _held_runtime_failure(error: MeasureError) -> MeasureError:
    """Part B: a runtime error, or a used VAR's thrown runtime error, that * and / hold until a BLANK operand decides the result; any other refusal propagates."""
    if isinstance(error, _HardError) and not isinstance(error.__cause__, MeasureRuntimeError):
        raise error
    return error


_DATA_READING_CALLS = (_AGGREGATING_CALLS - {"CALCULATE"}) | _ITERATOR_CALLS | {"AND", "OR", "RELATED", "RELATEDTABLE", "LOOKUPVALUE"}
# Task 20 Part A: the functions whose result can never be BLANK, and the argument that decides it. Measured in Power BI Desktop.
_NEVER_BLANK_ALWAYS = frozenset({
    "EXP", "LN", "LOG", "LOG10", "NOT", "AND", "OR", "ISBOOLEAN", "ISCURRENCY", "ISDATETIME", "ISDECIMAL", "ISDOUBLE", "ISERROR",
    "ISINT64", "ISINTEGER", "ISLOGICAL", "ISNONTEXT", "ISNUMBER", "ISNUMERIC", "ISSTRING", "ISTEXT", "PI", "RAND", "NOW", "TODAY",
    "UTCNOW", "UTCTODAY", "TRUE", "FALSE", "USERNAME", "USERPRINCIPALNAME", "USERCULTURE", "CONTAINSSTRING", "CONTAINSSTRINGEXACT",
    "EXACT", "FIND", "SEARCH", "FORMAT", "ISAFTER", "ISONORAFTER", "PATHCONTAINS", "RANDBETWEEN", "EFFECT", "NOMINAL", "COUPDAYBS",
    "COUPDAYS", "COUPDAYSNC", "COUPNCD", "COUPNUM", "COUPPCD", "PDURATION", "RRI", "SLN", "TBILLEQ", "TBILLPRICE", "TBILLYIELD", "RATE",
    "INTRATE", "PRICEDISC", "RECEIVED", "SYD", "YIELDDISC", "ACCRINTM", "DB", "DDB", "DISC", "MDURATION", "PRICEMAT", "VDB", "YIELDMAT",
    "CUMIPMT", "CUMPRINC", "YIELD", "AMORDEGRC", "AMORLINC", "ODDLPRICE", "ODDLYIELD", "ACCRINT", "DURATION", "PRICE", "ODDFPRICE", "ODDFYIELD",
})
_NEVER_BLANK_FIRST_ARGUMENT = frozenset({
    "ABS", "CURRENCY", "DATEVALUE", "DAY", "FIXED", "HOUR", "INT", "ISO.CEILING", "LEFT", "LEN", "LOWER", "MINUTE", "MONTH", "PATHLENGTH",
    "QUARTER", "RIGHT", "SECOND", "SIGN", "SQRT", "TIMEVALUE", "TRIM", "TRUNC", "UNICHAR", "UPPER", "VALUE", "WEEKDAY", "WEEKNUM", "YEAR",
    "CEILING", "DOLLARDE", "DOLLARFR", "EDATE", "EOMONTH", "FLOOR", "MOD", "MROUND", "POWER", "QUOTIENT", "REPT", "ROUND", "ROUNDDOWN",
    "ROUNDUP", "YEARFRAC", "MID", "SUBSTITUTE",
})
_NEVER_BLANK_ANY_ARGUMENT = frozenset({"CONCATENATE", "DATE", "TIME"})
_NEVER_BLANK_THIRD_ARGUMENT = frozenset({"PMT", "PV", "NPER", "FV"})
_NEVER_BLANK_ALL_ARGUMENTS = frozenset({"MAX", "MIN", "ISPMT", "PPMT", "IPMT", "REPLACE"})


def _has_table_operand(node: Any) -> bool:
    """True when a table expression occurs anywhere in this node (a table is an error as a logical or comparison operand)."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] in {"table", "table_call", "tablevalue", "tablecapture", "tableconstructor"}:
        return True
    if node[0] == "call" and node[1] in (_AGGREGATING_CALLS - {"CALCULATE"}) | _ITERATOR_CALLS:
        return False  # Task 37: the table inside COUNTROWS(Facts) or SUMX(...) is that call's argument; the call gives a scalar, not a table operand
    children = node if isinstance(node[0], tuple) else node[1:]
    return any(_has_table_operand(child) for child in children if isinstance(child, tuple))


def _never_blank(node: Any) -> bool:
    """Task 19 Part C: True when the expression can never be a BLANK, so ISBLANK answers False without evaluating it.

    Static, on the parsed node. A VAR is not followed here; ISBLANK resolves an argument that is exactly a VAR first.
    """
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind in {"number", "string", "boolean"}:
        return True
    if kind == "in":
        return True  # Task 20 Part A: x IN {..} is never BLANK, like a comparison
    if _is_pure_logical(node) or kind == "comparison":
        return not _has_table_operand(node)  # Task 19 Part F: a logical operator, AND, OR, NOT and a comparison are never BLANK (a table operand is an error)
    if kind == "unary":
        return _never_blank(node[2])  # Task 19 Part F: a sign is judged by its operand
    if kind == "call":
        function, arguments = node[1], node[2]
        if function in _NEVER_BLANK_ALWAYS:
            return True
        if function in _NEVER_BLANK_FIRST_ARGUMENT and arguments:
            return _never_blank(arguments[0])
        if function in _NEVER_BLANK_ANY_ARGUMENT and arguments:
            return any(_never_blank(argument) for argument in arguments)
        if function in _NEVER_BLANK_THIRD_ARGUMENT and len(arguments) >= 3:
            return _never_blank(arguments[2])
        if function in _NEVER_BLANK_ALL_ARGUMENTS and arguments:
            return all(_never_blank(argument) for argument in arguments)
        if function == "IF" and len(arguments) == 3:
            return _never_blank(arguments[1]) and _never_blank(arguments[2])  # the condition is not looked at
        return False
    if kind == "concat":
        return _never_blank(node[1]) or _never_blank(node[2])
    if kind == "binary":
        operator, left, right = node[1], node[2], node[3]
        if operator in {"+", "-"}:
            return _never_blank(left) or _never_blank(right)
        if operator == "*":
            return _never_blank(left) and _never_blank(right)
        if operator in {"/", "^"}:
            return _never_blank(left)  # Task 20 Part A: a power is judged by its base (measured: (1/0)^(FACT(-1)) is False, (DIVIDE(1,0))^("a"*2) is an error)
    return False


def _is_datetime_conversion(node: Any) -> bool:
    return (isinstance(node, tuple) and len(node) == 3 and node[0] == "call" and node[1] == "CONVERT" and len(node[2]) == 2
            and node[2][1][0] == "table" and str(node[2][1][1]).upper() == "DATETIME")


def _currency_divisions(node: Any, currency_typed: Callable[[Any], bool]) -> list[tuple[Any, ...]]:
    """The divisions inside this node whose numerator is a Currency that reads data and whose divisor is not a Currency: Power BI raises
    their division by zero even where ISBLANK skips the rest (Task 19 Part C). A division that can itself never be BLANK (its numerator cannot)
    is skipped like any other never-blank part."""
    found: list[tuple[Any, ...]] = []
    if not isinstance(node, tuple) or not node:
        return found
    if node[0] == "binary" and node[1] == "/" and currency_typed(node[2]) and not currency_typed(node[3]) and any(True for _ in _iter_reference_nodes(node[2])) and not _never_blank(node):
        found.append(node)
    children = node if isinstance(node[0], tuple) else node[1:]
    for child in children:
        found.extend(_currency_divisions(child, currency_typed))
    return found


def _is_bare_power(node: Any) -> bool:
    """The expression is one ^ or POWER of plain operands, signs aside."""
    def divides_or_powers(part: Any) -> bool:
        if not isinstance(part, tuple) or not part:
            return any(divides_or_powers(item) for item in part) if isinstance(part, (list, tuple)) else False
        return (part[0] == "binary" and part[1] in {"/", "^"}) or (part[:2] == ("call", "POWER")) or any(divides_or_powers(item) for item in part)

    while node[0] == "unary" and node[1] in {"+", "-"}:
        node = node[2]
    if node[0] == "binary" and node[1] == "^":
        return not divides_or_powers(node[2:4])  # measured: ISNUMBER(1.5^0.0^-1) and ISNUMBER(0^(BLANK()/2)) are errors
    return node[0] == "call" and node[1] == "POWER" and not divides_or_powers(node[2])


def _is_bare_let_var(node: Any) -> bool:
    """True if node is a bare let returning a var (e.g. VAR y = ... RETURN y) or a bare var."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "let":
        return _is_bare_let_var(node[2])
    return node[0] == "var"


def _has_bare_error(node: Any) -> bool:
    """True if node contains a call to ERROR."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] == "ERROR":
        return True
    return any(_has_bare_error(c) for c in (node[1:] if isinstance(node[0], str) else node))


def _has_call_outside_let(node: Any, call_names: set[str] | frozenset[str]) -> bool:
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "let":
        return _has_call_outside_let(node[2], call_names)
    if node[0] == "call" and len(node) > 1 and node[1] in call_names:
        return True
    return any(_has_call_outside_let(c, call_names) for c in (node[1:] if isinstance(node[0], str) else node))


def _has_op_outside_let(node: Any, ops: set[str] | frozenset[str]) -> bool:
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "let":
        return _has_op_outside_let(node[2], ops)
    if node[0] == "binary" and len(node) > 1 and node[1] in ops:
        return True
    return any(_has_op_outside_let(c, ops) for c in (node[1:] if isinstance(node[0], str) else node))


def _reads_no_data(node: Any, held: Callable[[str], Any], seen: frozenset[str] = frozenset()) -> bool:
    """Corrections rule 1: True when an operand reads no data (BLANK(), IF(1=2,1), ABS(BLANK()), CALCULATE(BLANK()), a VAR of those).

    Only such a BLANK cancels an error or a text beside it in * and /.  A column or measure reference, a table, an aggregate or iterator, or a
    logical operator (a && node, AND, OR) in the subtree, followed through VARs, makes the BLANK one from data, which does not cancel it.
    """
    if not isinstance(node, tuple) or not node:
        return True
    kind = node[0]
    if kind == "logical":
        return _reads_no_data(node[2], held, seen) and _reads_no_data(node[3], held, seen)
    if kind == "call" and node[1] in {"AND", "OR"} and len(node[2]) == 2:
        return all(_reads_no_data(arg, held, seen) for arg in node[2])
    if kind == "call" and node[1] in {"MIN", "MAX"} and len(node[2]) == 2:
        return all(_reads_no_data(arg, held, seen) for arg in node[2])
    if kind == "call" and node[1] == "CONVERT" and len(node[2]) == 2:
        return _reads_no_data(node[2][0], held, seen)
    if kind in {"reference", "measure", "table", "table_call", "tablevalue", "tablecapture", "tableconstructor"}:
        return False
    if kind == "call" and node[1] in _DATA_READING_CALLS:
        return False
    if kind == "let":  # a VAR block inside the operand: its own names are held here
        own = dict(node[1])
        outer = held
        held = lambda name: own.get(name, outer(name))  # noqa: E731
        return all(_reads_no_data(bound, held, seen) for _, bound in node[1]) and _reads_no_data(node[2], held, seen)
    if kind == "var":
        if node[1] in seen:
            return False
        bound = held(node[1])
        return bound is not None and _reads_no_data(bound, held, seen | {node[1]})
    children = node if isinstance(node[0], tuple) else node[1:]
    return all(_reads_no_data(child, held, seen) for child in children if isinstance(child, tuple))



def _has_error_or_data_or_blank(node: Any) -> bool:
    """True if node contains explicit BLANK, errors, data reading, or variable references that can evaluate to BLANK/error."""
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind in {"reference", "measure", "table", "table_call", "tableconstructor", "blank", "blank_comment"}:
        return True
    if kind == "var":
        return True
    if kind == "call":
        fn = node[1]
        if fn in {"BLANK", "ERROR", "LN", "LOG", "SQRT", "VALUE", "DIVIDE", "SWITCH"}:
            return True
        if fn in (_DATA_READING_CALLS - {"AND", "OR"}):
            return True
        if fn in {"SUM", "AVERAGE", "MIN", "MAX", "COUNT", "SUMX", "AVERAGEX", "MAXX", "MINX", "COUNTX", "COUNTAX", "SELECTEDVALUE"}:
            return True
        if fn in {"IF", "IF.EAGER"} and len(node[2]) < 3:
            return True
        return any(_has_error_or_data_or_blank(arg) for arg in node[2])
    if kind == "binary":
        op, left, right = node[1], node[2], node[3]
        if op == "/":
            return True
        return _has_error_or_data_or_blank(left) or _has_error_or_data_or_blank(right)
    if kind == "unary":
        return _has_error_or_data_or_blank(node[2])
    if kind == "let":
        return any(_has_error_or_data_or_blank(bound) for _, bound in node[1]) or _has_error_or_data_or_blank(node[2])
    return False


_NO_SCAN_FILTER_CALLS = frozenset({"HASONEVALUE", "ISFILTERED", "ISINSCOPE"})  # Task 19 Part D: each reads the filter context of one column


def _is_plain_all(node: Any) -> bool:
    """A CALCULATE filter argument that is ALL, ALLSELECTED or REMOVEFILTERS of one table or column (also inside KEEPFILTERS): it removes filters and scans nothing."""
    if isinstance(node, tuple) and len(node) > 2 and node[0] == "call" and node[1] == "KEEPFILTERS" and len(node[2]) == 1:
        return _is_plain_all(node[2][0])  # keeping the filters of a filter that removes none changes nothing
    return isinstance(node, tuple) and len(node) > 2 and node[0] == "call" and node[1] in {"ALL", "ALLSELECTED", "REMOVEFILTERS"} and len(node[2]) == 1


def _blank_without_scan(node: Any, held: Callable[[str], Any], in_row: bool = False, seen: frozenset[str] = frozenset()) -> bool:
    """Task 19 Part D: True when a BLANK operand works out without scanning any column values, so it cancels an error or a text beside it in * and in / (left side).

    Recursive like _reads_no_data, but it allows only the filter-context calls (SELECTEDVALUE, HASONEVALUE, ISFILTERED, ISINSCOPE), COUNTROWS of a
    table, CALCULATE with no filter, COALESCE, IF, ISBLANK, comparisons and arithmetic of those, constants and VARs. Any other call, a column in a
    scan, or a logical operator makes the BLANK one from data, which does not cancel.
    """
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind in {"number", "string", "boolean", "blank"}:
        return True
    if kind == "let":  # a VAR block inside the operand: its own names are held here
        own = dict(node[1])
        outer = held
        held = lambda name: own.get(name, outer(name))  # noqa: E731
        return all(_blank_without_scan(bound, held, in_row, seen) for _, bound in node[1]) and _blank_without_scan(node[2], held, in_row, seen)
    if kind == "var":
        if node[1] in seen:
            return False
        bound = held(node[1])
        return bound is not None and _blank_without_scan(bound, held, in_row, seen | {node[1]})
    if kind in {"binary", "comparison", "unary"}:
        return all(_blank_without_scan(child, held, in_row, seen) for child in node[2:] if isinstance(child, tuple))
    if kind != "call":
        return False
    name, arguments = node[1], node[2]
    if name in _NO_SCAN_FILTER_CALLS:
        return len(arguments) == 1 and arguments[0][0] == "reference"
    if name == "SELECTEDVALUE":
        return (len(arguments) in (1, 2) and arguments[0][0] == "reference"
                and (len(arguments) == 1 or arguments[1] == ("blank",) or arguments[1][:2] == ("call", "BLANK")))
    if name == "COUNTROWS":
        return len(arguments) == 1 and arguments[0][0] == "table"
    if name == "CALCULATE":
        return len(arguments) == 1 and not in_row and _blank_without_scan(arguments[0], held, in_row, seen)  # under a row context a CALCULATE transitions it: a scan
    if name in {"COALESCE", "IF", "ISBLANK", "BLANK"}:
        return all(_blank_without_scan(argument, held, in_row, seen) for argument in arguments)
    return False

def _filter_flag_blank(node: Any) -> bool:
    """Task 20 Part E: a BLANK built only from ISFILTERED or ISINSCOPE (with constants, IF, COALESCE, ISBLANK and arithmetic), at least one of
    them. Only this BLANK still cancels an error under a CALCULATE that filters; a SELECTEDVALUE or a COUNTROWS there does not (live Power BI)."""
    found = [False]

    def walk(item: Any) -> bool:
        if not isinstance(item, tuple) or not item:
            return False
        kind = item[0]
        if kind in {"number", "string", "boolean", "blank"}:
            return True
        if kind in {"binary", "comparison", "unary"}:
            return all(walk(child) for child in item[2:] if isinstance(child, tuple))
        if kind == "call" and item[1] in {"ISFILTERED", "ISINSCOPE"}:
            found[0] = True
            return len(item[2]) == 1 and item[2][0][0] == "reference"
        if kind == "call" and item[1] in {"IF", "COALESCE", "ISBLANK", "BLANK"}:
            return all(walk(argument) for argument in item[2])
        return False

    return walk(node) and found[0]


def _held_logical(node: Any, held: Callable[[str], Any]) -> tuple[Any, Callable[[str], Any]]:
    """Task 20 Part C: the node a VAR, or a VAR block's RETURN, holds, with the block's names held (a VAR is followed to its bound expression)."""
    seen: set[str] = set()
    while isinstance(node, tuple) and node and node[0] in {"var", "let"}:
        if node[0] == "let":
            own, outer = dict(node[1]), held
            held = lambda name, own=own, outer=outer: own.get(name, outer(name))  # noqa: E731
            node = node[2]
        elif node[1] not in seen and held(node[1]) is not None:
            seen.add(node[1])
            node = held(node[1])
        else:
            break
    return node, held


def _logical_operands_scan_nothing(node: Any, held: Callable[[str], Any], in_row: bool = False) -> bool:
    """Task 19 Part F: a logical operator (&&, ||, AND, OR, NOT) whose operands all work out without scanning a column.

    Its BLANK then cancels an error beside it in * and in / (left side), as a BLANK of Part D does. Only the top operator is looked at.
    """
    node, held = _held_logical(node, held)
    if not _is_pure_logical(node):
        return False
    operands = node[2:] if node[0] == "logical" else node[2]
    return all(_blank_without_scan(operand, held, in_row) or (not _needs_scan(operand, held, in_row) and not any(True for _ in _iter_reference_nodes(operand))) for operand in operands if isinstance(operand, tuple))


_SCAN_FREE_CALLS = frozenset({
    "ALL", "ALLSELECTED", "VALUES", "DISTINCTCOUNT", "DISTINCTCOUNTNOBLANK", "HASONEVALUE", "HASONEFILTER", "ISFILTERED", "ISCROSSFILTERED",
    "ISINSCOPE", "SELECTEDVALUE", "REMOVEFILTERS", "KEEPFILTERS",
})


def _is_true_constant(node: Any) -> bool:
    return isinstance(node, tuple) and len(node) > 1 and ((node[0] == "boolean" and node[1] is True) or (node[0] == "call" and node[1] == "TRUE" and not node[2]))


def _is_whole_table_all(item: tuple[Any, ...]) -> bool:
    """An ALL(table) filter, possibly under KEEPFILTERS (the caller has checked it is a plain ALL)."""
    inner = item[2][0] if item[1] == "KEEPFILTERS" else item
    return inner[2][0][0] == "table"


def _needs_scan(node: Any, held: Callable[[str], Any], in_row: bool = False, seen: frozenset[str] = frozenset()) -> bool:
    """Task 20 Part C: True when the expression scans column values, so a BLANK beside it does not work out without a scan.

    A column read is a scan in a row context. Aggregates, iterators, ISEMPTY, LOOKUPVALUE, FIRSTNONBLANK and FILTER scan (FILTER does not when its
    predicate is TRUE()). MAX and MIN of a column, MAXX of a plain column, DISTINCTCOUNT, COUNTROWS of a table, ALL or VALUES and the filter-context
    reads do not. A CALCULATE scans with a filter that is not ALL, or under a row context to transition it. Any other call scans when an operand does.
    """
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind == "reference":
        return in_row
    if kind == "let":  # a VAR block inside the operand: its own names are held here
        own = dict(node[1])
        outer = held
        held = lambda name: own.get(name, outer(name))  # noqa: E731
        return any(_needs_scan(bound, held, in_row, seen) for _, bound in node[1]) or _needs_scan(node[2], held, in_row, seen)
    if kind == "var":
        if node[1] in seen:
            return False
        bound = held(node[1])
        return bound is not None and _needs_scan(bound, held, in_row, seen | {node[1]})
    if kind != "call":
        return any(_needs_scan(child, held, in_row, seen) for child in node[1:] if isinstance(child, tuple))
    name, arguments = node[1], node[2]

    def operands_scan(items: Iterable[Any]) -> bool:
        return any(_needs_scan(item, held, in_row, seen) for item in items if isinstance(item, tuple))

    if name in {"AND", "OR"}:
        return operands_scan(arguments)
    if name in {"MAX", "MIN"}:
        return operands_scan(argument for argument in arguments if argument[0] != "reference")
    if name in {"MAXX", "MINX"}:
        return len(arguments) != 2 or arguments[1][0] != "reference" or _needs_scan(arguments[0], held, in_row, seen)
    if name == "FILTER":
        return not (len(arguments) == 2 and _is_true_constant(arguments[1]))
    if name == "COUNTROWS":
        return operands_scan(arguments)
    if name in {"CALCULATE", "CALCULATETABLE"}:
        filters = arguments[1:]
        if any(not _is_plain_all(item) for item in filters):
            return True
        if in_row and not (filters and all(_is_whole_table_all(item) for item in filters)):
            return True  # under a row context the CALCULATE transitions the row into the filters
        return operands_scan(arguments[:1])
    if name in _SCAN_FREE_CALLS:
        return False
    if name == "ISEMPTY" or name in _DATA_READING_CALLS or name in _ITERATOR_CALLS:
        return True
    return operands_scan(arguments)


def _static_blank(node: Any, held: Callable[[str], Any], truth: Callable[[Any], bool | None], seen: frozenset[str] = frozenset()) -> bool:
    """True when Power BI knows this operand is BLANK without looking at any row (BITAND, BITLSHIFT and BITRSHIFT then skip their other operand).

    BLANK(), SELECTEDVALUE of one column, BLANK + BLANK, anything * BLANK, an IF whose constant condition picks a missing else or a branch that is
    itself static, and a VAR holding one. A BLANK read from an iterator or an aggregate over an empty table (COUNTROWS(FILTER(t,FALSE())), SUMX ...)
    is a scanned BLANK, not this. ``truth`` answers a condition that reads no data (True, False) or None when it cannot be told.
    """
    if not isinstance(node, tuple) or not node:
        return False
    kind = node[0]
    if kind == "blank":
        return True
    if kind == "let":
        own, outer = dict(node[1]), held
        return _static_blank(node[2], lambda name: own.get(name, outer(name)), truth, seen)
    if kind == "var":
        bound = None if node[1] in seen else held(node[1])
        return bound is not None and _static_blank(bound, held, truth, seen | {node[1]})
    if kind == "binary" and len(node) == 4:
        left, right = _static_blank(node[2], held, truth, seen), _static_blank(node[3], held, truth, seen)
        return (left or right) if node[1] == "*" else (left and right) if node[1] in {"+", "-"} else False
    if kind != "call":
        return False
    name, arguments = node[1], node[2]
    if name == "BLANK":
        return not arguments
    if name == "SELECTEDVALUE":
        return len(arguments) == 1 and arguments[0][0] == "reference"
    if name == "IF" and len(arguments) in (2, 3):
        answer = truth(arguments[0])
        if answer is None:
            return False
        if answer:
            return _static_blank(arguments[1], held, truth, seen)
        return len(arguments) == 2 or _static_blank(arguments[2], held, truth, seen)
    return False


def _is_empty_text(node: Any) -> bool:
    return isinstance(node, tuple) and len(node) > 1 and node[0] == "string" and node[1] == ""


_LOGICAL_OPERAND_CATEGORIES = frozenset({"boolean", "blank", "numeric", "date/time"})


def _empty_text_blank(node: Any, others: Iterable[Any]) -> bool:
    """Task 20 Part C: an empty text is a BLANK beside an operand that reads a column (Facts[Sales]&&""), where Power BI answers the row's value; over constants it stays refused."""
    return _is_empty_text(node) and any(True for other in others if isinstance(other, tuple) for _ in _iter_reference_nodes(other))


def _is_text_arithmetic(node: Any) -> bool:
    """Task 20 Part C: arithmetic on a text constant that is not a number ("a"*2). Power BI's answer for a logical BLANK beside one is not modelled
    (a * of it is refused, as before Part C), so a logical BLANK does not cancel it here."""
    if not isinstance(node, tuple) or len(node) != 4 or node[0] != "binary" or node[1] not in {"+", "-", "*", "/"}:
        return False
    for child in node[2:]:
        if isinstance(child, tuple) and len(child) > 1 and child[0] == "string":
            try:
                Decimal(str(child[1]).strip())
            except Exception:
                return True
    return False


def _currency_wrap(value: Decimal) -> Decimal:
    """Part D: a Currency is a signed 64-bit count of ten-thousandths; + - * wrap around with no error (CURRENCY(1E14)*10 is -844674407370955.1616)."""
    units = int((value * 10000).to_integral_value(rounding=ROUND_HALF_UP))
    units = (units + 2**63) % 2**64 - 2**63
    return Decimal(units).scaleb(-4)  # a zero has no sign in a Currency


def _is_power_node(node: Any) -> bool:
    """True when the node is a POWER call or a ^ operation (not one nested deeper)."""
    if isinstance(node, tuple) and len(node) == 3 and node[0] == "unary":
        return _is_power_node(node[2])  # a sign in front of a power (-"2"^1.5 is minus the power)
    return isinstance(node, tuple) and len(node) >= 2 and ((node[0] == "call" and node[1] == "POWER") or (node[0] == "binary" and node[1] == "^"))


def _double_rounding_result(function: str, result: Any, argument_type: str | None) -> Any:
    """Part A: ROUND, ROUNDUP, ROUNDDOWN, TRUNC, MROUND and MOD of a Double are Doubles: the result is its exact binary value."""
    if function in {"ROUND", "ROUNDUP", "ROUNDDOWN", "TRUNC", "MROUND", "MOD"} and argument_type == "double" and isinstance(result, Decimal) and result.is_finite():
        return Decimal(float(result))
    return result


def _int64_wrap(operator: str, left: Decimal, right: Decimal) -> Decimal:
    """Part C: + - * of two Int64 values, exactly then wrapped to a signed 64-bit count (9223372036854775807+1 is -9223372036854775808).

    A value that is not a whole number (not expected for an Int64) keeps the Decimal result.
    """
    if left != left.to_integral_value() or right != right.to_integral_value():
        return _binary_value(operator, left, right)
    a, b = int(left), int(right)
    exact = a + b if operator == "+" else a - b if operator == "-" else a * b
    return Decimal((exact + 2**63) % 2**64 - 2**63)


def _binary_value(operator: str, left: Decimal | None, right: Decimal | None) -> Decimal | None:
    """+ - * / with Power BI's blank and IEEE rules (verified on 2.157.879.0).

    Blank counts as zero for + and - unless both sides are blank; * and / return
    blank when the left side is blank. x/0 and x/BLANK() are Infinity (NaN for 0/0),
    and results beyond the double range are Infinity.
    """
    quiet = dax_typed.QUIET
    if operator in {"+", "-"}:
        if left is None and right is None:
            return None
        if left is None and operator == "-":
            return _checked_double(right.copy_negate())  # Part B: BLANK() - x is -x (BLANK()-(0/0) is nan, not -nan)
        left_value = Decimal(0) if left is None else left  # not 'left or 0': a minus zero is falsy and must keep its sign
        right_value = Decimal(0) if right is None else right
        result = quiet.add(left_value, right_value) if operator == "+" else quiet.subtract(left_value, right_value)
        return _checked_double(_invalid_nan(result, left_value, right_value))
    if left is None:
        return None
    if operator == "*":
        return None if right is None else _checked_double(_invalid_nan(quiet.multiply(left, right), left, right))
    divisor = Decimal(0) if right is None else right
    if divisor == 0:  # Part B: the sign of the divisor counts for an Infinity
        if left.is_nan():
            return left
        if left == 0:
            return Decimal("-NaN")  # zero over zero is the IEEE default NaN, negative
        return Decimal("-Infinity") if left.is_signed() != divisor.is_signed() else Decimal("Infinity")
    return _checked_double(_invalid_nan(quiet.divide(left, divisor), left, divisor))


def _invalid_nan(result: Decimal, left: Decimal, right: Decimal) -> Decimal:
    """Part B: an invalid operation (Infinity - Infinity, Infinity * 0, Infinity / Infinity) is the negative NaN; a NaN operand keeps its own sign."""
    if result.is_nan() and not (left.is_nan() or right.is_nan()):
        return Decimal("-NaN")
    return result


def _bare_result(value: Any) -> Any:
    """Part B: a bare result prints 0 for a zero of either sign and NaN for a NaN of either sign."""
    if isinstance(value, Decimal) and not isinstance(value, bool) and not dax_dates.is_date(value) and (value.is_zero() or value.is_nan()):
        return Decimal("NaN") if value.is_nan() else Decimal(0)
    return value


def _unsigned_zero(value: Any) -> Any:
    """A calculated column stores a zero without its sign."""
    return Decimal(0) if isinstance(value, Decimal) and not dax_dates.is_date(value) and value.is_zero() else value


def _is_abs_of_blank(node: tuple[Any, ...]) -> bool:
    return (
        node[0] == "call"
        and node[1] == "ABS"
        and len(node[2]) == 1
        and node[2][0][0] == "blank"
    )


_GENERAL_CLEAR_FUNCTIONS = {"ALL", "ALLNOBLANKROW", "REMOVEFILTERS", "ALLEXCEPT", "ALLCROSSFILTERED"}
_GENERAL_BOOLEAN_CALLS = {"AND", "OR", "NOT", "ISBLANK", "CONTAINSSTRING", "CONTAINSSTRINGEXACT", "ISNUMBER", "ISTEXT", "CONTAINS"}


def _is_general_table_filter(node: Any) -> bool:
    """A CALCULATE filter argument that is a table expression (its columns' values become the filter)."""
    while isinstance(node, tuple) and node and node[0] == "call" and node[1] == "EVALUATEANDLOG" and node[2]:
        node = node[2][0]
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] in {"table_call", "tableconstructor", "table"}:
        return True
    if node[0] == "var":
        return True
    return node[0] == "call" and (
        node[1] in _TABLE_FUNCTION_ARITY or node[1] in dax_time_sets.SET_FUNCTIONS or node[1] in _NONBLANK_TABLES
        or node[1] in {"FILTER", "GENERATESERIES", "ROW"} or node[1] in _TIME_FILTER_FUNCTIONS
    )


def _general_calculate_filters_valid(filters: tuple[tuple[Any, ...], ...], legacy_sets_ok: bool = False) -> bool:
    """Whether every CALCULATE filter argument has a shape the general (any table or Boolean expression) path evaluates."""
    # date sets: the old ladder keeps a CALCULATE whose time functions all have its own shape; one other date set sends all of them here
    general_time_sets = legacy_sets_ok or any(_new_route_time_set(item) for item in filters)
    for node in filters:
        wrapped = False
        while isinstance(node, tuple) and node[:2] == ("call", "KEEPFILTERS") and len(node[2]) == 1:
            node = node[2][0]
            wrapped = True
        if not isinstance(node, tuple) or not node:
            return False
        if node[0] == "let":
            try:
                node = _unwrap_var_filter(node)
            except MeasureError:
                return False
        if not isinstance(node, tuple) or not node:
            return False
        if node[0] == "call" and node[1] in _GENERAL_CLEAR_FUNCTIONS:
            continue
        if node[0] == "call" and node[1] in dax_time_sets.SET_FUNCTIONS and (general_time_sets or wrapped or _new_route_time_set(node)):
            continue  # date sets are tables with the lineage of their column (iteration 84)
        if node[0] == "call" and node[1] in _TIME_FILTER_FUNCTIONS | {"USERELATIONSHIP", "CROSSFILTER", "ALLSELECTED"}:
            return False  # these keep their dedicated paths
        if _is_general_table_filter(node):
            continue
        if node[0] in {"comparison", "logical", "in", "unary", "reference"} or node[0] == "call":
            continue  # any expression over the columns of one table: it is checked when evaluated
        return False
    return True


_RELATIONSHIP_MODIFIERS = {"USERELATIONSHIP", "CROSSFILTER"}


def _time_filters_beside_general_filters(arguments: tuple[tuple[Any, ...], ...]) -> bool:
    """CALCULATE(e, <date sets>, <any Boolean / table / clearing filters>): live Power BI evaluates every filter in the outer context,
    so a date set may sit beside FILTER(ALL(T), ..), ALL(T) and column tests in any order."""
    filters = arguments[1:]
    return any(a[0] == "call" and a[1] in _TIME_FILTER_FUNCTIONS for a in filters) and _general_calculate_filters_valid(
        tuple(a for a in filters if not (a[0] == "call" and a[1] in _TIME_FILTER_FUNCTIONS | _RELATIONSHIP_MODIFIERS))
    )


_MIX_MODIFIERS = _RELATIONSHIP_MODIFIERS | {"ALLSELECTED"}


def _modifier_mix_filters_valid(filters: tuple[tuple[Any, ...], ...]) -> bool:
    """CALCULATE filters that mix USERELATIONSHIP / CROSSFILTER with clearing, Boolean and table filters (general path)."""
    modifiers = [
        node for node in filters if isinstance(node, tuple) and node[:1] == ("call",) and node[1] in _MIX_MODIFIERS
    ]
    if not modifiers:
        return False
    for node in modifiers:
        if node[1] == "USERELATIONSHIP":
            _validate_userelationship_call(node)
        elif node[1] == "CROSSFILTER":
            _validate_crossfilter_call(node)
        else:
            _validate_filter_clear_call(node, "ALLSELECTED")
    rest = tuple(node for node in filters if node not in modifiers)
    return not rest or _general_calculate_filters_valid(rest)


def _validate_general_filter_literals(node: tuple[Any, ...]) -> None:
    if node[:2] == ("call", "KEEPFILTERS") and len(node[2]) == 1:
        node = node[2][0]
    if node[0] == "let":
        node = _unwrap_var_filter(node)
    if node[0] in {"comparison", "logical", "in", "unary", "reference"}:
        _validate_literal_positions(node, allow_blank=True)


def _legacy_calculate_filters_valid(arguments: tuple[tuple[Any, ...], ...]) -> None:
    """The CALCULATE filter shapes the local engine has always supported; raises MeasureError for any other."""
    if any(_new_route_time_set(argument) or (
        isinstance(argument, tuple) and argument[:1] == ("call",) and argument[1] in dax_time_sets.SET_FUNCTIONS - _TIME_FILTER_FUNCTIONS
    ) for argument in arguments[1:]):
        raise MeasureError("This date set is evaluated by the general CALCULATE path.")
    contains_userelationship = any(
        _contains_function_call(argument, "USERELATIONSHIP")
        for argument in arguments[1:]
    )
    if contains_userelationship:
        modifiers = tuple(
            argument
            for argument in arguments[1:]
            if argument[0] == "call"
            and argument[1] == "USERELATIONSHIP"
        )
        filter_arguments = tuple(
            argument
            for argument in arguments[1:]
            if not (
                argument[0] == "call"
                and argument[1] == "USERELATIONSHIP"
            )
        )
        if not modifiers or any(
            _contains_function_call(argument, "USERELATIONSHIP")
            for argument in filter_arguments
        ):
            raise MeasureError(
                "USERELATIONSHIP must be a direct CALCULATE filter modifier in this local subset."
            )
        for modifier in modifiers:
            _validate_userelationship_call(modifier)
        _validate_relationship_modifier_filters(filter_arguments)
        return
    contains_crossfilter = any(
        _contains_function_call(argument, "CROSSFILTER")
        for argument in arguments[1:]
    )
    if contains_crossfilter:
        modifiers = tuple(
            argument
            for argument in arguments[1:]
            if argument[0] == "call"
            and argument[1] == "CROSSFILTER"
        )
        filter_arguments = tuple(
            argument
            for argument in arguments[1:]
            if not (
                argument[0] == "call"
                and argument[1] == "CROSSFILTER"
            )
        )
        if not modifiers or any(
            _contains_function_call(argument, "CROSSFILTER")
            for argument in filter_arguments
        ):
            raise MeasureError(
                "CROSSFILTER must be a direct CALCULATE filter modifier in this local subset."
            )
        for modifier in modifiers:
            _validate_crossfilter_call(modifier)
        _validate_relationship_modifier_filters(filter_arguments)
        return
    valid_filter_clear = (
        len(arguments) == 2
        and arguments[1][0] == "call"
        and arguments[1][1] in {"REMOVEFILTERS", "ALL", "ALLNOBLANKROW", "ALLEXCEPT", "ALLSELECTED", "ALLCROSSFILTERED"}
    )
    contained_filter_clear = {
        function
        for function in {"REMOVEFILTERS", "ALL", "ALLNOBLANKROW", "ALLEXCEPT", "ALLSELECTED", "ALLCROSSFILTERED"}
        if any(
            _contains_function_call(argument, function)
            for argument in arguments[1:]
        )
    }
    if contained_filter_clear:
        if _validate_mixed_filter_clear_calculate(arguments):
            return
        if not valid_filter_clear and _time_filters_beside_general_filters(arguments):
            return
        if not valid_filter_clear:
            function = sorted(contained_filter_clear)[0]
            raise MeasureError(
                f"{function} must be the only CALCULATE filter argument in this local subset."
            )
        if arguments[1][1] == "ALLEXCEPT":
            _validate_allexcept_call(arguments[1])
        else:
            _validate_filter_clear_call(arguments[1], arguments[1][1])
        return
    if (
        len(arguments) == 2
        and _is_table_filter_argument(arguments[1], legacy=True)
    ):
        unwrapped = arguments[1]
        while isinstance(unwrapped, tuple) and unwrapped:
            if unwrapped[0] == "call" and unwrapped[1] == "KEEPFILTERS" and len(unwrapped[2]) == 1:
                unwrapped = unwrapped[2][0]
            elif unwrapped[0] == "let":
                try:
                    unwrapped = _unwrap_var_filter(unwrapped)
                except MeasureError:
                    break
            else:
                break
        if isinstance(unwrapped, tuple) and unwrapped and unwrapped[0] == "call" and unwrapped[1] == "FILTER":
            _validate_table_filter_call(unwrapped)
        return
    if any(_contains_function_call(argument, "FILTER") for argument in arguments[1:]):
        if _time_filters_beside_general_filters(arguments):
            return
        raise MeasureError(
            "A table-valued FILTER must be the only CALCULATE filter argument."
        )
    for filter_argument in arguments[1:]:
        if _new_route_time_set(filter_argument) or (filter_argument[0] == "call" and filter_argument[1] in dax_time_sets.SET_FUNCTIONS - _TIME_FILTER_FUNCTIONS):
            raise MeasureError("This date set is evaluated by the general CALCULATE path.")
        if filter_argument[0] == "call" and filter_argument[1] in _TIME_FILTER_FUNCTIONS:
            _validate_literal_positions(filter_argument)
        else:
            predicate, _keep = _calculate_filter_argument(filter_argument)
            _calculate_boolean_filter_column(predicate)
    return


def _validate_literal_positions(
    node: tuple[Any, ...], *, allow_blank: bool = False
) -> None:
    """Keep literals in time-intelligence syntax or validated CALCULATE filters."""
    kind = node[0]
    if kind in {"string", "var", "boolean"}:
        return
    if kind == "let":
        for _name, value in node[1]:
            if _is_held_table_value(value):
                continue  # a table held in a VAR; its arguments are checked when it is evaluated
            _validate_literal_positions(value, allow_blank=True)
        _validate_literal_positions(node[2], allow_blank=True)
        return
    if kind == "blank":
        if allow_blank:
            return
        raise MeasureError("BLANK() is supported only in explicitly allowed argument positions.")
    if kind == "blank_comment":
        return
    if kind == "omitted":
        raise MeasureError("Only TOTALYTD's optional filter argument can be omitted.")
    if kind == "call":
        function, arguments = node[1], node[2]
        if function == "DIVIDE":
            for operand in arguments[:2]:
                if operand[0] != "blank" and not _is_abs_of_blank(operand):
                    _validate_literal_positions(operand)
            if len(arguments) == 3:
                if not _is_divide_alternate_constant(arguments[2]):
                    raise MeasureError(
                        "DIVIDE alternate result must be a constant numeric value or BLANK()."
                    )
                if arguments[2][0] not in {"blank", "string", "boolean"}:
                    _validate_literal_positions(arguments[2])
            return
        if function in _SCALAR_MATH_ARITY:
            for argument in arguments:
                _validate_literal_positions(argument, allow_blank=True)
            return
        if function == "CALCULATETABLE":
            _validate_literal_positions(("call", "CALCULATE", ((("number", Decimal(0))),) + tuple(arguments[1:])))
            return
        if function in _TABLE_FUNCTION_ARITY or function in _RANK_ARITY:
            for index, argument in enumerate(arguments):
                if argument[0] in {"table", "omitted"} or (
                    _table_position(function, index) and _is_all_table_value_argument(argument)
                ):
                    continue  # a table expression, an omitted argument or an ASC/DESC/SKIP/DENSE keyword
                _validate_literal_positions(argument, allow_blank=True)
            return
        if (function in dax_time_sets.SET_FUNCTIONS and not (function in _TIME_FILTER_FUNCTIONS and _legacy_time_shape(node))) or function in _NONBLANK_TABLES or function in {"FIRSTNONBLANKVALUE", "LASTNONBLANKVALUE"}:
            for index, argument in enumerate(arguments):
                if index == 0 and _is_all_table_value_argument(argument):
                    continue  # a column or table expression of dates
                _validate_literal_positions(argument, allow_blank=True)
            return
        if function in {"CONCATENATEX", "XNPV", "XIRR", "TOCSV", "TOJSON", "LINESTX"}:
            for argument in arguments[1:]:
                if argument[0] != "table":  # ASC / DESC
                    _validate_literal_positions(argument, allow_blank=True)
            return
        if function == "LINEST":
            for argument in arguments:
                _validate_literal_positions(argument, allow_blank=True)
            return
        if function in {"IF", "IF.EAGER", "ISBLANK", "IFERROR", "SWITCH", "ABS", "AND", "OR", "NOT", "SELECTEDVALUE", "ERROR", "CUSTOMDATA", "EVALUATEANDLOG"} or function in _TYPED_ARITY or function in _LOOKUP_ARITY or (
            function in {"MIN", "MAX"} and len(arguments) == 2
        ):
            for index, argument in enumerate(arguments):
                if function in {"ISEMPTY", "CONTAINS", "CONTAINSROW"} and index == 0 and _is_all_table_value_argument(argument):
                    continue  # a table expression, checked where it is evaluated
                _validate_literal_positions(argument, allow_blank=True)
            return
        if function in {"NAMEOF", "TABLEOF"}:
            return
        if function == "COALESCE":
            for argument in arguments:
                if _is_coalesce_table_argument(argument):
                    raise MeasureError(
                        "COALESCE needs scalar expressions; table-valued arguments are not supported."
                    )
                _validate_literal_positions(argument, allow_blank=True)
            return
        if function == "CALCULATE":
            if not arguments:
                raise MeasureError("CALCULATE needs an expression.")
            _validate_literal_positions(arguments[0], allow_blank=allow_blank)
            try:
                _legacy_calculate_filters_valid(arguments)
            except MeasureError:
                if not _general_calculate_filters_valid(arguments[1:]) and not _modifier_mix_filters_valid(arguments[1:]):
                    raise
                for filter_argument in arguments[1:]:
                    _validate_general_filter_literals(filter_argument)
            return
        if function in {"MAXX", "MINX"}:
            _validate_literal_positions(arguments[1], allow_blank=True)
            return
        if function in {"SUMX", "AVERAGEX"} or function in dax_math.STAT_ITERATORS:
            _validate_literal_positions(arguments[1], allow_blank=True)
            for extra in arguments[2:]:
                _validate_literal_positions(extra, allow_blank=True)
            return
        if function in {"COUNTX", "COUNTAX"}:
            _validate_count_iterator_literals(arguments[1])
            return
        if function == "COUNTROWS":
            return
        if function == "FILTER":
            if not (isinstance(arguments[0], tuple) and arguments[0] and arguments[0][0] == "call" and arguments[0][1] == "ROW"):
                # only a table that is one row by construction can be read as a single cell; any other FILTER in a scalar position is a table result
                raise MeasureError(
                    "FILTER is supported only as the sole table-valued CALCULATE filter argument."
                )
            if not (_is_all_table_value_argument(arguments[0]) or _table_position(function, 0)):
                _validate_literal_positions(arguments[0], allow_blank=True)
            _validate_literal_positions(arguments[1], allow_blank=True)
            return
        if function == "KEEPFILTERS":
            raise MeasureError("KEEPFILTERS is supported only as a CALCULATE filter argument.")
        if function == "ROLLUP":
            raise MeasureError("ROLLUP function can only be used on groupBy_ColumnName parameters of the SUMMARIZE function.")
        if function == "ROLLUPGROUP":
            raise MeasureError("ROLLUPGROUP function can only be used in the ROLLUP function.")
        if function == "ROLLUPADDISSUBTOTAL":
            raise MeasureError("ROLLUPADDISSUBTOTAL function can only be used in the SUMMARIZECOLUMNS function.")
        if function == "ROLLUPISSUBTOTAL":
            raise MeasureError("ROLLUPISSUBTOTAL function can only be used in the ADDMISSINGITEMS function.")
        if function == "ISSUBTOTAL":
            raise MeasureError("ISSUBTOTAL function can only be used in the SUMMARIZE function.")
        if function == "USERELATIONSHIP":
            raise MeasureError(
                "USERELATIONSHIP is supported only as a CALCULATE filter modifier."
            )
        if function == "CROSSFILTER":
            raise MeasureError(
                "CROSSFILTER is supported only as a CALCULATE filter modifier."
            )
        if function in {"REMOVEFILTERS", "ALLCROSSFILTERED"}:
            raise MeasureError(
                f"{function} is supported only as a CALCULATE filter modifier."
            )
        if function in {"ALL", "ALLNOBLANKROW", "ALLEXCEPT", "ALLSELECTED"}:
            raise MeasureError(
                f"{function} is supported only as a CALCULATE filter modifier or "
                "a COUNTROWS/SUMX/AVERAGEX/MAXX/MINX/COUNTX/COUNTAX table expression in this local subset."
            )
        for index, argument in enumerate(arguments):
            if function == "TOTALYTD" and index == 3 and argument[0] == "string":
                _parse_year_end_date(argument[1])
            elif function == "DATESYTD" and index == 1 and argument[0] == "string":
                _parse_year_end_date(argument[1])
            elif function == "DATESBETWEEN" and index in {1, 2}:
                if argument[0] == "string":
                    _parse_iso_date_literal(argument[1], "DATESBETWEEN")
                elif argument[0] == "blank":
                    continue
            elif function == "DATESINPERIOD" and index == 1 and argument[0] == "string":
                _parse_iso_date_literal(argument[1], "DATESINPERIOD")
            elif function == "PREVIOUSYEAR" and index == 1 and argument[0] == "string":
                _parse_year_end_date(argument[1])
            elif function == "TOTALYTD" and index == 2 and argument[0] == "omitted":
                continue
            else:
                # ABS(BLANK()) is blank in Power BI; ROUND(BLANK(), 0) and other calls are not modelled for blanks.
                _validate_literal_positions(argument, allow_blank=allow_blank and function == "ABS")
        return
    if kind == "in":
        _validate_literal_positions(node[1], allow_blank=True)
        if not _is_all_table_value_argument(node[2]):
            _validate_literal_positions(node[2], allow_blank=True)
        return
    operand_blank = allow_blank or kind in {"unary", "binary", "comparison", "logical", "concat", "in", "tableconstructor", "tuple", "strict_equal"}
    for child in node[1:]:
        if isinstance(child, tuple) and child:
            _validate_literal_positions(child, allow_blank=operand_blank)


def _validate_count_iterator_literals(node: tuple[Any, ...]) -> None:
    """Allow bounded text conditions and string/blank results in COUNTX/COUNTAX."""
    if node[0] in {"string", "blank"}:
        return
    if node[0] == "call" and node[1] == "IF" and len(node[2]) == 3:
        _validate_count_iterator_condition(node[2][0])
        _validate_count_iterator_literals(node[2][1])
        _validate_count_iterator_literals(node[2][2])
        return
    _validate_literal_positions(node, allow_blank=True)


def _validate_count_iterator_condition(node: tuple[Any, ...]) -> None:
    """Accept the local numeric conditions plus text-column equality checks."""
    kind = node[0]
    if kind == "blank" or (kind == "call" and node[1] == "BLANK"):
        return
    if kind == "comparison":
        operator, left, right = node[1:4]  # a 5th item marks an IN comparison
        text_equality = (
            operator in {"=", "<>"}
            and (
                (left[0] == "reference" and right[0] == "string")
                or (right[0] == "reference" and left[0] == "string")
            )
        )
        if text_equality:
            return
        _validate_literal_positions(node)
        return
    if kind == "logical":
        _validate_count_iterator_condition(node[2])
        _validate_count_iterator_condition(node[3])
        return
    if kind == "call" and node[1] in {"AND", "OR"}:
        for argument in node[2]:
            _validate_count_iterator_condition(argument)
        return
    if kind == "call" and node[1] == "NOT":
        _validate_count_iterator_condition(node[2][0])
        return
    _validate_literal_positions(node)


class _Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.index = 0
        self.variables: list[str] = []
        self._in_var_binding: bool = False

    def parse(self) -> tuple[Any, ...]:
        if not self.tokens:
            raise MeasureError("Enter a DAX expression.")
        node = self._expression()
        if self.index != len(self.tokens):
            raise MeasureError(f"Unexpected token {self.tokens[self.index].value!r}.")
        node = _rewrite_total_td(node)
        _validate_literal_positions(node)
        return node

    def _expression(self) -> tuple[Any, ...]:
        if self._is_keyword("VAR"):
            return self._variables()
        return self._logical_or()

    def _is_keyword(self, word: str) -> bool:
        return (
            self.index < len(self.tokens)
            and self.tokens[self.index].kind == "identifier"
            and self.tokens[self.index].value == word
        )

    def _variables(self) -> tuple[Any, ...]:
        """VAR name = expression ... RETURN expression."""
        declared = len(self.variables)
        bindings: list[tuple[str, tuple[Any, ...]]] = []
        block_names: set[str] = set()
        while self._is_keyword("VAR"):
            self._take()
            name = self._take()
            if name.kind != "identifier" or name.value in _FUNCTIONS or name.value in {"VAR", "RETURN", "TRUE", "FALSE", "BLANK"}:
                raise MeasureError(f"{name.value!r} is not a valid variable name.")
            if name.value in block_names:
                raise MeasureError(
                    f"Variable {name.value.lower()!r} cannot be created because a variable with the same name already exists."
                )
            block_names.add(name.value)
            self._expect("=")
            self._in_var_binding = True
            try:
                value = self._expression()
            finally:
                self._in_var_binding = False
            bindings.append((name.value, value))
            self.variables.append(name.value)
        if not self._is_keyword("RETURN"):
            raise MeasureError("A VAR block needs a RETURN expression.")
        self._take()
        body = self._expression()
        del self.variables[declared:]
        return ("let", tuple(bindings), body)

    def _logical_or(self) -> tuple[Any, ...]:
        node = self._logical_and()
        while self._peek() == "||":
            self._take()
            right = self._variables() if self._is_keyword("VAR") else self._logical_and()
            node = ("logical", "||", node, right)
        return node

    def _logical_and(self) -> tuple[Any, ...]:
        node = self._comparison()
        while self._peek() == "&&":
            self._take()
            right = self._variables() if self._is_keyword("VAR") else self._comparison()
            node = ("logical", "&&", node, right)
        return node

    _AFTER_NOT_GROUP = {"=", "<>", "<", "<=", ">", ">=", "&", "+", "-", "*", "/", "^"}

    def _not_is_operator(self) -> bool:
        """NOT in front of an operand rather than NOT( ... ) as a function: a bare NOT, or NOT (x) followed by an operator."""
        if not self._is_keyword("NOT"):
            return False
        if self.index + 1 >= len(self.tokens) or self.tokens[self.index + 1].kind != "(":
            return True
        depth, position = 0, self.index + 1
        while position < len(self.tokens):
            depth += {"(": 1, ")": -1}.get(self.tokens[position].kind, 0)
            if depth == 0:
                after = self.tokens[position + 1] if position + 1 < len(self.tokens) else None
                return after is not None and (after.kind in self._AFTER_NOT_GROUP or (after.kind == "identifier" and after.value == "IN"))
            position += 1
        return False

    def _comparison(self) -> tuple[Any, ...]:
        node = self._concatenation()
        if self._is_keyword("IN"):
            self._take()
            members = self._concatenation()
            if members == ("tableconstructor", ()):
                # {} alone is an empty table, but Power BI rejects it as the right side of IN
                raise MeasureError("IN needs a table or at least one value; an empty table constructor {} is not accepted.")
            return _membership(node, members)
        if self._peek() in {"=", "==", "<>", "<", "<=", ">", ">="}:
            while self._peek() in {"=", "==", "<>", "<", "<=", ">", ">="}:  # a < b < c reads (a < b) < c
                operator = self._take().kind
                right = self._variables() if self._is_keyword("VAR") else self._concatenation()
                node = ("strict_equal", node, right) if operator == "==" else ("comparison", operator, node, right)
        return node

    def _concatenation(self) -> tuple[Any, ...]:
        node = self._arithmetic()
        while self._peek() == "&":
            self._take()
            right = self._variables() if self._is_keyword("VAR") else self._arithmetic()
            node = ("concat", node, right)
        return node

    def _arithmetic(self) -> tuple[Any, ...]:
        node = self._term()
        while self._peek() in {"+", "-"}:
            operator = self._take().kind
            right = self._variables() if self._is_keyword("VAR") else self._term()
            node = ("binary", operator, node, right)
        return node

    def _term(self) -> tuple[Any, ...]:
        if self._peek() in {"+", "-"}:  # Part B: a leading sign applies to the whole product or quotient that follows it, not to its first operand
            operator = self._take().kind
            return ("unary", operator, self._term())
        node = self._unary()
        while self._peek() in {"*", "/"}:
            operator = self._take().kind
            if self._is_keyword("VAR"):
                right = self._variables()
            elif self._peek() in {"+", "-"}:  # Part D: a sign after * or / binds the whole product or quotient that follows it
                right = ("unary", self._take().kind, self._term())
            else:
                right = self._unary()
            node = ("binary", operator, node, right)
        return node

    def _unary(self) -> tuple[Any, ...]:
        if self._not_is_operator():
            # NOT negates the whole comparison that follows: NOT 2>1 && 1>2 reads (NOT (2>1)) && (1>2); NOT (1>2) > (2>1) reads
            # NOT ((1>2) > (2>1)); 1 + NOT 1>2 is 2 (Power BI, tools/dax_battery_not_operator.json)
            self._take()
            operand = self._comparison()
            if self._is_keyword("IN"):  # Power BI folds a chained IN into the operand and rejects some of those; not modelled
                raise MeasureError("NOT followed by a comparison and IN needs parentheses in the local engine.")
            return ("call", "NOT", (operand,))
        if self._peek() in {"+", "-"}:
            operator = self._take().kind
            return ("unary", operator, self._unary())
        return self._power()

    def _power(self) -> tuple[Any, ...]:
        base = self._primary()
        if self._peek() == "^":  # binds tighter than a leading minus and groups to the right
            self._take()
            if self._is_keyword("VAR"):
                right = self._variables()
            elif self._peek() in {"+", "-"}:  # Task 20 F1: a sign after ^ binds the whole product or quotient that follows, like one after * or /
                right = ("unary", self._take().kind, self._term())
            else:
                right = self._unary()
            return ("binary", "^", base, right)
        return base

    def _primary(self) -> tuple[Any, ...]:
        token = self._take()
        if token.kind == "number":
            try:
                value = Decimal(token.value)
                digits = token.value.lower().split("e")[0].replace(".", "").lstrip("0")
                if len(digits) > 15 and ("." in token.value or "e" in token.value.lower() or abs(value) > 9223372036854775807):
                    value = Decimal(repr(float(token.value)))  # Power BI reads such literals as doubles
            except (DecimalException, OverflowError) as exc:
                raise MeasureError(f"Invalid numeric literal {token.value!r}.") from exc
            if not value.is_finite():
                raise MeasureError("Numeric literals must be finite.")
            return ("number", value, token.value)
        if token.kind == "string":
            return ("string", token.value)
        if token.kind == "(":
            node = self._expression()
            if self._peek() == ",":  # (a, b, ...) is a row of values, used inside {...} and with IN
                members = [node]
                while self._peek() == ",":
                    self._take()
                    members.append(self._expression())
                self._expect(")")
                return ("tuple", tuple(members))
            self._expect(")")
            return node
        if token.kind == "{" and self._peek() == "}":
            self._take()
            return ("tableconstructor", ())
        if token.kind == "{":
            items: list[tuple[Any, ...]] = []
            while True:
                items.append(self._expression())
                if self._peek() != ",":
                    break
                self._take()
            self._expect("}")
            widths = {len(item[1]) if item[0] in {"tuple", "tableconstructor"} else 0 for item in items}
            if len(widths) > 1:
                raise MeasureError("All rows of a table constructor must have the same number of values.")
            return ("tableconstructor", tuple(items))
        if token.kind == "reference":
            table, column = token.value.split("\0", 1)
            return ("reference", table, column)
        if token.kind == "blank_comment":
            return ("blank_comment",)
        if token.kind == "table":
            return ("table", token.value)
        if token.kind == "identifier":
            function = token.value
            if function in self.variables and self._peek() != "(":
                return ("var", function)
            if function in {"TRUE", "FALSE"}:
                if self._peek() == "(":
                    self._take()
                    self._expect(")")
                return ("boolean", function == "TRUE")
            if function == "BLANK":
                self._expect("(")
                self._expect(")")
                return ("blank",)
            if function in {"DISTINCT", "VALUES"} and self._peek() == "(":
                self._take()
                argument = self._expression()
                self._expect(")")
                if argument[0] not in {"reference", "table", "call", "table_call", "tableconstructor", "var", "let"}:
                    raise MeasureError(f"{function} needs one source column reference or table.")
                return ("table_call", function, argument)
            if function not in _FUNCTIONS:
                if self._peek() in {",", ")"} or (self._in_var_binding and (self._is_keyword("RETURN") or self._is_keyword("VAR"))):
                    return ("table", function)
                raise MeasureError(f"Function {function} is not supported by the local DAX engine.")
            if self._peek() in {",", ")"}:
                return ("table", function)  # a keyword such as MONTH in DATEDIFF(...) or INTEGER in CONVERT(...)
            self._expect("(")
            arguments: list[tuple[Any, ...]] = []
            if self._peek() != ")":
                while True:
                    if self._peek() == ",":
                        arguments.append(("omitted",))
                    else:
                        arguments.append(self._expression())
                    if self._peek() != ",":
                        break
                    self._take()
                    if self._peek() == ")":
                        arguments.append(("omitted",))
                        break
            self._expect(")")
            if function in dax_math.STAT_PERCENTILE_COLUMN and len(arguments) == 2 and arguments[1][0] == "blank":
                arguments[1] = ("number", Decimal(0))  # live Power BI (iteration 88): a BLANK() percentile is 0 (PERCENTILE.EXC of 0 is an error)
            if function in {"PERCENTILEX.INC", "PERCENTILEX.EXC"} and len(arguments) == 3 and arguments[2][0] == "blank":
                arguments[2] = ("number", Decimal(0))
            if function == "RELATEDTABLE":  # CALCULATETABLE(table): the row context of the enclosing iterator becomes the filter
                if len(arguments) != 1 or arguments[0][0] != "table":
                    raise MeasureError("RELATEDTABLE needs one table, such as RELATEDTABLE('Sales').")
                return ("call", "CALCULATETABLE", (arguments[0],))
            if function in dax_time_sets.BALANCES:
                return _balance_call(function, arguments)
            if (
                (function in _ROW_ORDER_FUNCTIONS or function in {"TOCSV", "TOJSON"})
                and any(_contains_function_call(argument, "TABLEOF") for argument in arguments)
                and not (function == "TOPN" and len(arguments) > 1 and arguments[1][:2] == ("call", "TABLEOF"))  # TOPN straight over TABLEOF: the rows kept are the same set whatever the walk order
                and function != "CONCATENATEX"  # checked where the rows are known: more than one row of anything but a bare TABLEOF is refused there
            ):
                # live Power BI (iteration 92, Task 10 review): TABLEOF hands the rows over in the engine's own order, not the table's; it is modelled only for CONCATENATEX straight over TABLEOF
                raise MeasureError(f"{function} over TABLEOF depends on the row order, which is not modelled in the local engine.")
            if function in dax_time_sets.SET_FUNCTIONS and _time_set_call_is_new_form(function, arguments):
                _validate_time_set_call(function, arguments)
            elif function in dax_math.STAT_PERCENTILE_COLUMN:
                if len(arguments) != 2 or arguments[0][0] != "reference":
                    raise MeasureError(f"{function} needs a column reference and a percentile between 0 and 1.")
            elif function in {
                "SUM", "AVERAGE", "MIN", "MAX", "COUNT", "COUNTA",
                "DISTINCTCOUNT", "DISTINCTCOUNTNOBLANK", "MEDIAN", "PRODUCT", "COUNTBLANK",
            } | dax_math.STAT_COLUMN_FUNCTIONS:
                if function in {"MIN", "MAX"} and len(arguments) == 2 and all(a[0] != "omitted" for a in arguments):
                    pass  # MAX(a, b) / MIN(a, b): the scalar form
                elif len(arguments) != 1 or arguments[0][0] != "reference":
                    raise MeasureError(f"{function} needs one column reference, such as {function}([Amount]).")
            elif function == "COUNTROWS":
                if arguments and arguments[0][0] == "call" and arguments[0][1] == "KEEPFILTERS":
                    raise MeasureError("KEEPFILTERS function can only be used as a top level filter argument of CALCULATE and CALCULATETABLE or with a table argument of a function performing a table scan.")
                if (
                    len(arguments) > 1
                    or (arguments and not _is_all_table_value_argument(arguments[0]))
                ):
                    if arguments and arguments[0][0] == "call" and arguments[0][1] == "ALLCROSSFILTERED":
                        raise MeasureError("ALLCROSSFILTERED function cannot be used as a table expression. It can appear only as a filter in CALCULATE.")
                    raise MeasureError(
                        "COUNTROWS needs no argument or one loaded table/ALL table expression."
                    )
            elif function == "TOCSV":
                if len(arguments) < 1:
                    raise MeasureError("Too few arguments were passed to the TOCSV function. The minimum argument count for the function is 1.")
                if len(arguments) > 4:
                    raise MeasureError("Too many arguments were passed to the TOCSV function. The maximum argument count for the function is 4.")
                if arguments[0][0] == "call" and arguments[0][1] == "KEEPFILTERS":
                    raise MeasureError("KEEPFILTERS function can only be used as a top level filter argument of CALCULATE and CALCULATETABLE or with a table argument of a function performing a table scan.")
                if not _is_all_table_value_argument(arguments[0]):
                    raise MeasureError("The TOCSV function expects a table expression for argument '1', but a string or numeric expression was used.")
                if len(arguments) > 1:
                    _tocsv_max_rows(arguments[1])
            elif function == "TOJSON":
                if len(arguments) < 1:
                    raise MeasureError("Too few arguments were passed to the TOJSON function. The minimum argument count for the function is 1.")
                if len(arguments) > 2:
                    raise MeasureError("Too many arguments were passed to the TOJSON function. The maximum argument count for the function is 2.")
                if arguments[0][0] == "call" and arguments[0][1] == "KEEPFILTERS":
                    raise MeasureError("KEEPFILTERS function can only be used as a top level filter argument of CALCULATE and CALCULATETABLE or with a table argument of a function performing a table scan.")
                if not _is_all_table_value_argument(arguments[0]):
                    raise MeasureError("The TOJSON function expects a table expression for argument '1', but a string or numeric expression was used.")
                if len(arguments) > 1:
                    _tocsv_max_rows(arguments[1])
            elif function == "LINEST":
                if len(arguments) < 2:
                    raise MeasureError("Too few arguments were passed to the LINEST function. The minimum argument count for the function is 2.")
                has_const = len(arguments) > 2 and _linest_is_const_literal(arguments[-1])
                col_args = arguments[:-1] if has_const else arguments
                for idx, arg in enumerate(col_args):
                    if arg[0] != "reference":
                        raise MeasureError(f"The LINEST function only accepts a column reference as the argument number {idx + 1}.")
                if len(arguments) > 2 and not has_const and arguments[-1][0] != "reference":
                    raise MeasureError(f"The LINEST function only accepts a column reference as the argument number {len(arguments)}.")
            elif function == "LINESTX":
                if len(arguments) < 3:
                    raise MeasureError("Too few arguments were passed to the LINESTX function. The minimum argument count for the function is 3.")
                if not _is_all_table_value_argument(arguments[0]):
                    raise MeasureError("The LINESTX function expects a table expression for argument '1', but a string or numeric expression was used.")
            elif function == "DIVIDE" and len(arguments) not in {2, 3}:
                raise MeasureError("DIVIDE needs a numerator, denominator, and optional alternate result.")
            elif function == "COALESCE" and (
                len(arguments) < 2
                or any(argument[0] == "omitted" for argument in arguments)
            ):
                raise MeasureError(
                    "COALESCE needs at least two non-omitted scalar expressions."
                )
            elif function == "COALESCE" and any(
                _is_coalesce_table_argument(argument) for argument in arguments
            ):
                raise MeasureError(
                    "COALESCE needs scalar expressions; table-valued arguments are not supported."
                )
            elif function == "ABS" and len(arguments) != 1:
                raise MeasureError("ABS needs one numeric expression.")
            elif function == "CONCATENATEX" and (
                len(arguments) < 2 or not _is_all_table_value_argument(arguments[0])
            ):
                raise MeasureError(
                    "CONCATENATEX needs a table, an expression, and optional delimiter and order arguments."
                )
            elif function == "XNPV":
                if len(arguments) < 4:
                    raise MeasureError("Too few arguments were passed to the XNPV function. The minimum argument count for the function is 4.")
                if len(arguments) > 4:
                    raise MeasureError("Too many arguments were passed to the XNPV function. The maximum argument count for the function is 4.")
                if not _is_all_table_value_argument(arguments[0]):
                    raise MeasureError("The XNPV function expects a table expression for argument '1', but a string or numeric expression was used.")
                if any(argument[0] == "omitted" for argument in arguments):
                    raise MeasureError("The XNPV function does not accept omitted arguments.")
            elif function == "XIRR":
                if len(arguments) < 3:
                    raise MeasureError("Too few arguments were passed to the XIRR function. The minimum argument count for the function is 3.")
                if len(arguments) > 5:
                    raise MeasureError("Too many arguments were passed to the XIRR function. The maximum argument count for the function is 5.")
                if not _is_all_table_value_argument(arguments[0]):
                    raise MeasureError("The XIRR function expects a table expression for argument '1', but a string or numeric expression was used.")
                if any(argument[0] == "omitted" for argument in arguments):
                    raise MeasureError("The XIRR function does not accept omitted arguments.")
            elif function == "IF.EAGER":
                if len(arguments) < 2:
                    raise MeasureError("Too few arguments were passed to the IF.EAGER function. The minimum argument count for the function is 2.")
                if len(arguments) > 3:
                    raise MeasureError("Too many arguments were passed to the IF.EAGER function. The maximum argument count for the function is 3.")
                if any(_is_all_table_value_argument(arg) or _is_coalesce_table_argument(arg) for arg in arguments[1:]):
                    raise MeasureError("The expression refers to multiple columns. Multiple columns cannot be converted to a scalar value.")
            elif function == "ERROR":
                if len(arguments) < 1:
                    raise MeasureError("Too few arguments were passed to the ERROR function. The minimum argument count for the function is 1.")
                if len(arguments) > 1:
                    raise MeasureError("Too many arguments were passed to the ERROR function. The maximum argument count for the function is 1.")
                if arguments[0][0] != "string":
                    raise MeasureError("The function 'ERROR' expects its argument number 1 to be constant.")
            elif function in {"CUSTOMDATA", "UTCNOW", "UTCTODAY", "COLUMNSTATISTICS"}:
                if len(arguments) > 0:
                    raise MeasureError(f"Too many arguments were passed to the {function} function. The maximum argument count for the function is 0.")
            elif function == "NAMEOF":
                if len(arguments) < 1:
                    raise MeasureError("Too few arguments were passed to the NAMEOF function. The minimum argument count for the function is 1.")
                if len(arguments) > 1:
                    raise MeasureError("Valid arguments for component are TABLE, COLUMN, MEASURE, CALENDAR, FULL, SELF, and PARENT.")
                arg = arguments[0]
                if arg[0] not in {"reference", "table"} or (arg[0] == "reference" and not arg[1]):
                    raise MeasureError("Only measure or fully-qualified column or table or calendar references are allowed in NAMEOF function.")
            elif function == "TABLEOF":
                if len(arguments) < 1:
                    raise MeasureError("Too few arguments were passed to the TABLEOF function. The minimum argument count for the function is 1.")
                if len(arguments) > 1:
                    raise MeasureError("Too many arguments were passed to the TABLEOF function. The maximum argument count for the function is 1.")
                arg = arguments[0]
                if arg[0] != "reference" or not arg[1]:
                    raise MeasureError("The TABLEOF function only accepts a column reference, measure reference, or calendar reference as the argument number 1.")
            elif function == "EVALUATEANDLOG":
                if len(arguments) < 1:
                    raise MeasureError("Too few arguments were passed to the EVALUATEANDLOG function. The minimum argument count for the function is 1.")
                if len(arguments) > 3:
                    raise MeasureError("Too many arguments were passed to the EVALUATEANDLOG function. The maximum argument count for the function is 3.")
            elif function == "ALLCROSSFILTERED":
                if len(arguments) != 1:
                    raise MeasureError("ALLCROSSFILTERED needs one table expression.")
                if arguments[0][0] == "reference":
                    raise MeasureError(
                        f"A single value for column '{arguments[0][2]}' in table '{arguments[0][1]}' cannot be determined. "
                        "This can happen when a measure or function formula refers to a column that contains many values "
                        "without specifying an aggregation such as min, max, count, or sum to get a single result."
                    )
                if arguments[0][0] != "table":
                    raise MeasureError("ALLCROSSFILTERED needs one table expression.")
            elif function in {"ISONORAFTER", "ISAFTER"}:
                if len(arguments) < 2:
                    raise MeasureError(f"Too few arguments were passed to the {function} function. The minimum argument count for the function is 2.")
                if len(arguments) % 3 == 1:
                    raise MeasureError("IsOnOrAfter() function contains a scalar expression to compare without a value to compare against.")
            elif function == "SUBSTITUTEWITHINDEX":
                if len(arguments) < 4:
                    raise MeasureError(f"Too few arguments were passed to the {function} function. The minimum argument count for the function is 4.")
                if arguments[1][0] not in {"string", "var"} or (arguments[1][0] == "string" and not arguments[1][1]):
                    raise MeasureError(f"Function {function} expects a column name as argument number 2.")
            elif function == "ADDMISSINGITEMS":
                if not arguments:
                    raise MeasureError(f"Too few arguments were passed to the {function} function. The minimum argument count for the function is 1.")
                chk_i = 0
                while chk_i < len(arguments) and arguments[chk_i][0] == "reference":
                    chk_i += 1
                if chk_i >= len(arguments):
                    raise MeasureError(f"ADDMISSINGITEMS function expects a table in argument number {chk_i + 1}.")
                if not _is_all_table_value_argument(arguments[chk_i]):
                    raise MeasureError(f"The function expects a table expression for argument '{chk_i + 1}', but a string or numeric expression was used.")
            elif function in {"ROLLUP", "ROLLUPGROUP"}:
                if not arguments:
                    raise MeasureError(f"Too few arguments were passed to the {function} function. The minimum argument count for the function is 1.")
            elif function == "ISSUBTOTAL":
                if len(arguments) != 1:
                    raise MeasureError("Too few arguments were passed to the ISSUBTOTAL function." if len(arguments) < 1 else "Too many arguments were passed to the ISSUBTOTAL function.")
                if arguments[0][0] != "reference":
                    raise MeasureError("ISSUBTOTAL needs one column reference.")
            elif function in {"ROLLUPADDISSUBTOTAL", "ROLLUPISSUBTOTAL"}:
                if len(arguments) < 2:
                    raise MeasureError(f"Too few arguments were passed to the {function} function. The minimum argument count for the function is 2.")
            elif function in _INFO_UNAVAILABLE_FUNCTIONS:
                raise MeasureError(
                    "The operation cannot be performed because it references an object or property that is unavailable in the current edition of the server or the compatibility level of the database."
                )
            elif function in {"INFO.VIEW.TABLES", "INFO.VIEW.COLUMNS", "INFO.VIEW.MEASURES", "INFO.VIEW.RELATIONSHIPS"}:
                if len(arguments) > 0:
                    raise MeasureError(f"Too many arguments were passed to the {function} function. The maximum argument count for the function is 0.")
            elif function in _INFO_RESTRICTION_FUNCTIONS:
                if len(arguments) > 0:
                    if arguments[0][0] != "string":
                        raise MeasureError(f"The '{function}' function expects a constant string representing a restriction name.")
                    raise MeasureError(f"'{arguments[0][1]}' is not a valid restriction name.")
            elif function in _TABLE_FUNCTION_ARITY and not (
                _TABLE_FUNCTION_ARITY[function][0] <= len(arguments)
                and (_TABLE_FUNCTION_ARITY[function][1] is None or len(arguments) <= _TABLE_FUNCTION_ARITY[function][1])
                and (function in {"INDEX", "OFFSET", "WINDOW"} or all(argument[0] != "omitted" for argument in arguments))
            ):
                raise MeasureError(f"{function} has the wrong number of arguments.")
            elif function == "ADDCOLUMNS" and len(arguments) % 2 == 0:
                raise MeasureError(f"{function} needs a table followed by pairs of a column name and an expression.")
            elif function in _RANK_ARITY and not (
                _RANK_ARITY[function][0] <= len(arguments) <= _RANK_ARITY[function][1]
            ):
                raise MeasureError(f"{function} has the wrong number of arguments.")
            elif function in _LOOKUP_ARITY and not (
                _LOOKUP_ARITY[function][0] <= len(arguments)
                and (_LOOKUP_ARITY[function][1] is None or len(arguments) <= _LOOKUP_ARITY[function][1])
                and all(argument[0] != "omitted" for argument in arguments)
            ):
                raise MeasureError(f"{function} has the wrong number of arguments.")
            elif function in {"FIRSTNONBLANK", "LASTNONBLANK", "FIRSTNONBLANKVALUE", "LASTNONBLANKVALUE"} and arguments[0][0] in {
                "number", "string", "boolean", "blank", "unary", "binary",
            }:
                raise MeasureError(f"{function} needs a column reference and an expression.")
            elif function == "ROW":
                if len(arguments) % 2:
                    raise MeasureError("ROW needs pairs of a column name and an expression.")
                for i in range(0, len(arguments), 2):
                    if arguments[i][0] not in {"string", "var"}:  # a VAR holding a constant text works in Power BI; its value is checked when ROW is evaluated
                        raise MeasureError(f"Function ROW expects a column name as argument number {i + 1}.")
            elif function in _COLUMN_SCALAR_ARITY and not (
                _COLUMN_SCALAR_ARITY[function][0] <= len(arguments) <= _COLUMN_SCALAR_ARITY[function][1]
                and arguments[0][0] == "reference"
            ):
                raise MeasureError(f"{function} needs a column reference{' and an optional alternate result' if function == 'SELECTEDVALUE' else ''}.")
            elif function in _TYPED_ARITY and not (
                _TYPED_ARITY[function][0] <= len(arguments) <= _TYPED_ARITY[function][1]
                and all(argument[0] != "omitted" for argument in arguments)
            ):
                low, high = _TYPED_ARITY[function]
                raise MeasureError(f"{function} needs {low if low == high else f'{low} to {high}'} argument(s).")
            elif function in _SCALAR_MATH_ARITY and not (
                _SCALAR_MATH_ARITY[function][0]
                <= len(arguments)
                <= _SCALAR_MATH_ARITY[function][1]
            ):
                low, high = _SCALAR_MATH_ARITY[function]
                raise MeasureError(
                    f"{function} needs {low if low == high else f'{low} or {high}'} numeric argument(s)."
                )
            elif function == "ROUND" and len(arguments) != 2:
                raise MeasureError("ROUND needs a numeric expression and a number of digits.")
            elif function in {"IF", "SWITCH"} and len(arguments) >= 2 and _mixes_table_and_scalar_branches(function, arguments):
                raise MeasureError(f"{function} cannot return a table in one branch and a single value in another.")
            elif function == "IF" and len(arguments) not in {2, 3}:
                raise MeasureError(
                    "IF needs a condition, a value for true, and an optional value for false."
                )
            elif function == "ISBLANK" and len(arguments) != 1:
                raise MeasureError("ISBLANK needs one argument.")
            elif function == "IFERROR" and len(arguments) != 2:
                raise MeasureError("IFERROR needs a value and a value to use if it is an error.")
            elif function == "SWITCH" and len(arguments) < 3:
                raise MeasureError(
                    "SWITCH needs an expression and at least one value/result pair."
                )
            elif function in {"AND", "OR"} and len(arguments) != 2:
                raise MeasureError(f"{function} needs two logical expressions.")
            elif function == "NOT" and len(arguments) != 1:
                raise MeasureError("NOT needs one logical expression.")
            elif function == "KEEPFILTERS" and len(arguments) != 1:
                raise MeasureError("KEEPFILTERS needs one filter expression.")
            elif function in _ALL_ITERATORS and (
                len(arguments) != (3 if function.startswith("PERCENTILEX") else 2)
                or not _is_all_table_value_argument(arguments[0])
            ):
                raise MeasureError(
                    f"{function} needs a loaded table or ALL table expression and one scalar expression."
                )
            elif function == "RELATED" and (
                len(arguments) != 1
                or arguments[0][0] != "reference"
                or not arguments[0][1]
            ):
                raise MeasureError(
                    "RELATED needs one fully qualified column reference, such as RELATED('Products'[Unit Price])."
                )
            elif function in {"TOTALYTD", "TOTALQTD", "TOTALMTD"}:
                if any(argument[0] == "omitted" for argument in arguments):
                    # live Power BI: an empty argument is an error, TOTALYTD(e, d, , "6/30") included
                    omitted_at = next(index for index, argument in enumerate(arguments) if argument[0] == "omitted") + 1
                    raise MeasureError(f"Argument '{omitted_at}' in {function} function is required.")
                year_end = None
                rest = list(arguments[2:])
                if function == "TOTALYTD" and len(rest) in {1, 2} and rest[-1][0] == "string":
                    year_end = rest.pop()
                if (
                    len(arguments) < 2 or arguments[1][0] != "reference" or len(rest) > 1
                    or (rest and rest[0][0] == "string") or (function != "TOTALYTD" and len(arguments) > 3)
                ):
                    raise MeasureError(
                        f"{function} needs an expression, a date column reference and an optional filter"
                        + (' and a "M/D" year end.' if function == "TOTALYTD" else ".")
                    )
                if year_end is not None:
                    _parse_year_end_date(year_end[1])
                if rest and not _general_calculate_filters_valid((rest[0],)):
                    raise MeasureError(f"{function} needs an expression and marked date-column reference. Filter expressions are not supported unless they are Boolean or table filters.")
            elif function == "DATESYTD":
                valid_arguments = (
                    len(arguments) == 1 and arguments[0][0] == "reference"
                ) or (
                    len(arguments) == 2
                    and arguments[0][0] == "reference"
                    and arguments[1][0] == "string"
                )
                if not valid_arguments:
                    raise MeasureError(
                        'DATESYTD needs a marked date-column reference and optional '
                        'M/D year-end string, such as DATESYTD(\'Calendar\'[Date], "6/30").'
                )
                if len(arguments) == 2:
                    _parse_year_end_date(arguments[1][1])
            elif function == "DATESQTD":
                if len(arguments) != 1 or arguments[0][0] != "reference":
                    raise MeasureError(
                        "DATESQTD needs one marked date-column reference."
                    )
            elif function == "DATESMTD":
                if len(arguments) != 1 or arguments[0][0] != "reference":
                    raise MeasureError(
                        "DATESMTD needs one marked date-column reference."
                    )
            elif function == "DATESBETWEEN":
                valid_arguments = (
                    len(arguments) == 3
                    and arguments[0][0] == "reference"
                    and arguments[1][0] not in {"table", "omitted", "boolean"}
                    and arguments[2][0] not in {"table", "omitted", "boolean"}
                )
                if not valid_arguments:
                    raise MeasureError(
                        'DATESBETWEEN needs a marked date-column reference and date, ISO '
                        'date text or BLANK() start/end bounds.'
                    )
            elif function == "DATESINPERIOD":
                valid_interval = (
                    len(arguments) == 4
                    and arguments[0][0] == "reference"
                    and arguments[1][0] not in {"table", "omitted", "boolean"}
                    and arguments[2][0] not in {"table", "omitted", "boolean", "string"}
                    and arguments[3][0] == "table"
                    and str(arguments[3][1]).upper()
                    in {"DAY", "MONTH", "QUARTER", "YEAR"}
                )
                if not valid_interval:
                    raise MeasureError(
                        "DATESINPERIOD needs a marked date-column reference, a start date, "
                        "an interval count, and DAY, MONTH, QUARTER, or YEAR."
                    )
            elif function == "DATEADD":
                valid_interval = (
                    len(arguments) == 3
                    and arguments[0][0] == "reference"
                    and arguments[2][0] == "table"
                    and str(arguments[2][1]).upper() in {"YEAR", "QUARTER", "MONTH", "DAY"}
                )
                if not valid_interval or arguments[1][0] in {"table", "string", "omitted"}:
                    raise MeasureError(
                        "DATEADD needs a date-column reference, numeric interval count, "
                        "and YEAR, QUARTER, MONTH, or DAY interval."
                    )
            elif function == "SAMEPERIODLASTYEAR":
                if len(arguments) != 1 or arguments[0][0] != "reference":
                    raise MeasureError(
                        "SAMEPERIODLASTYEAR needs one marked date-column reference."
                    )
            elif function in {"PREVIOUSYEAR", "NEXTYEAR"}:
                valid_arguments = (
                    len(arguments) == 1 and arguments[0][0] == "reference"
                ) or (
                    len(arguments) == 2
                    and arguments[0][0] == "reference"
                    and arguments[1][0] == "string"
                )
                if not valid_arguments:
                    raise MeasureError(
                        f"{function} needs a marked date-column reference and an "
                        "optional M/D year-end string."
                    )
                if len(arguments) == 2:
                    _parse_year_end_date(arguments[1][1])
            elif function in {"PREVIOUSQUARTER", "PREVIOUSMONTH", "PREVIOUSDAY", "NEXTQUARTER", "NEXTMONTH", "NEXTDAY"}:
                if len(arguments) != 1 or arguments[0][0] != "reference":
                    raise MeasureError(
                        f"{function} needs one marked date-column reference."
                    )
            elif function == "PARALLELPERIOD":
                valid_interval = (
                    len(arguments) == 3
                    and arguments[0][0] == "reference"
                    and arguments[2][0] == "table"
                    and str(arguments[2][1]).upper() in {"YEAR", "QUARTER", "MONTH"}
                )
                if not valid_interval or arguments[1][0] in {"table", "string", "omitted"}:
                    raise MeasureError(
                        "PARALLELPERIOD needs a date-column reference, numeric interval count, "
                        "and YEAR, QUARTER, or MONTH interval."
                    )
            elif function == "FILTER":
                try:
                    _validate_table_filter_call(
                        ("call", function, tuple(arguments)), allow_all_base=True
                    )
                except MeasureError:
                    # any table expression and any row predicate is valid DAX; it is evaluated row by row
                    if len(arguments) != 2 or not _is_all_table_value_argument(arguments[0]):
                        raise
            elif function in {"REMOVEFILTERS", "ALL", "ALLNOBLANKROW", "ALLSELECTED"}:
                _validate_filter_clear_call(
                    ("call", function, tuple(arguments)), function
                )
                if function == "ALLNOBLANKROW" and not arguments:
                    raise MeasureError("ALLNOBLANKROW needs a table or column argument.")
            elif function == "ALLEXCEPT":
                _validate_allexcept_call(("call", function, tuple(arguments)))
            elif function == "USERELATIONSHIP":
                _validate_userelationship_call(("call", function, tuple(arguments)))
            elif function == "CROSSFILTER":
                _validate_crossfilter_call(("call", function, tuple(arguments)))
            elif function == "CALCULATE":
                if not arguments:
                    raise MeasureError("CALCULATE needs an expression.")
                try:
                    contains_userelationship = any(
                        _contains_function_call(argument, "USERELATIONSHIP")
                        for argument in arguments[1:]
                    )
                    if contains_userelationship:
                        modifiers = tuple(
                            argument
                            for argument in arguments[1:]
                            if argument[0] == "call"
                            and argument[1] == "USERELATIONSHIP"
                        )
                        filter_arguments = tuple(
                            argument
                            for argument in arguments[1:]
                            if not (
                                argument[0] == "call"
                                and argument[1] == "USERELATIONSHIP"
                            )
                        )
                        if not modifiers or any(
                            _contains_function_call(argument, "USERELATIONSHIP")
                            for argument in filter_arguments
                        ):
                            raise MeasureError(
                                "USERELATIONSHIP must be a direct CALCULATE filter modifier in this local subset."
                            )
                        for modifier in modifiers:
                            _validate_userelationship_call(modifier)
                        _validate_relationship_modifier_filters(filter_arguments)
                        return ("call", function, tuple(arguments))
                    contains_crossfilter = any(
                        _contains_function_call(argument, "CROSSFILTER")
                        for argument in arguments[1:]
                    )
                    if contains_crossfilter:
                        modifiers = tuple(
                            argument
                            for argument in arguments[1:]
                            if argument[0] == "call"
                            and argument[1] == "CROSSFILTER"
                        )
                        filter_arguments = tuple(
                            argument
                            for argument in arguments[1:]
                            if not (
                                argument[0] == "call"
                                and argument[1] == "CROSSFILTER"
                            )
                        )
                        if not modifiers or any(
                            _contains_function_call(argument, "CROSSFILTER")
                            for argument in filter_arguments
                        ):
                            raise MeasureError(
                                "CROSSFILTER must be a direct CALCULATE filter modifier in this local subset."
                            )
                        for modifier in modifiers:
                            _validate_crossfilter_call(modifier)
                        _validate_relationship_modifier_filters(filter_arguments)
                        return ("call", function, tuple(arguments))
                    valid_time_filter = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] in _TIME_FILTER_FUNCTIONS
                    )
                    valid_table_filter = (
                        len(arguments) == 2
                        and _is_table_filter_argument(arguments[1], legacy=True)
                    )
                    valid_removefilters = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] == "REMOVEFILTERS"
                    )
                    valid_all = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] == "ALL"
                    )
                    valid_allnoblankrow = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] == "ALLNOBLANKROW"
                    )
                    valid_allexcept = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] == "ALLEXCEPT"
                    )
                    valid_allselected = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] == "ALLSELECTED"
                    )
                    valid_allcrossfiltered = (
                        len(arguments) == 2
                        and arguments[1][0] == "call"
                        and arguments[1][1] == "ALLCROSSFILTERED"
                    )
                    contains_filter_clear = {
                        clear_function
                        for clear_function in {
                            "REMOVEFILTERS", "ALL", "ALLNOBLANKROW", "ALLEXCEPT", "ALLSELECTED", "ALLCROSSFILTERED"
                        }
                        if any(
                            _contains_function_call(argument, clear_function)
                            for argument in arguments[1:]
                        )
                    }
                    if contains_filter_clear and _validate_mixed_filter_clear_calculate(
                        tuple(arguments)
                    ):
                        return ("call", function, tuple(arguments))
                    if contains_filter_clear and not (
                        valid_removefilters or valid_all or valid_allnoblankrow or valid_allexcept or valid_allselected or valid_allcrossfiltered
                    ):
                        clear_function = sorted(contains_filter_clear)[0]
                        raise MeasureError(
                            f"{clear_function} must be the only CALCULATE filter argument in this local subset."
                        )
                    if valid_removefilters or valid_all or valid_allnoblankrow or valid_allexcept or valid_allselected or valid_allcrossfiltered:
                        if valid_allexcept:
                            _validate_allexcept_call(arguments[1])
                        else:
                            _validate_filter_clear_call(arguments[1], arguments[1][1])
                        if valid_allnoblankrow and not arguments[1][2]:
                            raise MeasureError(
                                "ALLNOBLANKROW needs a table or column argument."
                            )
                        return ("call", function, tuple(arguments))
                    contains_table_filter = any(
                        _contains_function_call(argument, "FILTER")
                        for argument in arguments[1:]
                    )
                    if contains_table_filter and not valid_table_filter:
                        raise MeasureError(
                            "A table-valued FILTER must be the only CALCULATE filter argument."
                        )
                    contains_time_filter = any(
                        argument[0] == "call" and argument[1] in _TIME_FILTER_FUNCTIONS
                        for argument in arguments[1:]
                    )
                    if not valid_time_filter and not valid_table_filter:
                        for filter_argument in arguments[1:]:
                            if filter_argument[0] == "call" and filter_argument[1] in _TIME_FILTER_FUNCTIONS:
                                continue
                            predicate, _keep = _calculate_filter_argument(filter_argument)
                            _calculate_boolean_filter_column(predicate)
                except MeasureError:
                    if not _general_calculate_filters_valid(tuple(arguments[1:])) and not _modifier_mix_filters_valid(tuple(arguments[1:])) and not _time_filters_beside_general_filters(tuple(arguments)):
                        raise
            if (function in _ALL_ITERATORS or function in {"CONCATENATEX", "XNPV", "XIRR"} or function == "FILTER") and len(arguments) >= 2:
                _check_set_iterator_body(arguments[0], arguments[1])  # live Power BI: FILTER(date set, ..) reads only the set's own column too
                if function in {"XNPV", "XIRR"} and len(arguments) >= 3:
                    _check_set_iterator_body(arguments[0], arguments[2])
            if function in {"UNION", "EXCEPT", "INTERSECT", "CROSSJOIN"} and any(argument[0] == "reference" for argument in arguments):
                # live Power BI (iteration 84, critic): a bare column where a table is expected is a compile-time error
                # ("A single value for column .. cannot be determined"), also in a branch that is never run
                raise MeasureError(f"{function} needs table expressions; a column reference has no single value.")
            if function == "FILTER" and len(arguments) == 2:
                _check_single_column_filter(arguments[0], arguments[1])
            return ("call", function, tuple(arguments))
        raise MeasureError(f"Unexpected token {token.value!r}; expected a number, measure, or function.")

    def _peek(self) -> str | None:
        return self.tokens[self.index].kind if self.index < len(self.tokens) else None

    def _take(self) -> Token:
        if self.index >= len(self.tokens):
            raise MeasureError("The DAX expression ends unexpectedly.")
        token = self.tokens[self.index]
        self.index += 1
        return token

    def _expect(self, kind: str) -> None:
        token = self._take()
        if token.kind != kind:
            raise MeasureError(f"Expected {kind!r}, found {token.value!r}.")


_TOTAL_TO_DATES = {"TOTALYTD": "DATESYTD", "TOTALQTD": "DATESQTD", "TOTALMTD": "DATESMTD"}


def _rewrite_total_td(node: Any, filter_position: bool = False) -> Any:
    """TOTALYTD(e, d [, filter] [, year_end]) is CALCULATE(e, DATESYTD(d [, year_end]) [, filter]) (live Power BI, 567 of 567
    pairs); TOTALQTD / TOTALMTD take no year end.  An omitted argument, a year end that is not a text literal or a filter in
    the CALCULATE filter list keeps the original call, which the validators refuse."""
    if isinstance(node, list):
        return [_rewrite_total_td(item) for item in node]
    if not isinstance(node, tuple) or not node:
        return node
    if node[0] == "call":
        function, arguments = node[1], node[2]
        in_filters = function in {"CALCULATE", "CALCULATETABLE"}
        new_arguments = tuple(_rewrite_total_td(argument, in_filters and index >= 1) for index, argument in enumerate(arguments))
        rewritten = (node[0], function, new_arguments, *node[3:])
        if function in _TOTAL_TO_DATES and not filter_position and 2 <= len(new_arguments) <= 4:
            expression, dates, rest = new_arguments[0], new_arguments[1], list(new_arguments[2:])
            if dates[0] != "reference" or any(item[0] == "omitted" for item in new_arguments):
                return rewritten
            year_end = None
            if function == "TOTALYTD" and rest and rest[-1][0] == "string" and (len(rest) == 2 or len(rest) == 1):
                year_end = rest.pop()
            if len(rest) > 1 or (rest and rest[0][0] == "string") or (function != "TOTALYTD" and len(new_arguments) > 3):
                return rewritten
            date_set = ("call", _TOTAL_TO_DATES[function], (dates,) if year_end is None else (dates, year_end))
            return ("call", "CALCULATE", (expression, date_set, *rest))
        return rewritten
    return tuple(_rewrite_total_td(child) if isinstance(child, (tuple, list)) else child for child in node)


def parse_expression(expression: str) -> tuple[Any, ...]:
    """Parse one supported DAX expression into a safe internal tree."""
    return _Parser(tokenize(expression)).parse()


def _contains_table_call(node: Any) -> bool:
    if not isinstance(node, tuple) or not node:
        return False
    return (
        node[0] == "table_call"
        or (
            node[0] == "call"
            and node[1] in {
                "DATEADD", "SAMEPERIODLASTYEAR", "PREVIOUSYEAR", "PREVIOUSQUARTER", "PREVIOUSMONTH",
                "DATESYTD", "DATESQTD", "DATESMTD", "DATESBETWEEN", "DATESINPERIOD", "FILTER", "ALL", "ALLNOBLANKROW", "ALLEXCEPT", "ALLSELECTED",
            }
        )
        or any(
            _contains_table_call(child) for child in node[1:]
        )
    )


def _is_supported_time_filter_calculate(node: Any) -> bool:
    if not (
        isinstance(node, tuple)
        and len(node) == 3
        and node[0] == "call"
        and node[1] == "CALCULATE"
        and len(node[2]) >= 2
    ):
        return False
    # Verify that there's at least one time-filter argument
    has_time_filter = any(
        arg[0] == "call" and arg[1] in _TIME_FILTER_FUNCTIONS
        for arg in node[2][1:]
    )
    if not has_time_filter:
        return False
    return not _contains_table_call(node[2][0])


def _is_supported_table_filter_calculate(node: Any) -> bool:
    if not (
        isinstance(node, tuple)
        and len(node) == 3
        and node[0] == "call"
        and node[1] == "CALCULATE"
        and len(node[2]) == 2
        and node[2][1][0] == "call"
        and node[2][1][1] == "FILTER"
    ):
        return False
    return not _contains_table_call(node[2][0])


def normalize_calculated_table_expression(
    expression: Any,
    source_table: Any,
    headers: Iterable[str] | None = None,
) -> dict[str, str]:
    """Validate the local one-column DISTINCT calculated-table subset."""
    if not isinstance(expression, str) or not expression.strip():
        raise MeasureError("Enter a calculated-table expression.")
    if not isinstance(source_table, str) or not source_table.strip():
        raise MeasureError("Choose a source table for the calculated table.")
    clean_expression = expression.strip(_DAX_WHITESPACE)
    node = parse_expression(clean_expression)
    if node[0] != "table_call" or node[1] != "DISTINCT":
        raise MeasureError(
            "Calculated tables currently support DISTINCT('Table'[Column]) expressions."
        )
    reference = node[2]
    if reference[0] != "reference" or not reference[1]:
        raise MeasureError("Use a qualified source column, such as DISTINCT('Sales'[Region]).")
    if reference[1].casefold() != source_table.strip().casefold():
        raise MeasureError(
            f"The expression must reference the selected source table {source_table!r}."
        )
    if headers is not None:
        columns_by_key = {str(header).casefold(): str(header) for header in headers}
        actual = columns_by_key.get(reference[2].casefold())
        if actual is None:
            raise MeasureError(f"Column {reference[2]!r} does not exist in {source_table!r}.")
        return {"expression": clean_expression, "source_table": source_table.strip(), "column": actual}
    return {
        "expression": clean_expression,
        "source_table": source_table.strip(),
        "column": reference[2],
    }


def evaluate_calculated_table(
    expression: Any,
    source_candidate: Any,
    source_table: Any,
) -> tuple[list[str], list[dict[str, Any]]]:
    """Materialize DISTINCT over one loaded column, preserving first-seen order."""
    definition = normalize_calculated_table_expression(
        expression, source_table, source_candidate.headers
    )
    column = definition["column"]
    seen: set[tuple[Any, ...]] = set()
    rows: list[dict[str, Any]] = []
    for source_row in source_candidate.rows:
        value = source_row.get(column)
        _reject_power_query_error(value, column, len(rows) + 1)
        key = cell_key(value)
        if key in seen:
            continue
        seen.add(key)
        rows.append({column: value})
    return [column], rows


def normalize_calculated_column(name: Any, expression: Any) -> dict[str, str]:
    """Validate one local calculated-column definition."""
    if not isinstance(name, str) or not name.strip():
        raise MeasureError("Enter a calculated column name.")
    clean_name = name.strip()
    if len(clean_name) > 120 or any(char in clean_name for char in "[]\r\n"):
        raise MeasureError(
            "Calculated column names must be 1–120 characters and cannot contain brackets or line breaks."
        )
    if not isinstance(expression, str) or not expression.strip():
        raise MeasureError("Enter a DAX expression for the calculated column.")
    clean_expression = expression.strip(_DAX_WHITESPACE)
    parsed_expression = parse_expression(clean_expression)
    if _contains_function_call(parsed_expression, "COALESCE"):
        raise MeasureError(
            "COALESCE is supported only in measures in this local subset."
        )
    if any(
        _contains_function_call(parsed_expression, function)
        for function in ("COUNTX", "COUNTAX")
    ):
        raise MeasureError(
            "COUNTX and COUNTAX are supported only in measures in this local subset."
        )
    if any(
        _contains_function_call(parsed_expression, function)
        for function in ("USERELATIONSHIP", "CROSSFILTER")
    ):
        raise MeasureError(
            "Relationship filter modifiers are supported only for measures in this local subset."
        )
    if any(
        _contains_function_call(parsed_expression, function)
        for function in ("MAXX", "MINX")
    ):
        raise MeasureError(
            "MAXX and MINX are supported only in measures in this local subset."
        )
    if _contains_table_call(parsed_expression):
        raise MeasureError("Table-valued functions are not supported in calculated columns.")
    return {"name": clean_name, "expression": clean_expression}


def validate_calculated_columns(value: Any) -> list[dict[str, str]]:
    """Return the canonical persisted shape for a table's calculated columns."""
    if not isinstance(value, list) or len(value) > MAX_CALCULATED_COLUMNS:
        raise MeasureError(
            f"A table can contain at most {MAX_CALCULATED_COLUMNS} calculated columns."
        )
    result: list[dict[str, str]] = []
    names: set[str] = set()
    for index, item in enumerate(value, 1):
        if not isinstance(item, dict) or set(item) != {"name", "expression"}:
            raise MeasureError(
                f"Calculated column {index} must contain only name and expression fields."
            )
        column = normalize_calculated_column(item["name"], item["expression"])
        key = column["name"].casefold()
        if key in names:
            raise MeasureError(f"Calculated column {column['name']!r} is duplicated.")
        names.add(key)
        result.append(column)
    return result


def evaluate_calculated_columns(
    definitions: Iterable[dict[str, str]],
    rows: list[dict[str, Any]],
    headers: list[str],
    table_name: str = "",
) -> tuple[list[str], list[dict[str, Any]], dict[str, str]]:
    """Materialize a table's numeric/boolean row expressions in definition order."""
    columns = validate_calculated_columns(list(definitions))
    output_headers = list(headers)
    output_rows = [dict(row) for row in rows]
    output_types: dict[str, str] = {}

    for definition in columns:
        name = definition["name"]
        header_by_key = {header.casefold(): header for header in output_headers}
        if name.casefold() in header_by_key:
            raise MeasureError(f"A column named {name!r} already exists in table {table_name!r}.")
        expression = parse_expression(definition["expression"])
        result_values: list[Decimal | bool | None] = []

    
        def evaluate(
            node: tuple[Any, ...], row: dict[str, Any], row_index: int
        ) -> Decimal | bool | None:
            kind = node[0]
            if kind == "number":
                return node[1]
            if kind == "boolean":
                return node[1]
            if kind == "table":
                raise MeasureError(
                    "Table names are not supported in calculated-column expressions."
                )
            if kind == "reference":
                _, table, column = node
                if table and table.casefold() != table_name.casefold():
                    raise MeasureError(
                        "A calculated column can reference columns from its own table only."
                    )
                actual = header_by_key.get(column.casefold())
                if actual is None:
                    raise MeasureError(
                        f"Column {column!r} does not exist in table {table_name!r}."
                    )
                raw = row.get(actual)
                _reject_power_query_error(raw, actual, row_index)
                value = "" if raw is None else cell_to_text(raw).strip()
                if not value:
                    return None
                if value.casefold() in {"true", "false"}:
                    return value.casefold() == "true"
                try:
                    number = Decimal(value.replace(",", ""))
                except (DecimalException, ValueError) as exc:
                    raise MeasureError(
                        f"Column {actual!r} contains a non-numeric value at row {row_index}."
                    ) from exc
                if not number.is_finite():
                    raise MeasureError(f"Column {actual!r} contains a non-finite number.")
                return number
            if kind == "blank":
                return None
            if kind == "unary":
                operand = evaluate(node[2], row, row_index)
                if operand is None:
                    return None
                value = as_number(operand)
                return value if node[1] == "+" else -value
            if kind == "binary":
                left = evaluate(node[2], row, row_index)
                right = evaluate(node[3], row, row_index)
                if node[1] == "/" and left is not None and (right is None or as_number(right) == 0):
                    raise _DivisionError(f"Calculated column {name!r} divides by zero at row {row_index}.")
                return _unsigned_zero(_binary_value(
                    node[1],
                    None if left is None else as_number(left),
                    None if right is None else as_number(right),
                ))
            if kind == "logical":
                left = as_boolean(_consume_infinity(lambda: evaluate(node[2], row, row_index)))
                if node[1] == "&&":
                    return left and as_boolean(_consume_infinity(lambda: evaluate(node[3], row, row_index)))
                return left or as_boolean(_consume_infinity(lambda: evaluate(node[3], row, row_index)))
            if kind == "comparison":
                left = _consume_infinity(lambda: evaluate(node[2], row, row_index))
                right = _consume_infinity(lambda: evaluate(node[3], row, row_index))
                if isinstance(left, bool) and isinstance(right, bool):
                    if node[1] == "=":
                        return left == right
                    if node[1] == "<>":
                        return left != right
                    raise MeasureError("True/False values support only equality comparisons.")
                left_number, right_number = as_number(left), as_number(right)
                return {
                    "=": left_number == right_number,
                    "<>": left_number != right_number,
                    "<": left_number < right_number,
                    "<=": left_number <= right_number,
                    ">": left_number > right_number,
                    ">=": left_number >= right_number,
                }[node[1]]
            _, function, arguments = node
            if function == "IF":
                if as_boolean(_consume_infinity(lambda: evaluate(arguments[0], row, row_index))):
                    return evaluate(arguments[1], row, row_index)
                return evaluate(arguments[2], row, row_index) if len(arguments) == 3 else None
            if function == "ISBLANK":
                return _isblank_consume(lambda: evaluate(arguments[0], row, row_index), arguments[0])
            if function == "IFERROR":
                try:
                    return evaluate(arguments[0], row, row_index)
                except (MeasureRuntimeError, DecimalException, OverflowError):
                    return evaluate(arguments[1], row, row_index)
            if function == "SWITCH":
                subject = _consume_infinity(lambda: evaluate(arguments[0], row, row_index))
                remaining = list(arguments[1:])
                fallback = remaining.pop() if len(remaining) % 2 else None
                for candidate, result in zip(remaining[::2], remaining[1::2]):
                    if dax_typed.values_match(
                        subject, _consume_infinity(lambda: evaluate(candidate, row, row_index))
                    ):
                        return evaluate(result, row, row_index)
                return None if fallback is None else evaluate(fallback, row, row_index)
            if function in {"AND", "OR"}:
                left = as_boolean(_consume_infinity(lambda: evaluate(arguments[0], row, row_index)))
                if function == "AND":
                    return left and as_boolean(_consume_infinity(lambda: evaluate(arguments[1], row, row_index)))
                return left or as_boolean(_consume_infinity(lambda: evaluate(arguments[1], row, row_index)))
            if function == "NOT":
                return not as_boolean(_consume_infinity(lambda: evaluate(arguments[0], row, row_index)))
            if function == "ABS":
                return abs(as_number(evaluate(arguments[0], row, row_index)))
            if function in _SCALAR_MATH_ARITY:
                return _scalar_math(function, [
                    None if value is None else as_number(value)
                    for value in (evaluate(argument, row, row_index) for argument in arguments)
                ])
            if function == "ROUND":
                value = as_number(evaluate(arguments[0], row, row_index))
                precision = as_number(evaluate(arguments[1], row, row_index))
                if precision != precision.to_integral_value() or abs(precision) > 28:
                    raise MeasureError("ROUND digits must be a whole number from -28 to 28.")
                quantum = Decimal(1).scaleb(-int(precision))
                return value.quantize(quantum, rounding=ROUND_HALF_UP)
            raise MeasureError(
                f"{function} is not supported in calculated-column expressions."
            )

        def as_number(value: Decimal | bool | None) -> Decimal:
            if value is None:
                return Decimal(0)
            if not isinstance(value, Decimal):
                raise MeasureError("This calculated-column expression needs a numeric value.")
            return value

        def as_boolean(value: Decimal | bool | None) -> bool:
            if value is None:
                return False
            if isinstance(value, bool):
                return value
            if isinstance(value, Decimal):
                return value != 0
            raise MeasureError("This calculated-column expression needs a logical value.")

        for row_index, row in enumerate(output_rows, 1):
            try:
                result_values.append(evaluate(expression, row, row_index))
            except (DecimalException, OverflowError) as exc:
                raise MeasureError(
                    f"Calculated column {name!r} is outside the supported numeric range at row {row_index}."
                ) from exc

        value_kinds = {"boolean" if isinstance(value, bool) else "numeric"
                       for value in result_values if value is not None}
        if len(value_kinds) > 1:
            raise MeasureError(
                f"Calculated column {name!r} returns mixed numeric and True/False values."
            )
        column_type = "boolean" if value_kinds == {"boolean"} else "decimal_number"
        for row, value in zip(output_rows, result_values):
            row[name] = value
        output_headers.append(name)
        output_types[name] = column_type

    return output_headers, output_rows, output_types


def normalize_measure(
    name: Any,
    expression: Any,
    *,
    description: Any = "",
    display_folder: Any = "",
    is_hidden: Any = False,
    home_table_id: Any = None,
) -> dict[str, Any]:
    """Validate a persisted measure and its model metadata."""
    if not isinstance(name, str) or not name.strip():
        raise MeasureError("Enter a measure name.")
    clean_name = name.strip()
    if len(clean_name) > 120 or any(char in clean_name for char in "[\r\n"):
        raise MeasureError("Measure names must be 1–120 characters and cannot contain brackets or line breaks.")
    if not isinstance(expression, str):
        raise MeasureError("A measure expression must be text.")
    clean_expression = expression.strip(_DAX_WHITESPACE)
    # Accept a complete DAX assignment in the expression box as a convenience.
    assignment = _FORMULA_ASSIGNMENT.match(clean_expression)
    if assignment is not None:
        assignment_name = (
            (assignment.group("bracketed") or "").replace("]]", "]") or assignment.group("plain") or ""
        ).strip()
        assigned_expression = clean_expression[assignment.end():].strip()
        if not assignment_name or not assigned_expression:
            raise MeasureError("Use the form Measure Name = expression.")
        if name.strip() and name.strip() != "Measure":
            clean_name = name.strip()
            if clean_name.casefold() != assignment_name.casefold():
                raise MeasureError("The formula name must match the Measure name field.")
        else:
            clean_name = assignment_name
        clean_expression = assigned_expression.strip()
    parsed_expression = parse_expression(clean_expression)
    if (
        _contains_table_call(parsed_expression)
        and not _is_supported_time_filter_calculate(parsed_expression)
        and not _is_supported_table_filter_calculate(parsed_expression)
        and not _has_supported_all_usage(parsed_expression)
    ):
        raise MeasureError("Table-valued functions are not supported in measure expressions.")
    if (
        not isinstance(description, str)
        or len(description) > 4_000
        or "\x00" in description
    ):
        raise MeasureError("A measure description must be at most 4,000 characters and contain no null characters.")
    if (
        not isinstance(display_folder, str)
        or len(display_folder) > 400
        or any(ord(char) < 32 for char in display_folder)
    ):
        raise MeasureError("A measure display folder must be at most 400 characters and contain no control characters.")
    if type(is_hidden) is not bool:
        raise MeasureError("A measure is_hidden value must be true or false.")
    result: dict[str, Any] = {"name": clean_name, "expression": clean_expression}
    if home_table_id is not None:
        if not isinstance(home_table_id, str) or not home_table_id.strip():
            raise MeasureError("A measure home table ID must be non-empty text.")
        result["home_table_id"] = home_table_id.strip()
    if description.strip():
        result["description"] = description.strip()
    if display_folder.strip():
        result["display_folder"] = display_folder.strip().strip("/\\")
        if not result["display_folder"]:
            result.pop("display_folder")
    if is_hidden:
        result["is_hidden"] = True
    return result


def validate_measures(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list) or len(value) > MAX_MEASURES:
        raise MeasureError(f"A model can contain at most {MAX_MEASURES} measures.")
    result = []
    names: set[str] = set()
    supported_fields = {
        "name", "expression", "description", "display_folder", "is_hidden",
        "home_table_id",
    }
    for index, item in enumerate(value, 1):
        if (
            not isinstance(item, dict)
            or not {"name", "expression"}.issubset(item)
            or set(item) - supported_fields
        ):
            raise MeasureError(
                f"Measure {index} needs name and expression and supports only recognized metadata fields."
            )
        measure = normalize_measure(
            item["name"],
            item["expression"],
            description=item.get("description", ""),
            display_folder=item.get("display_folder", ""),
            is_hidden=item.get("is_hidden", False),
            home_table_id=item.get("home_table_id"),
        )
        key = measure["name"].casefold()
        if key in names:
            raise MeasureError(f"Measure {measure['name']!r} is duplicated.")
        names.add(key)
        result.append(measure)
    return result


def _cell_date_value(value: Any, column: str, row_index: int | None) -> Any:
    """A Date/DateTime model cell as a DAX DateTime (None when blank)."""
    if value is None or (isinstance(value, str) and not value.strip()):
        return None
    if isinstance(value, (date, datetime)):
        return dax_dates.from_datetime(value)
    try:
        return dax_dates.from_datetime(datetime.fromisoformat(str(value).strip().replace("Z", "+00:00")))
    except ValueError:
        return dax_dates.parse_date_text(str(value))


def _parse_measure_date(value: Any, column: str, row_index: int) -> date | None:
    """Read an ISO Date/DateTime model value for a time-intelligence measure."""
    text = "" if value is None else str(value).strip()
    if not text:
        return None
    try:
        parsed_date = date.fromisoformat(text)
        if parsed_date.isoformat() == text:
            return parsed_date
    except ValueError:
        pass
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError as exc:
        raise MeasureError(
            f"Marked date column {column!r} contains an invalid date at row {row_index}."
        ) from exc


def _shift_date(value: date, intervals: int, unit: str, keep_month_end: bool = False) -> date:
    """value moved by whole months / quarters / years (days for DAY); the day is clamped to the target month, and with
    keep_month_end the last day of a month stays the last day of the target month (live DATESINPERIOD)."""
    if unit == "DAY":
        try:
            return value + timedelta(days=intervals)
        except OverflowError as exc:
            raise MeasureError("DATEADD shifted dates outside the supported date range.") from exc
    target_index = value.year * 12 + value.month - 1 + intervals * {"MONTH": 1, "QUARTER": 3, "YEAR": 12}[unit]
    target_year, zero_based_month = divmod(target_index, 12)
    target_month = zero_based_month + 1
    if not 1 <= target_year <= 9999:
        raise MeasureError("DATEADD shifted dates outside the supported date range.")
    last = monthrange(target_year, target_month)[1]
    if keep_month_end and value.day == monthrange(value.year, value.month)[1]:
        return date(target_year, target_month, last)
    return date(target_year, target_month, min(value.day, last))


def _sparse_period_window(days: set[date], start: date, count: int, unit: str) -> set[date] | None:
    """DATESINPERIOD month / quarter / year window over a sparse date column (one that is not a full calendar), measured on live Power
    BI in iteration 84 (13,608 probes on two fact date columns).

    A negative count: when the month of the start date holds no later date of the column the start date stands for the end of its
    month, so the window is whole months (from the 1st of the month |n|-1 months back); otherwise it is the exact DAX window.
    0 of 2,268 probes differ.  A positive count has no rule that fits every probe: four readings of the window (exact days, whole
    months, the exact end taken to the end of its month, with and without that last day) are computed and the answer is given only
    where they agree (2,058 of 2,268 probes, 0 wrong); None means "refuse"."""
    boundary = _shift_date(start, count, unit, keep_month_end=True)
    months = abs(count) * {"MONTH": 1, "QUARTER": 3, "YEAR": 12}[unit]

    def month_end(day: date) -> date:
        return date(day.year, day.month, monthrange(day.year, day.month)[1])

    if count < 0:
        exact = {value for value in days if boundary < value <= start}
        if any(start < value <= month_end(start) for value in days):
            return exact
        year, zero_month = divmod(start.year * 12 + start.month - 1 - (months - 1), 12)
        first = date(year, zero_month + 1, 1) if year >= 1 else date.min
        return {value for value in days if first <= value <= start}
    year, zero_month = divmod(start.year * 12 + start.month - 1 + months, 12)
    readings = [
        {value for value in days if start <= value < boundary},
        {value for value in days if start <= value <= (month_end(date(year, zero_month + 1, 1)) if year <= 9999 else date.max)},
        {value for value in days if start <= value < month_end(boundary)},
        {value for value in days if start <= value <= month_end(boundary - timedelta(days=1))},
    ]
    return readings[0] if all(reading == readings[0] for reading in readings) else None


def _scalar_day(value: Any, function: str) -> date | None:
    """A date-set bound as a calendar day: BLANK is None, a date or number is truncated to its day, text is an ISO / date text."""
    if value is None:
        return None
    if isinstance(value, bool):
        raise MeasureError(f"{function} needs a date value.")
    if isinstance(value, str):
        text = value.strip()
        try:
            return date.fromisoformat(text)
        except ValueError:
            try:
                value = dax_dates.parse_date_text(text)
            except Exception as exc:
                raise MeasureError(f"{function} needs a date value.") from exc
    if not isinstance(value, Decimal) or not value.is_finite():
        raise MeasureError(f"{function} needs a date value.")
    try:
        return dax_dates.to_datetime(value.to_integral_value(rounding=ROUND_FLOOR), ROUND_FLOOR).date()
    except (OverflowError, ValueError, MeasureError) as exc:
        raise MeasureError(f"{function} needs a date inside the supported range.") from exc


def _scalar_count(value: Any) -> int:
    """number_of_intervals: BLANK and 0 are no period, text numbers are coerced, halves round away from zero."""
    if value is None:
        return 0
    if isinstance(value, str):
        try:
            value = Decimal(value.strip())
        except DecimalException as exc:
            raise MeasureError("number_of_intervals must be a number.") from exc
    if isinstance(value, bool) or not isinstance(value, Decimal) or not value.is_finite():
        raise MeasureError("number_of_intervals must be a number.")
    rounded = int(value.to_integral_value(rounding=ROUND_HALF_UP))  # ROUND_HALF_UP rounds halves away from zero
    if abs(rounded) > 3_652_059:
        raise MeasureError("number_of_intervals is outside the supported range.")
    return rounded


def _gap_free(dates: Iterable[date]) -> bool:
    values = sorted(set(dates))
    return bool(values) and (values[-1] - values[0]).days + 1 == len(values)


def _dateadd_dates(
    selected_dates: Iterable[date], intervals: int, interval: str, available_dates: Iterable[date] | None = None
) -> set[date]:
    """Shift a date-column selection by DATEADD intervals (live Power BI 2.157, 728 of 728 probes).

    A contiguous selection becomes the whole range from the shifted first day to the shifted last day, the last day moved to the
    end of its month when the selection has several days and ends on its month end (QUARTER and YEAR too). A selection that is not
    contiguous is shifted day by day when the date column is unique and gap free (available_dates), otherwise refused."""
    source_dates = sorted(set(selected_dates))
    unit = interval.upper()
    if unit not in {"YEAR", "QUARTER", "MONTH", "DAY"}:
        raise MeasureError("DATEADD date-column intervals support YEAR, QUARTER, MONTH, or DAY.")
    if not source_dates:
        return set()
    contiguous = len(source_dates) == 1 or _gap_free(source_dates)
    try:
        if not contiguous:
            if available_dates is None or not _gap_free(available_dates):
                raise MeasureError("DATEADD requires the current date-column selection to be contiguous.")
            runs: list[list[date]] = [[source_dates[0]]]
            for value in source_dates[1:]:
                if (value - runs[-1][-1]).days == 1:
                    runs[-1].append(value)
                else:
                    runs.append([value])
            result: set[date] = set()
            for run in runs:
                result |= _dateadd_dates(run, intervals, interval)
            return result
        if unit == "DAY":
            return {_shift_date(value, intervals, unit) for value in source_dates}
        first = _shift_date(source_dates[0], intervals, unit)
        last = _shift_date(source_dates[-1], intervals, unit)
        if len(source_dates) > 1 and source_dates[-1].day == monthrange(source_dates[-1].year, source_dates[-1].month)[1]:
            last = date(last.year, last.month, monthrange(last.year, last.month)[1])
        return {first + timedelta(days=offset) for offset in range((last - first).days + 1)}
    except MeasureError:
        raise
    except (OverflowError, ValueError) as exc:
        raise MeasureError("DATEADD shifted dates outside the supported date range.") from exc


def _sameperiodlastyear_dates(selected_dates: Iterable[date], available_dates: Iterable[date] | None = None) -> set[date]:
    """SAMEPERIODLASTYEAR is DATEADD(-1, YEAR) (live Power BI: 43 of 43 contexts, the leap day included)."""
    try:
        return _dateadd_dates(selected_dates, -1, "YEAR", available_dates)
    except MeasureError as error:
        raise MeasureError(str(error).replace("DATEADD", "SAMEPERIODLASTYEAR")) from error


# Functions and operators whose arguments are evaluated in the caller's context: a bare column below them still has no row context.
_ROW_CONTEXT_FREE_CALLS = {
    "CURRENCY", "CONVERT", "SQRT", "LN", "LOG10", "LOG", "VALUE", "MOD",
    "IF", "IF.EAGER", "FORMAT", "SWITCH", "COALESCE", "IFERROR", "AND", "OR", "NOT", "ISBLANK", "ABS", "EXACT",
    "UPPER", "LOWER", "LEN", "TRIM", "ROUND", "INT",
    "ISINTEGER", "ISINT64", "ISDOUBLE", "ISDECIMAL", "ISCURRENCY",
}
_ROW_CONTEXT_FREE_NODES = {"binary", "comparison", "logical", "unary", "concat", "in", "let", "tableconstructor", "strict_equal"}


def _spells_a_number(text: str) -> bool:
    try:
        Decimal(text.strip())
    except DecimalException:
        return False
    return True


def _bare_column_outside_row_context(node: Any, columns: dict[str, set[str]]) -> tuple[str, str] | None:
    """The first column reference that a measure evaluated without a row context reads directly.

    Power BI refuses such a reference when the query is compiled ("A single value for column ... cannot be
    determined"), also in an IF/SWITCH branch that would never run.  Only constructs that keep the caller's
    context are followed; aggregations, iterators, CALCULATE and table functions give their arguments their own
    context and end the search.
    """
    if not isinstance(node, tuple) or not node:
        return None
    kind = node[0]
    if kind == "reference":
        table, column = node[1], node[2]
        if table and column.casefold() in columns.get(table.casefold(), ()):
            return table, column
        return None
    if kind == "call":
        if node[1] == "CALCULATE" and node[2]:
            children = node[2][:1]  # the expression keeps the caller's row context (none); the filters are evaluated elsewhere
        elif node[1] not in _ROW_CONTEXT_FREE_CALLS:
            return None
        else:
            children = node[2]
    elif kind == "let":
        children = [value for _name, value in node[1]] + [node[2]]
    elif kind == "in":
        children = [node[1]]
    elif kind in _ROW_CONTEXT_FREE_NODES:
        children = [part for part in node[1:] if isinstance(part, tuple)]
    else:
        return None
    for child in children:
        found = _bare_column_outside_row_context(child, columns)
        if found:
            return found
    return None


def _measure_references(node: Any, found: set[str]) -> None:
    if isinstance(node, tuple):
        if len(node) == 3 and node[0] == "reference" and node[1] == "":
            found.add(str(node[2]).casefold())
        for part in node:
            _measure_references(part, found)
    elif isinstance(node, (list, frozenset)):
        for part in node:
            _measure_references(part, found)


def _reject_bare_columns_without_row_context(
    selected: list[tuple[dict[str, str], tuple[Any, ...]]],
    every_expression: list[tuple[Any, ...]],
    columns: dict[str, set[str]],
) -> None:
    referenced: set[str] = set()
    for expression in every_expression:
        _measure_references(expression, referenced)
    for item, expression in selected:
        if item["name"].casefold() in referenced:
            continue  # used inside another measure, which may supply a row context
        found = _bare_column_outside_row_context(expression, columns)
        if found:
            raise MeasureError(
                f"A single value for column '{found[1]}' in table '{found[0]}' cannot be determined. "
                "Refer to the column inside an aggregation such as MIN, MAX, COUNT or SUM, or iterate its table."
            )



_NUMBER_COLUMN_TYPES = {"whole_number", "decimal_number", "decimal", "fixed_decimal", "currency", "number", "int64", "double"}
_TEXT_FUNCTIONS = {"UPPER", "LOWER", "TRIM", "LEFT", "RIGHT", "MID", "CONCATENATE", "FORMAT", "SUBSTITUTE", "REPT", "FIXED", "NAMEOF", "CUSTOMDATA", "TOCSV", "TOJSON"}
_BOOLEAN_FUNCTIONS = {
    "AND", "OR", "NOT", "ISBLANK", "EXACT", "ISNUMBER", "ISTEXT", "ISERROR", "CONTAINSROW", "CONTAINS",
    "ISINTEGER", "ISINT64", "ISDOUBLE", "ISDECIMAL", "ISCURRENCY",
}


_STATIC_ALWAYS_DOUBLE = frozenset({
    "POWER", "SQRT", "EXP", "LN", "LOG", "LOG10", "PI",
    "COMBIN", "FACT", "AVERAGE", "VALUE",
    "SIN", "COS", "TAN", "ASIN", "DEGREES", "RADIANS", "MEDIAN", "MEDIANX", "PERCENTILE.INC", "PERCENTILEX.INC",
    "STDEV.S", "STDEV.P", "VAR.S", "VAR.P", "VARX.S", "VARX.P", "GEOMEAN", "PRODUCT", "PRODUCTX", "XNPV", "XIRR", "RAND",
})

_STATIC_ALWAYS_INT64 = frozenset({
    "COUNT", "COUNTA", "COUNTROWS", "COUNTBLANK", "DISTINCTCOUNT", "DISTINCTCOUNTNOBLANK",
    "LEN", "YEAR", "MONTH", "DAY", "HOUR", "MINUTE", "SECOND", "QUARTER", "WEEKDAY", "WEEKNUM",
    "DATEDIFF", "FIND", "SEARCH", "UNICODE", "GCD", "LCM", "QUOTIENT",
    "RANDBETWEEN", "RANKX", "RANK", "ROWNUMBER", "SIGN", "COUNTX", "COUNTAX"
})


def _unify_numeric_types(types: list[str | None]) -> str | None:
    """Result type of branches / arguments that Power BI unifies (blank branches are ignored); None when unsure."""
    kinds = {t for t in types if t != "blank"}
    if not kinds:
        return "int64"
    if None in kinds or not kinds <= {"int64", "double", "currency", "datetime"}:
        return None
    if kinds == {"int64"}:
        return "int64"
    if kinds == {"datetime"}:
        if "blank" in types:
            return "double"
        return "datetime"
    if "double" in kinds or "datetime" in kinds:
        return "double"
    return "currency"

_STATIC_TEXT_FUNCTIONS = frozenset({
    "CONCATENATE", "UPPER", "LOWER", "TRIM", "LEFT", "RIGHT", "MID", "SUBSTITUTE", "REPLACE", "REPT",
    "UNICHAR", "FORMAT", "NAMEOF", "CUSTOMDATA", "FIXED", "TOCSV", "TOJSON"
})

_STATIC_BOOL_FUNCTIONS = frozenset({
    "AND", "OR", "NOT", "ISBLANK", "EXACT", "ISNUMBER", "ISTEXT", "ISNONTEXT", "ISLOGICAL", "ISERROR",
    "CONTAINS", "CONTAINSROW", "ISEMPTY", "ISFILTERED", "ISCROSSFILTERED", "HASONEFILTER", "ISINSCOPE",
    "HASONEVALUE", "ISINTEGER", "ISINT64", "ISDOUBLE", "ISDECIMAL", "ISCURRENCY", "TRUE", "FALSE"
})

_STATIC_DATE_FUNCTIONS = frozenset({
    "DATE", "TIME", "EOMONTH", "EDATE", "DATEVALUE", "TIMEVALUE", "TODAY", "NOW", "UTCNOW", "UTCTODAY"
})


def _normalize_model_column_types(model: Any) -> dict[str, dict[str, str]]:
    if not model:
        return {}
    if isinstance(model, dict):
        if "column_types" in model and isinstance(model["column_types"], dict):
            name = str(model.get("name", "facts")).casefold()
            types = {str(k).casefold(): str(v).casefold() for k, v in model["column_types"].items()}
            return {name: types}
        res: dict[str, dict[str, str]] = {}
        for k, v in model.items():
            if isinstance(v, dict):
                res[str(k).casefold()] = {str(ck).casefold(): str(cv).casefold() for ck, cv in v.items()}
            elif isinstance(v, str):
                res.setdefault("facts", {})[str(k).casefold()] = v.casefold()
        return res
    if isinstance(model, (list, tuple)):
        res = {}
        for item in model:
            if isinstance(item, dict) and "column_types" in item and isinstance(item["column_types"], dict):
                name = str(item.get("name", "")).casefold()
                res[name] = {str(k).casefold(): str(v).casefold() for k, v in item["column_types"].items()}
        return res
    if hasattr(model, "tables"):
        res = {}
        for t in getattr(model, "tables", []):
            name = str(getattr(t, "name", "")).casefold()
            col_types = getattr(t, "column_types", {})
            if isinstance(col_types, dict):
                res[name] = {str(k).casefold(): str(v).casefold() for k, v in col_types.items()}
        return res
    return {}


_TABLE_VARIABLE = "\0"  # the columns of a table variable sit beside the tables, under this prefix and the variable's name


def _join_column_types(types: list[str | None]) -> str:
    """The type of a column made of these (live Power BI, Task 16 review): a date beside a number is a Double, a BLANK takes the other side; "" when not known."""
    kinds = {t for t in types if t != "blank"}
    if not kinds:
        return "blank"
    if kinds <= {"text"} or kinds <= {"bool"} or kinds <= {"datetime"}:
        return kinds.pop()
    if "datetime" in kinds and kinds <= {"datetime", "int64", "double", "currency"}:
        return "double"
    return _unify_numeric_types(list(kinds)) or ""


def _static_table_columns(node: Any, columns: dict[str, dict[str, str]], variables: dict[str, str | None]) -> dict[str, str]:
    """The columns of a table expression and their types, header.casefold() -> type ("" when it is not known); {} for a table of unknown shape."""
    if not isinstance(node, tuple) or not node:
        return {}
    kind = node[0]
    if kind == "table":
        return dict(columns.get(str(node[1]).casefold(), {}))
    if kind == "table_call":
        return _static_table_columns(node[2], columns, variables)
    if kind == "reference":
        return dict(columns.get((node[1] or "").casefold(), {}))
    if kind == "var":
        return dict(columns.get(_TABLE_VARIABLE + str(node[1]).casefold(), {}))
    if kind == "let":
        scope_columns, scope = _static_let_scope(node, columns, variables)
        return _static_table_columns(node[2], scope_columns, scope)
    if kind == "tableconstructor":
        items = node[1]
        if not items:
            return {"value": ""}
        width = len(items[0][1]) if items and items[0][0] in {"tuple", "tableconstructor"} else 1
        names = ["value"] if width == 1 and (not items or items[0][0] != "tuple") else [f"value{col + 1}" for col in range(width)]
        tc_types = {}
        for col_idx, col_name in enumerate(names):
            col_nodes = [(item[1] if item[0] in {"tuple", "tableconstructor"} else (item,))[col_idx] for item in items]
            logical = [_is_true_false_column_node(n, variables) or _static_type(n, columns, variables) == "boolean" for n in col_nodes]
            if all(logical):
                tc_types[col_name] = "bool"
            elif any(_static_type(n, columns, variables) == "text" for n in col_nodes):
                tc_types[col_name] = "text"
            elif any(logical) and all(is_logical or _static_numeric_type(n, columns, variables) == "datetime" for n, is_logical in zip(col_nodes, logical)):
                tc_types[col_name] = "datetime"  # live Power BI (Task 17 review): a True/False beside a date does not make a number, unlike a number beside a date
            else:
                tc_types[col_name] = _join_column_types(["int64" if is_logical else _static_numeric_type(n, columns, variables) for n, is_logical in zip(col_nodes, logical)])
        return tc_types
    if kind != "call":
        return {}
    fn, args = node[1], node[2]
    if fn == "COLUMNSTATISTICS":
        return {
            "table name": "text",
            "column name": "text",
            "min": "variant",
            "max": "variant",
            "cardinality": "int64",
            "max length": "int64",
        }
    if fn in {"LINEST", "LINESTX"}:
        from . import dax_linest
        return {h.casefold(): "double" for h in dax_linest.headers_for(16, True)}
    if fn in _INFO_FUNCTIONS:
        if fn in _INFO_EMPTY_SCHEMAS:
            hdrs, typs = _INFO_EMPTY_SCHEMAS[fn]
            return {h.casefold(): typs.get(h, "") for h in hdrs}
        types_map = {
            "INFO.VIEW.TABLES": (_INFO_VIEW_TABLES_HEADERS, _INFO_VIEW_TABLES_TYPES),
            "INFO.VIEW.COLUMNS": (_INFO_VIEW_COLUMNS_HEADERS, _INFO_VIEW_COLUMNS_TYPES),
            "INFO.VIEW.MEASURES": (_INFO_VIEW_MEASURES_HEADERS, _INFO_VIEW_MEASURES_TYPES),
            "INFO.VIEW.RELATIONSHIPS": (_INFO_VIEW_RELATIONSHIPS_HEADERS, _INFO_VIEW_RELATIONSHIPS_TYPES),
            "INFO.TABLES": (_INFO_TABLES_HEADERS, _INFO_TABLES_TYPES),
            "INFO.COLUMNS": (_INFO_COLUMNS_HEADERS, _INFO_COLUMNS_TYPES),
            "INFO.MEASURES": (_INFO_MEASURES_HEADERS, _INFO_MEASURES_TYPES),
            "INFO.RELATIONSHIPS": (_INFO_RELATIONSHIPS_HEADERS, _INFO_RELATIONSHIPS_TYPES),
        }
        hdrs, typs = types_map.get(fn, ([], {}))
        return {h.casefold(): typs.get(h, "") for h in hdrs}
    if fn in {"ADDCOLUMNS", "SELECTCOLUMNS"} and args:
        base = _static_table_columns(args[0], columns, variables)
        added = dict(base) if fn == "ADDCOLUMNS" else {}
        scope_columns = {**columns, "": base}
        for name, expression in zip(args[1::2], args[2::2]):
            if name[0] == "string":
                added[str(name[1]).casefold()] = _static_numeric_type(expression, scope_columns, variables) or ""
        return added
    if fn == "CROSSJOIN":
        cols = {}
        for arg in args:
            cols.update(_static_table_columns(arg, columns, variables))
        return cols
    if fn == "UNION" and args:
        tables = [_static_table_columns(arg, columns, variables) for arg in args]
        if not all(tables) or len({len(table) for table in tables}) != 1:
            return {name: "" for name in tables[0]}  # columns are matched by position
        return {name: _join_column_types(list(types)) for name, *types in zip(tables[0], *[table.values() for table in tables])}
    if fn in {"SUMMARIZE", "GROUPBY"} and args:
        base = _static_table_columns(args[0], columns, variables)
        result = {}
        i = 1
        while i < len(args):
            arg = args[i]
            if arg[0] == "string" and i + 1 < len(args):
                name = str(arg[1]).casefold()
                expr = args[i + 1]
                result[name] = _static_numeric_type(expr, {**columns, "": base}, variables) or ""
                i += 2
            elif arg[0] == "reference":
                col_name = str(arg[2]).casefold()
                col_t = base.get(col_name) or (columns.get(str(arg[1]).casefold(), {}).get(col_name) if arg[1] else "")
                result[col_name] = col_t or ""
                i += 1
            else:
                i += 1
        return result
    if fn in {"FILTER", "CALCULATETABLE", "KEEPFILTERS", "ALL", "ALLSELECTED"} and args:
        return _static_table_columns(args[0], columns, variables)
    if fn == "TOPN" and len(args) >= 2:
        return _static_table_columns(args[1], columns, variables)
    return {}


def _static_let_scope(
    node: tuple[Any, ...],
    columns: dict[str, dict[str, str]],
    variables: dict[str, str | None],
) -> tuple[dict[str, dict[str, str]], dict[str, str | None]]:
    """The columns and the variables a VAR block adds to the type walk."""
    scope_columns, scope = dict(columns), dict(variables)
    for name, value in node[1]:
        scope[str(name)] = _static_numeric_type(value, scope_columns, scope)
        scope_columns[_TABLE_VARIABLE + str(name).casefold()] = _static_table_columns(value, scope_columns, scope)
    return scope_columns, scope


def _is_never_blank_logical(node: Any) -> bool:
    """TRUE(), FALSE(), a Boolean constant or a comparison: a True/False that can never be BLANK."""
    return isinstance(node, tuple) and bool(node) and (node[0] in {"boolean", "comparison"} or (node[0] == "call" and node[1] in {"TRUE", "FALSE"} and not node[2]))


def _static_numeric_type(
    node: Any,
    model: Any = None,
    variables: dict[str, str | None] | None = None,
) -> str | None:
    """Infer static DAX numeric/data type: "int64" | "double" | "currency" | "decimal" | "bool" | "text" | "datetime" | "blank" | None."""
    if not isinstance(node, tuple) or not node:
        return None
    columns = _normalize_model_column_types(model) if not isinstance(model, dict) or any(isinstance(v, str) for v in model.values()) or "column_types" in model else model
    variables = {} if variables is None else variables
    kind = node[0]
    if kind == "number":
        if len(node) > 2 and isinstance(node[2], str):
            lit = node[2]
            if "." in lit or "e" in lit.lower():
                return "double"
            try:
                if int(lit) > 9223372036854775807:
                    return "double"
                return "int64"
            except ValueError:
                return "double"
        val = node[1]
        if val != val.to_integral_value() or val.as_tuple().exponent < 0 or val > Decimal(9223372036854775807):
            return "double"
        return "int64"
    if kind == "string":
        return "text"
    if kind == "boolean":
        return "bool"
    if kind in {"blank", "blank_comment"}:
        return "blank"
    if kind in {"comparison", "logical", "in", "strict_equal"}:
        return "bool"
    if kind == "concat":
        return "text"
    if kind == "var":
        return variables.get(str(node[1]))
    if kind == "let":
        scope_columns, scope = _static_let_scope(node, columns, variables)
        return _static_numeric_type(node[2], scope_columns, scope)
    if kind == "reference":
        table = (node[1] or "").casefold()
        col = str(node[2]).casefold()
        raw_type = None
        if table:
            raw_type = columns.get(table, {}).get(col)
        else:
            if "" in columns:
                raw_type = columns[""].get(col)  # the column of the iterated table, whatever a stored column of the same name holds
            else:
                for tbl_types in columns.values():
                    if col in tbl_types:
                        raw_type = tbl_types[col]
                        break
        if not raw_type:
            return None
        raw = raw_type.casefold()
        if raw in {"whole_number", "integer", "int64", "int"}:
            return "int64"
        if raw in {"decimal_number", "double", "float", "number"}:
            return "double"
        if raw in {"currency", "fixed_decimal", "decimal"}:
            return "currency"
        if raw in {"text", "string"}:
            return "text"
        if raw in {"boolean", "true_false", "bool"}:
            return "bool"
        if raw in {"date", "datetime", "time"}:
            return "datetime"
        if raw == "blank":
            return "blank"
        return None
    if kind == "unary":
        op, child = node[1], node[2]
        t = _static_numeric_type(child, columns, variables)
        if op == "+":
            if t in {"int64", "double", "currency", "datetime", "blank"}:
                return t
            if t == "bool":
                return "bool"
            if t == "text":
                return "double"
        if op == "-":
            if t in {"int64", "double", "currency", "blank"}:
                return t
            if t == "datetime":
                return "double"
            if t == "bool":
                return "int64"
            if t == "text":
                return "double"
        if op == "not":
            return "bool"
        return None
    if kind == "binary":
        op, left, right = node[1], node[2], node[3]
        if op == "^":
            return "double"
        lt = _static_numeric_type(left, columns, variables)
        rt = _static_numeric_type(right, columns, variables)
        lt = "int64" if lt == "bool" else lt
        rt = "int64" if rt == "bool" else rt
        if lt == "blank" and rt == "blank":
            return "blank"
        if op in {"+", "-"} and (lt == "datetime" or rt == "datetime"):
            if op == "-":
                if lt == "datetime":
                    return "datetime"
                return "double"
            if op == "+":
                return "datetime"
            return None
        if op in {"+", "-"} and "text" in (lt, rt) and "currency" in (lt, rt):
            return "double"  # Task 21 Part B: a text number + or - a Currency is a Double
        if op == "*" and "text" in (lt, rt) and "currency" in (lt, rt):
            return "currency"  # Task 21 Part B: a text number times a Currency is a Currency
        if op == "/" and lt == "currency" and rt in {"text", "datetime"}:
            return "currency"  # Task 21 Part B: a Currency over a text number or a date is a Currency
        if op == "/" and rt == "currency" and lt in {"text", "datetime"}:
            return "double"  # Task 21 Part B: a text number or a date over a Currency is a Double
        if op in {"+", "-", "*", "/"} and "text" in (lt, rt) and "currency" not in (lt, rt):
            return "double"  # Part E: arithmetic on text is a Double ("1E15"+0 is 1E+15 in text); a Currency beside text is left as it was
        if lt == "blank" and rt is not None:
            lt = rt if op in {"+", "-"} else "int64"
        elif rt == "blank" and lt is not None:
            rt = lt if op in {"+", "-"} else "int64"
        # live Power BI: True/False in arithmetic is an Integer, so TRUE()*1 and TRUE()+1 are Int64
        lt = "int64" if lt == "bool" else lt
        rt = "int64" if rt == "bool" else rt
        if op in {"+", "-"}:
            if lt == "int64" and rt == "int64":
                return "int64"
            if "double" in (lt, rt) and lt in {"int64", "double", "currency"} and rt in {"int64", "double", "currency"}:
                return "double"
            if lt == "currency" and rt in {"currency", "int64"}:
                return "currency"
            if rt == "currency" and lt in {"currency", "int64"}:
                return "currency"
            return None
        if op in {"*", "/"}:
            if lt == "datetime" and rt == "datetime":
                return "double"
            if "datetime" in (lt, rt):
                if op == "*" and "currency" in (lt, rt):
                    return "currency"
                return "double"
        if op == "*":
            if lt == "int64" and rt == "int64":
                return "int64"
            if lt == "currency" and rt == "currency":
                return "double"
            if "currency" in (lt, rt) and lt in {"int64", "double", "currency"} and rt in {"int64", "double", "currency"}:
                return "currency"
            if "double" in (lt, rt) and lt in {"int64", "double"} and rt in {"int64", "double"}:
                return "double"
            return None
        if op == "/":
            if lt == "currency" and rt in {"int64", "double"}:
                return "currency"
            if lt in {"int64", "double", "currency"} and rt in {"int64", "double", "currency"}:
                return "double"
            return None
        if op == "^":
            return "double"
        return None
    if kind != "call":
        return None
    fn, args = node[1], node[2]
    if fn == "SELECTEDVALUE" and args and args[0][0] == "reference":
        return _static_numeric_type(args[0], columns, variables)  # live Power BI (Part A): SELECTEDVALUE of a column has the column's type, so a date stays a date and a number stays a number
    if fn == "XNPV" and len(args) == 4 and _static_numeric_type(args[1], columns, variables) == "currency":
        return "currency"
    if fn in _STATIC_ALWAYS_DOUBLE:
        return "double"
    if fn in _STATIC_ALWAYS_INT64:
        return "int64"
    if fn in _STATIC_TEXT_FUNCTIONS:
        return "text"
    if fn in _STATIC_BOOL_FUNCTIONS:
        return "bool"
    if fn in _STATIC_DATE_FUNCTIONS:
        return "datetime"
    if fn == "CONVERT" and _is_datetime_conversion(node):
        return "datetime"  # Part E: CONVERT(x,DATETIME) is a date, so CONVERT(BLANK(),DATETIME)+1 is a date
    if fn == "BLANK":
        return "blank"
    if fn == "CURRENCY":
        return "currency"
    if fn == "ERROR":
        return "int64"
    if fn == "CONVERT" and len(args) == 2:
        kw = str(args[1][1]).upper() if args[1][0] == "table" else ""
        if kw in {"INTEGER", "INT64"}:
            return "int64"
        if kw in {"DOUBLE"}:
            return "double"
        if kw in {"CURRENCY", "DECIMAL"}:
            return "currency"
        if kw in {"BOOLEAN"}:
            return "bool"
        if kw in {"STRING"}:
            return "text"
        if kw in {"DATETIME"}:
            return "datetime"
        return None
    if fn in {"ROUND", "ROUNDUP", "ROUNDDOWN", "TRUNC"}:
        at = _static_numeric_type(args[0], columns, variables) if args else None
        if at in {"int64", "double", "currency"}:
            return at
        return "int64" if at == "bool" else "double"
    if fn == "INT":
        at = _static_numeric_type(args[0], columns, variables) if args else None
        if at == "currency":
            return "currency"
        return "int64" if at in {"int64", "double", "text", "bool"} else None
    if fn in {"EVEN", "ODD"}:
        at = _static_numeric_type(args[0], columns, variables) if args else None
        return at if at in {"int64", "double", "currency"} else None
    if fn == "ABS":
        at = _static_numeric_type(args[0], columns, variables) if args else None
        if at in {"int64", "double", "currency"}:
            return at
        return {"bool": "int64", "text": "double"}.get(at or "")
    if fn in {"FLOOR", "CEILING", "MROUND", "MOD"}:
        if len(args) != 2:
            return None
        lt = _static_numeric_type(args[0], columns, variables)
        rt = _static_numeric_type(args[1], columns, variables)
        if lt not in {"int64", "double", "currency"} or rt not in {"int64", "double", "currency"}:
            return None
        if "currency" in (lt, rt):
            return "currency" if {lt, rt} <= {"currency", "int64"} else None
        if fn == "MOD":
            return "int64" if (lt, rt) == ("int64", "int64") else "double"
        return rt
    if fn == "DIVIDE":
        if len(args) < 2:
            return None
        quotient = _static_numeric_type(("binary", "/", args[0], args[1]), columns, variables)
        if len(args) == 2:
            return quotient
        alt = _static_numeric_type(args[2], columns, variables)
        if quotient is None or alt not in {"int64", "double", "currency", "blank", "bool", "datetime"}:
            return None
        return "currency" if quotient == "currency" else "double"
    if fn in {"MAX", "MIN"} and len(args) == 2:
        return _unify_numeric_types([_static_numeric_type(a, columns, variables) for a in args])
    if fn in {"SUM", "MIN", "MAX"}:
        if args:
            return _static_numeric_type(args[0], columns, variables)
        return None
    if fn == "AVERAGEX":
        if len(args) >= 2:
            table_cols = _static_table_columns(args[0], columns, variables)
            scope = {**columns, "": table_cols} if table_cols else columns
            arg_t = _static_numeric_type(args[1], scope, variables)
            if arg_t == "currency":
                return "currency"
        return "double"
    if fn in {"GEOMEANX", "STDEVX.P", "STDEVX.S"} and len(args) >= 2:
        return "currency" if _static_numeric_type(args[1], columns, variables) == "currency" else "double"  # live Power BI (Task 16 review): it keeps a Currency
    if fn in {"SUMX", "MAXX", "MINX"}:
        if len(args) >= 2:
            table_cols = _static_table_columns(args[0], columns, variables)
            scope = {**columns, "": table_cols} if table_cols else columns
            return _static_numeric_type(args[1], scope, variables)
        return None
    if fn == "CALCULATE":
        if args:
            return _static_numeric_type(args[0], columns, variables)
        return None
    if fn in {"IF", "IF.EAGER", "SWITCH", "IFERROR", "COALESCE"}:
        if fn in {"IF", "IF.EAGER"}:
            res_nodes = list(args[1:])
        elif fn == "SWITCH":
            res_nodes = [args[i] for i in range(2, len(args), 2)]
            if len(args) >= 4 and len(args) % 2 == 0:
                res_nodes.append(args[-1])
        else:
            res_nodes = list(args)
        types = [_static_numeric_type(r, columns, variables) for r in res_nodes]
        if fn == "IFERROR" and types[:1] and types[0] in {"int64", "double", "currency"} and types[1:] == ["text"]:
            return types[0]  # Part B: the replacement text only shows where the number is an error
        known = {t for t in types if t != "blank"}
        if len(known) == 1 and None not in known:
            return known.pop()
        if "datetime" in known and any(r[:2] == ("call", "ERROR") for r in res_nodes):
            return None  # Task 41: ISDOUBLE(IF(1=0,ERROR("e"),DATE(2020,1,1))) is False in Power BI (a Double beside a date is True); not settled
        return _unify_numeric_types(types)
    return None


_STATIC_DATE_REFUSING_ITERATORS = frozenset({"PRODUCTX", "MEDIANX", "GEOMEANX", "PERCENTILEX.INC", "PERCENTILEX.EXC"})
_STATIC_DATE_FUNCTIONS = frozenset({"DATE", "TIME", "DATEVALUE", "TIMEVALUE", "EDATE", "EOMONTH", "NOW", "TODAY", "UTCNOW", "UTCTODAY"})



_TEXT_MAKING_CALLS = frozenset({
    "FORMAT", "FIXED", "CONCATENATE", "CONCATENATEX", "LEN", "LEFT", "RIGHT", "MID", "SUBSTITUTE", "REPLACE", "UPPER", "LOWER", "TRIM", "REPT",
    "SEARCH", "FIND", "EXACT", "UNICODE", "TOCSV", "TOJSON", "CONTAINSSTRING", "CONTAINSSTRINGEXACT", "COMBINEVALUES", "VALUE",
})


def _mark_calls(node: Any, name: str, found: set[int], variable_nodes: dict[str, Any] | None = None, seen: set[int] | None = None) -> None:
    """Add the id of every call to `name` inside the expression (and inside the VAR it reads) to `found`."""
    seen = set() if seen is None else seen
    if isinstance(node, (tuple, list)) and id(node) not in seen:
        seen.add(id(node))
        if isinstance(node, tuple) and len(node) > 1 and node[0] == "call" and node[1] == name:
            found.add(id(node))
        if isinstance(node, tuple) and len(node) > 1 and node[0] == "var" and variable_nodes and node[1] in variable_nodes:
            _mark_calls(variable_nodes[node[1]], name, found, variable_nodes, seen)
        for part in node:
            _mark_calls(part, name, found, variable_nodes, seen)


def _mark_calls_under_concat(node: Any, name: str, found: set[int], variable_nodes: dict[str, Any]) -> None:
    """Add the id of every call to `name` that feeds a text join (&) or a text function in the expression, also through the VARs it reads."""
    if isinstance(node, (tuple, list)):
        if isinstance(node, tuple) and node and (
            node[0] == "concat"
            or (node[0] == "call" and (node[1] in _TEXT_MAKING_CALLS or (node[1] == "CONVERT" and len(node[2]) == 2 and node[2][1][-1] == "STRING")))
        ):
            _mark_calls(node, name, found, variable_nodes)
        for part in node:
            _mark_calls_under_concat(part, name, found, variable_nodes)


def _product_depends_on_multiplication_order(values: list[Decimal]) -> bool:
    """True when the exact product, the double product in row order and the product by logarithms differ at 15 significant digits."""
    if len(values) < 2 or any(v == 0 for v in values):
        return False
    exact = Decimal(1)
    for value in values:
        exact *= value
    running = 1.0
    for value in values:
        running *= float(value)
    if not math.isfinite(running):
        return False
    try:
        logged = math.exp(math.fsum(math.log(abs(float(v))) for v in values))
    except (OverflowError, ValueError):
        return False
    if sum(1 for v in values if v < 0) % 2:
        logged = -logged
    shown = {f"{float(exact):.14e}", f"{running:.14e}", f"{logged:.14e}"}
    # exp of a plain running sum of logarithms (the rows in stored order, smallest first, largest first): the evidence cannot say which order Power BI sums in (live: the
    # EDATE(DATE(2010,7,7)+0.25,2) product is 4.36269736004559E+27, which only the smallest-first sum gives)
    sign = -1.0 if sum(1 for v in values if v < 0) % 2 else 1.0
    magnitudes = [abs(float(v)) for v in values]
    for ordered in ((magnitudes, sorted(magnitudes), sorted(magnitudes, reverse=True)) if len(set(values)) > 1 else ()):  # a body that is the same on every row was measured exact
        total = 0.0
        for magnitude in ordered:
            total += math.log(magnitude)
        try:
            shown.add(f"{sign * math.exp(total):.14e}")
        except OverflowError:
            return False
    return len(shown) > 1

def _mentions_date(node: Any, columns: dict[str, dict[str, str]]) -> bool:
    """True when any part of the expression is a date function or a date column (the type a date body takes through arithmetic is not tracked)."""
    if isinstance(node, tuple):
        if node and _static_date(node, columns) and node[0] in {"call", "reference"}:
            return True
        return any(_mentions_date(part, columns) for part in node)
    if isinstance(node, list):
        return any(_mentions_date(part, columns) for part in node)
    return False


def _static_date(node: Any, columns: dict[str, dict[str, str]]) -> bool:
    """True when the expression is typed as a date whatever the data: a date function, a date column, a date plus or minus a number."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "reference":
        table = (node[1] or "").casefold()
        col = str(node[2]).casefold()
        if table:
            return columns.get(table, {}).get(col) in {"date", "datetime"}
        return columns.get("", {}).get(col) in {"date", "datetime"}
    if node[0] == "binary":
        op, left, right = node[1], node[2], node[3]
        if op == "-":
            return _static_date(left, columns)
        if op == "+":
            return _static_date(left, columns) or _static_date(right, columns)
        return False
    return node[0] == "call" and node[1] in _STATIC_DATE_FUNCTIONS


_CONVERT_TARGET_STATIC = {
    "INTEGER": "number", "INT64": "number", "DOUBLE": "number", "CURRENCY": "number", "DECIMAL": "number",
    "BOOLEAN": "boolean", "STRING": "text", "DATETIME": "date",
}


def _static_type(node: Any, columns: dict[str, dict[str, str]], variables: dict[str, str | None]) -> str | None:
    """text / number / boolean when the expression has that type whatever the data, else None (unknown or mixed).

    Power BI checks the operands of a comparison against each other when it compiles the query, so a BLANK() result
    of an expression typed Text still cannot be compared with a number."""
    if not isinstance(node, tuple) or not node:
        return None
    kind = node[0]
    if kind == "number":
        return "number"
    if kind == "string":
        return "text"
    if kind == "boolean":
        return "boolean"
    if kind in {"comparison", "logical", "in", "strict_equal"}:
        return "boolean"
    if kind == "unary" and node[1] == "+" and _static_type(node[2], columns, variables) == "boolean":
        return "boolean"  # unary plus leaves a True/False a True/False (live Power BI, iteration 87)
    if kind in {"binary", "unary"}:
        return "number"
    if kind == "concat":
        return "text"
    if kind == "var":
        return variables.get(str(node[1]))
    if kind == "reference":
        table = (node[1] or "").casefold()
        col = str(node[2]).casefold()
        column_type = None
        if table:
            column_type = columns.get(table, {}).get(col)
        else:
            column_type = columns.get("", {}).get(col)  # an unqualified column is one of the iterated table, never a stored column of that name
        if not column_type:
            return None
        if column_type in _NUMBER_COLUMN_TYPES:
            return "number"
        if column_type in {"boolean", "true_false", "bool"}:
            return "boolean"
        return "text" if column_type in {"text", "string"} else None  # dates are compared with ISO text literals
    if kind == "let":
        scope = dict(variables)
        for name, value in node[1]:
            scope[str(name)] = _static_type(value, columns, scope)
        return _static_type(node[2], columns, scope)
    if kind != "call":
        return None
    function, arguments = node[1], node[2]
    if function in _STATIC_ALWAYS_INT64 or function in _STATIC_ALWAYS_DOUBLE or function in {"INT", "COUNTROWS", "SUM", "SUMX", "AVERAGE", "AVERAGEX", "CURRENCY"}:
        return "number"  # Task 20: CURRENCY is a number, so MIN or MAX of it with text is refused as it is in Power BI
    if function in {"SELECTEDVALUE", "LOOKUPVALUE"} and arguments:
        return _static_type(arguments[0], columns, variables)
    if function in {"FIRSTNONBLANKVALUE", "LASTNONBLANKVALUE"} and len(arguments) == 2:
        return "number" if arguments[1] == ("blank",) or arguments[1][:2] == ("call", "BLANK") else _static_type(arguments[1], columns, variables)  # live Power BI (Task 13 review): typed Integer
    if function in {"FIRSTNONBLANK", "LASTNONBLANK"} and len(arguments) == 2:
        source = _nonblank_source_column(arguments[0])
        return None if source is None else _static_type(source, columns, variables)
    if function == "CALCULATE" and arguments:
        return _static_type(arguments[0], columns, variables)  # live Power BI (Task 11 review): CALCULATE(MAX(text column)) is Text
    if function in {"MAX", "MIN"} and len(arguments) == 1 and arguments[0][0] == "reference":
        return _static_type(arguments[0], columns, variables)  # live Power BI (Task 11 review): MAX of a text column is Text, beside COUNTROWS an error
    if function in _DATE_FUNCTIONS or function == "DATE":
        return "date"
    if function in _TEXT_FUNCTIONS:
        return "text"
    if function in _BOOLEAN_FUNCTIONS:
        return "boolean"
    if function == "CONVERT" and len(arguments) == 2 and arguments[1][0] == "table":
        return _CONVERT_TARGET_STATIC.get(str(arguments[1][1]).upper())  # Task 19 Part A: the target type is static, whatever the value (IF, VAR, COALESCE and IFERROR follow it)
    if function in {"IF", "IF.EAGER", "COALESCE", "IFERROR", "SWITCH"}:
        if function in {"IF", "IF.EAGER"}:
            results = list(arguments[1:])
        elif function == "SWITCH":
            results = [arguments[index] for index in range(2, len(arguments), 2)]
            if len(arguments) >= 4 and len(arguments) % 2 == 0:
                results.append(arguments[-1])
        else:
            results = list(arguments)
        if not results:
            return None
        types = {_static_type(result, columns, variables) for result in results if result[0] != "blank"}
        if not types:
            return "number"  # a conditional that can only give BLANK() is typed Integer
        if types <= {"number", "date"}:
            return "number" if "number" in types else "date"
        return types.pop() if len(types) == 1 and None not in types else None
    return None


def _spells_boolean_or_number(text: str) -> bool:
    if text == "" or text.strip().casefold() in {"true", "false"}:
        return True
    try:
        dax_typed.text_to_number(text)
    except (MeasureError, ArithmeticError, ValueError):
        return False
    return True


_TABLE_AS_SCALAR_MARKERS = ("Table-valued functions", "needs a column reference", "A table name is only supported")
_ENGINE_LIMIT_MARKERS = ("local engine", "local DAX engine", "not modelled", "not modeled", "not supported in the local")


def _has_conditional_or_var(node: Any) -> bool:
    """Whether the expression holds an IF / SWITCH / IFERROR / COALESCE or a VAR block: its static type is not that of the value one row gives."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "let" or (node[0] == "call" and node[1] in {"IF", "IF.EAGER", "SWITCH", "IFERROR", "COALESCE"}):
        return True
    return any(_has_conditional_or_var(child) if isinstance(child, tuple) else (
        isinstance(child, (list, tuple)) and any(_has_conditional_or_var(item) for item in child if isinstance(item, tuple))
    ) for child in node[1:])


def _type_display(static: str) -> str:
    return {"number": "Integer", "text": "Text", "boolean": "True/False", "date": "Date"}.get(static, "True/False")


def _nonblank_source_column(node: Any) -> Any:
    """The column FIRSTNONBLANK and its relatives read from their first argument: the column itself, or VALUES / DISTINCT / FILTER of it."""
    while isinstance(node, tuple) and node:
        if node[0] == "reference":
            return node
        if node[0] == "table_call":
            node = node[2]
        elif node[0] == "call" and node[1] in {"VALUES", "DISTINCT", "FILTER", "CALCULATETABLE", "ALL"} and node[2]:
            node = node[2][0]
        else:
            return None
    return None


def _strict_operand_type(node: tuple[Any, ...], columns: dict[str, dict[str, str]], variables: dict[str, str | None]) -> str | None:
    """The type == checks (live Power BI, Task 16 review): only a literal BLANK() fits every type, a VAR holding it is an Integer; None when not known."""
    if node == ("blank",):
        return None
    probe, bound = node, {}
    while probe[0] in {"let", "var"} and (probe[0] == "let" or str(probe[1]) in bound):
        if probe[0] == "let":
            bound.update({str(name): value for name, value in probe[1]})
            probe = probe[2]
        else:
            probe = bound.pop(str(probe[1]))
    if probe == ("blank",) or (probe[0] == "call" and probe[1] == "BLANK" and not probe[2]):
        return "number"
    if probe == ("blank",) or probe[:2] == ("call", "BLANK"):
        return "blank"
    if probe[:2] == ("call", "SELECTEDVALUE"):
        if len(probe[2]) == 1:
            probe = probe[2][0]
        elif len(probe[2]) == 2:
            column_type = _strict_operand_type(probe[2][0], columns, variables)
            alternate_type = column_type if probe[2][1] == ("blank",) or probe[2][1][:2] == ("call", "BLANK") else _strict_operand_type(probe[2][1], columns, variables)  # a BLANK() alternate takes the column's type
            # Two-argument form: typed as its column when the alternate is the same family, else a Variant (unknown here)
            return column_type if column_type is not None and column_type == alternate_type else None
    if probe[0] == "call" and probe[1] in {"MAXX", "MINX"} and len(probe[2]) >= 2:
        table_cols = _static_table_columns(probe[2][0], columns, variables)
        iter_cols = {**columns, "": table_cols} if table_cols else columns
        return _strict_operand_type(probe[2][1], iter_cols, variables)
    if probe[0] == "reference":
        table = (probe[1] or "").casefold()
        col = str(probe[2]).casefold()
        col_type = columns.get(table, {}).get(col) or columns.get("", {}).get(col)
        if col_type in {"text", "string"}:
            return "text"
        if col_type in _NUMBER_COLUMN_TYPES:
            return "number"
        if col_type in {"boolean", "bool", "true_false"}:
            return "boolean"
        if col_type in {"date", "datetime"}:
            return "date"
        if not table and "" not in columns:
            return None
    known = _static_type(probe, columns, variables)
    if known is None and _static_numeric_type(probe, columns, variables) in {"int64", "double", "currency"}:
        return "number"
    return known


def _mixed_selectedvalue(node: Any, columns: dict[str, dict[str, str]]) -> bool:
    """A two-argument SELECTEDVALUE whose alternate is of another type family than its column is a Variant (live Power BI, Task 44): COUNTX counts only its numbers and dates."""
    if not isinstance(node, tuple) or not node:
        return False
    if node[0] == "call" and node[1] == "SELECTEDVALUE" and len(node[2]) == 2 and node[2][1] != ("blank",) and node[2][1][:2] != ("call", "BLANK"):
        column_type, alternate_type = _strict_operand_type(node[2][0], columns, {}), _strict_operand_type(node[2][1], columns, {})
        if column_type is None or alternate_type is None or column_type != alternate_type:
            return True
    return any(isinstance(child, tuple) and _mixed_selectedvalue(child, columns) for child in node)


def _reject_mismatched_strict_operands(left: tuple[Any, ...], right: tuple[Any, ...], columns: dict[str, dict[str, str]], variables: dict[str, str | None]) -> None:
    types = (_strict_operand_type(left, columns, variables), _strict_operand_type(right, columns, variables))
    if "blank" in types or None in types:
        return
    if types[0] != types[1] and ("text" in types or set(types) <= {"number", "boolean"}):
        def shown(operand: tuple[Any, ...], kind: str | None) -> str:
            if kind == "number":
                return {"double": "Number", "currency": "Currency"}.get(str(_static_numeric_type(operand, columns, variables)), "Integer")
            if kind == "date":
                return "Date"
            return "True/False" if kind == "boolean" else "Text"

        raise MeasureError(
            f"DAX comparison operations do not support comparing values of type {shown(left, types[0])} with values of type {shown(right, types[1])}. "
            "Consider using the VALUE or FORMAT function to convert one of the values."
        )


def _reject_mismatched_comparison_types(node: Any, columns: dict[str, dict[str, str]], variables: dict[str, str | None] | None = None, *, unevaluated: bool = False) -> None:
    variables = {} if variables is None else variables
    if not isinstance(node, tuple) or not node:
        return
    if node[0] == "call" and node[1] == "ISBLANK" and node[2] and _never_blank(node[2][0]):
        unevaluated = True  # Task 20 Part A: ISBLANK does not evaluate a never-blank argument; the type tests below are not refused there
    if node[0] == "strict_equal":
        _reject_mismatched_strict_operands(node[1], node[2], columns, variables)
    if node[0] == "let":
        scope = dict(variables)
        columns = dict(columns)
        for name, value in node[1]:
            _reject_mismatched_comparison_types(value, columns, scope)
            scope[str(name)] = _static_type(value, columns, scope)
            columns[_TABLE_VARIABLE + str(name).casefold()] = _static_table_columns(value, columns, {})
        _reject_mismatched_comparison_types(node[2], columns, scope)
        return
    if node[0] == "reference" and node[1] and columns:
        known = columns.get(str(node[1]).casefold())
        if known is None:
            raise MeasureError(f"Cannot find table '{node[1]}'.")
        if str(node[2]).casefold() not in known:
            raise MeasureError(f"Column '{node[2]}' in table '{node[1]}' cannot be found or may not be used in this expression.")
    if node[0] == "call" and node[1] in {"EARLIER", "EARLIEST"} and len(node[2]) == 2:
        level = node[2][1]
        if level[0] != "number" or level[1] != level[1].to_integral_value() or level[1] < 1 or level[1].as_tuple().exponent > 0 or "." in str(level[1]):
            raise MeasureError("The second argument of function EARLIER must be an integer greater than zero.")
    if node[0] == "call":
        function, arguments = node[1], node[2]
        if function in {"SUMX", "AVERAGEX", "PRODUCTX", "MEDIANX", "MAXX", "MINX", *dax_math.STAT_ITERATORS} and len(arguments) >= 2:
            table_cols = _static_table_columns(arguments[0], columns, variables)
            iter_cols = {**columns, "": table_cols} if table_cols else columns
            result_type = _static_type(arguments[1], iter_cols, variables)
            if result_type == "boolean" or (result_type == "text" and function not in {"MAXX", "MINX", "COUNTX"}):
                raise MeasureError(f"The function {function} cannot work with values of type {'Boolean' if result_type == 'boolean' else 'String'}.")
            if function in _STATIC_DATE_REFUSING_ITERATORS and (_static_date(arguments[1], iter_cols) or result_type == "date"):
                raise MeasureError(f"{function} does not support expressions of type date.")  # at compile time: an untaken branch fails too (live Power BI, Task 13 review)
        elif function in {"SUM", "AVERAGE"} and len(arguments) == 1 and _static_type(arguments[0], columns, variables) == "text":
            raise MeasureError(f"The function {function} cannot work with values of type String.")
        elif function in {"MIN", "MAX"} and len(arguments) == 2 and all(_static_type(argument, columns, variables) == "boolean" for argument in arguments):
            raise MeasureError("Min or Max of booleans are not currently supported.")
        elif function in {"MIN", "MAX"} and len(arguments) == 2 and {_static_type(argument, columns, variables) for argument in arguments} == {"text", "number"}:
            raise MeasureError(f"The function {function} cannot compare text with a number.")
        elif function == "NAMEOF":
            arg = arguments[0]
            if arg[0] == "table":
                if columns and str(arg[1]).casefold() not in columns:
                    raise MeasureError("Only measure or fully-qualified column or table or calendar references are allowed in NAMEOF function.")
        elif function in {"ISINTEGER", "ISINT64", "ISDOUBLE", "ISDECIMAL", "ISCURRENCY"}:
            if arguments and not unevaluated:
                st = _static_numeric_type(arguments[0], columns, variables)
                if st is None:
                    raise MeasureError(f"Cannot determine static type for function {function}.")
        elif function in {"ISONORAFTER", "ISAFTER"}:
            for i in range(0, len(arguments) - 1, 3):
                left_t = _static_type(arguments[i], columns, variables)
                right_t = _static_type(arguments[i + 1], columns, variables)
                if left_t and right_t and left_t != right_t and not ({left_t, right_t} <= {"number", "date"}):
                    raise MeasureError(
                        f"DAX comparison operations do not support comparing values of type {_type_display(left_t)} with values of type {_type_display(right_t)}. "
                        "Consider using the VALUE or FORMAT function to convert one of the values."
                    )
    if node[0] == "call" and node[1] in {"MAX", "MIN"} and len(node[2]) == 2:
        kinds = {_static_type(argument, columns, variables) for argument in node[2]}
        if "boolean" in kinds:
            raise MeasureError("Min or Max of booleans are not currently supported.")  # live Power BI (Task 13 review): when the query is compiled, IFERROR does not catch it
        if {"date", "text"} <= kinds:
            raise MeasureError(
                "DAX comparison operations do not support comparing values of type Date with values of type Text. "
                "Consider using the VALUE or FORMAT function to convert one of the values."
            )
    if node[0] == "call" and node[1] == "SWITCH" and len(node[2]) >= 3:
        subject = _static_type(node[2][0], columns, variables)
        for candidate in node[2][1:len(node[2]) - (len(node[2]) % 2 == 0)][::2]:
            value_type = _static_type(candidate, columns, variables)
            if subject and value_type and subject != value_type and not ({subject, value_type} <= {"number", "date"}):
                raise MeasureError(
                    f"DAX comparison operations do not support comparing values of type {_type_display(subject)} with values of type {_type_display(value_type)}. "
                    "Consider using the VALUE or FORMAT function to convert one of the values."
                )  # live Power BI (Task 13 review): SWITCH(TRUE(), "x", ...) also over an empty table, and IFERROR does not catch it
    if node[0] == "comparison":
        left, right = _static_type(node[2], columns, variables), _static_type(node[3], columns, variables)
        if left and right and left != right and not ({left, right} <= {"number", "date"}):
            raise MeasureError(
                f"DAX comparison operations do not support comparing values of type {_type_display(left)} with values of type {_type_display(right)}. "
                "Consider using the VALUE or FORMAT function to convert one of the values."
            )
    for part in node[1:]:
        if isinstance(part, tuple) and part and isinstance(part[0], str):
            _reject_mismatched_comparison_types(part, columns, variables, unevaluated=unevaluated)
        elif isinstance(part, (tuple, list, frozenset)):
            for item in part:
                if isinstance(item, tuple):
                    _reject_mismatched_comparison_types(item, columns, variables, unevaluated=unevaluated)



def evaluate_measures(
    measures: Iterable[dict[str, str]],
    rows: list[dict[str, Any]],
    headers: list[str],
    table_name: str = "",
    *,
    measure_names: Iterable[str] | None = None,
    table_context: Iterable[dict[str, Any]] | None = None,
    relationships: Iterable[dict[str, Any]] = (),
    filter_table_ids: Iterable[str] = (),
    active_table_id: str | None = None,
    visual_axis_context: VisualAxisContext | None = None,
) -> dict[str, Decimal | None]:
    """Evaluate measures over local tables and their active relationship paths."""
    definitions = validate_measures(list(measures))
    by_name = {item["name"].casefold(): item for item in definitions}
    parsed = {item["name"].casefold(): parse_expression(item["expression"]) for item in definitions}

    contexts_by_id: dict[str, dict[str, Any]] = {}
    if table_context is not None:
        for item in table_context:
            if not isinstance(item, dict):
                raise MeasureError("Each loaded table needs an ID, name, columns, and rows.")
            table_id = item.get("id")
            if not isinstance(table_id, str) or not table_id:
                raise MeasureError("A loaded table is missing its model ID.")
            if table_id in contexts_by_id:
                raise MeasureError("Loaded model table IDs must be unique.")
            table_headers = item.get("headers")
            table_rows = item.get("rows")
            if not isinstance(table_headers, list) or not isinstance(table_rows, list):
                raise MeasureError("A loaded table is missing its columns or rows.")
            normalized_headers = [str(header) for header in table_headers]
            header_by_key = {
                header.casefold(): header for header in normalized_headers
            }
            supplied_column_rows = item.get("filter_column_rows", {})
            if not isinstance(supplied_column_rows, dict):
                raise MeasureError(
                    f"Loaded table {item.get('name', table_id)!r} has an invalid per-column filter context."
                )
            filter_column_rows: dict[str, frozenset[int]] = {}
            for column, indexes in supplied_column_rows.items():
                actual_column = header_by_key.get(str(column).casefold())
                if actual_column is None:
                    raise MeasureError(
                        f"Loaded table {item.get('name', table_id)!r} has filter context for an unavailable column."
                    )
                if (
                    not isinstance(indexes, (list, tuple, set, frozenset))
                    or any(type(index) is not int or not 0 <= index < len(table_rows) for index in indexes)
                ):
                    raise MeasureError(
                        f"Loaded table {item.get('name', table_id)!r} has invalid per-column filter rows."
                    )
                filter_column_rows[actual_column] = frozenset(indexes)
            supplied_blank_allowed = item.get("filter_column_blank_allowed", {})
            if not isinstance(supplied_blank_allowed, dict):
                raise MeasureError(
                    f"Loaded table {item.get('name', table_id)!r} has invalid blank-filter provenance."
                )
            filter_column_blank_allowed: dict[str, bool] = {}
            for column, allowed in supplied_blank_allowed.items():
                actual_column = header_by_key.get(str(column).casefold())
                if actual_column is None or type(allowed) is not bool:
                    raise MeasureError(
                        f"Loaded table {item.get('name', table_id)!r} has invalid blank-filter provenance."
                    )
                filter_column_blank_allowed[actual_column] = allowed
            supplied_table_rows = item.get("filter_table_rows")
            if supplied_table_rows is not None and (
                not isinstance(supplied_table_rows, (list, tuple, set, frozenset))
                or any(
                    type(index) is not int or not 0 <= index < len(table_rows)
                    for index in supplied_table_rows
                )
            ):
                raise MeasureError(
                    f"Loaded table {item.get('name', table_id)!r} has invalid table-filter rows."
                )
            filter_context_complete = item.get("filter_context_complete", False)
            if type(filter_context_complete) is not bool:
                raise MeasureError(
                    f"Loaded table {item.get('name', table_id)!r} has an invalid filter-context marker."
                )
            contexts_by_id[table_id] = {
                "id": table_id,
                "name": str(item.get("name") or table_id),
                "headers": normalized_headers,
                "rows": list(table_rows),
                "column_types": dict(item.get("column_types", {})),
                "date_column": str(item.get("date_column") or ""),
                "model_customised": [str(setting) for setting in item.get("model_customised", ())],
                "model_expressions": item.get("model_expressions", False) is True,
                "filter_column_rows": filter_column_rows,
                "filter_column_blank_allowed": filter_column_blank_allowed,
                "filter_context_complete": filter_context_complete,
                **({"filter_rows": list(item["filter_rows"])} if "filter_rows" in item else {}),
                **({"filter_table_rows": frozenset(supplied_table_rows)}
                   if supplied_table_rows is not None else {}),
            }

    active_context = contexts_by_id.get(active_table_id or "")
    if active_context is None and table_name:
        active_context = next(
            (item for item in contexts_by_id.values()
             if item["name"].casefold() == table_name.casefold()),
            None,
        )
    if active_context is None and len(contexts_by_id) == 1:
        active_context = next(iter(contexts_by_id.values()))
    if active_context is None:
        synthetic_id = active_table_id or "__active_table__"
        if synthetic_id in contexts_by_id:
            raise MeasureError("The active table ID does not identify the selected table.")
        active_context = {
            "id": synthetic_id,
            "name": table_name or "Active table",
            "headers": list(headers),
            "rows": list(rows),
            "column_types": {},
            "filter_column_rows": {},
            "filter_context_complete": False,
        }
        contexts_by_id[synthetic_id] = active_context
    active_table_id = active_context["id"]
    filter_ids = set(filter_table_ids)
    if active_table_id in filter_ids and "filter_rows" not in active_context:
        active_context["filter_rows"] = list(rows)
    if visual_axis_context is not None:
        if not isinstance(visual_axis_context, VisualAxisContext):
            raise MeasureError("The visual axis filter context is invalid.")
        axis_table = contexts_by_id.get(visual_axis_context.table_id)
        if axis_table is None:
            raise MeasureError("The chart axis table is not loaded in the model.")
        axis_columns = {
            column.casefold(): column for column in axis_table["headers"]
        }
        axis_column = axis_columns.get(visual_axis_context.column.casefold())
        if axis_column is None:
            raise MeasureError("The chart axis column is not loaded in the model.")
        selected_rows = visual_axis_context.selected_rows
        if selected_rows is not None and any(
            type(index) is not int or not 0 <= index < len(axis_table["rows"])
            for index in selected_rows
        ):
            raise MeasureError("The chart axis selection has invalid row indexes.")
        if (
            visual_axis_context.blank_allowed is not None
            and type(visual_axis_context.blank_allowed) is not bool
        ):
            raise MeasureError("The chart axis selection has invalid blank provenance.")
        if any(table_id not in contexts_by_id for table_id in visual_axis_context.filter_table_ids):
            raise MeasureError("The chart axis selection references an unavailable table.")
        visual_axis_context = VisualAxisContext(
            table_id=visual_axis_context.table_id,
            column=axis_column,
            selected_rows=(
                None if selected_rows is None else frozenset(selected_rows)
            ),
            blank_allowed=visual_axis_context.blank_allowed,
            filter_table_ids=frozenset(visual_axis_context.filter_table_ids),
        )
    evaluation_contexts_by_id = contexts_by_id
    evaluation_filter_ids = set(filter_ids)
    relationship_definitions = list(relationships)
    column_types_by_table = {
        str(ctx.get("name", "")).casefold(): {
            str(h).casefold(): str(ctx.get("column_types", {}).get(h, "")).casefold() for h in ctx.get("headers", [])
        }
        for ctx in contexts_by_id.values()
    }
    related_lookup_cache: dict[
        tuple[str, str, str, str, str],
        dict[tuple[str, Any], list[dict[str, Any]]],
    ] = {}

    table_names: dict[str, list[dict[str, Any]]] = {}
    for context in contexts_by_id.values():
        table_names.setdefault(context["name"].casefold(), []).append(context)

    try:
        unknown_member_ids = unknown_member_table_ids(
            list(contexts_by_id.values()), relationship_definitions
        )
    except (RelationshipError, DecimalException) as exc:
        raise MeasureError(f"Could not inspect model relationships: {exc}") from exc
    unknown_member_exclusions: dict[str, set[str] | None] = {}

    def unknown_member_hidden(table_id: str) -> bool:
        """ALLNOBLANKROW(T) removes the blank member from every view of T; ALLNOBLANKROW(T[column]) only keeps the rows that
        point at it out of the facts (live Power BI: VALUES(T[c]) still lists it, SUM over the facts drops its rows)."""
        return table_id in unknown_member_exclusions and unknown_member_exclusions[table_id] is None

    def own_unknown_member_selected(context: dict[str, Any], ignore_exclusion: bool = False) -> bool:
        """Do the filters on this table itself still select its virtual blank member (the predicate holds for a row of BLANKs)?"""
        table_id = context["id"]
        if table_id in unknown_member_exclusions and not ignore_exclusion:
            return False
        if "filter_table_rows" in context:
            return bool(context.get("filter_table_unknown", False))  # FILTER(VALUES(T)..) lists it, FILTER(T,..) never does
        blank_allowed = context.get("filter_column_blank_allowed", {})
        if not context.get("filter_column_rows") and "filter_rows" in context:
            return False  # rows supplied by a visual or slicer without per-column provenance: a selection never includes the blank
        return all(blank_allowed.get(column, False) for column in context.get("filter_column_rows", {}))

    def typed_cell(context: dict[str, Any], column: str, raw: Any) -> Any:
        """A loaded cell as the DAX value of its column type (None is blank)."""
        if raw is None:
            return None
        if isinstance(raw, _UnmodelledField):
            raw._refuse()  # reading it as a typed value (CONTAINS, lookups) would invent a value
        kind = str(context.get("column_types", {}).get(column, "text")).casefold()
        if kind in {"whole_number", "decimal_number", "decimal", "fixed_decimal", "currency", "number", "int64", "double"}:
            return raw if isinstance(raw, Decimal) else dax_typed.text_to_number(cell_to_text(raw))
        if kind in {"date", "datetime"}:
            return _cell_date_value(raw, column, None)
        if kind == "boolean":
            return raw if isinstance(raw, bool) else cell_to_text(raw).strip().casefold() == "true"
        return raw if isinstance(raw, str) else cell_to_text(raw)

    # What ALLSELECTED sees inside an iterator (tools/parity/dax_battery_allselected_shadow.json): the iterated table's
    # distinct tuples ("shadow", one component over the columns it came from), the outer filters those columns replace
    # ("suppressed"), and the filters that are only a context transition ("transition", which it never sees).
    eff_layers: tuple[_Shadow, ...] = ()
    eff_suppressed: dict[str, dict[str, Any]] = {}  # table -> casefolded column -> the outer filter object the shadow replaced
    eff_transition: dict[str, dict[str, tuple[Any, Any]]] = {}  # table -> casefolded column -> (filter a transition set, filter it replaced)
    eff_group_keys: dict[str, dict[str, Any]] = {}  # SUMMARIZE group keys: table -> casefolded column -> the filter object
    eff_touched: frozenset[tuple[str, str]] = frozenset()  # (table, column) a CALCULATE modifier has cleared or filtered
    eff_blocked = False
    eff_rank_table = False  # evaluating the table argument of RANKX: ALLSELECTED(col) still sees a SUMMARIZE key on its own column

    shadowed_cache: list[frozenset[str]] = []

    def shadowed_measure_keys() -> frozenset[str]:
        """Lower-case names of the measures that share their name with a column of their own table."""
        if not shadowed_cache:
            keys = set()
            for definition in definitions:
                home = contexts_by_id.get(str(definition.get("home_table_id") or ""))
                if home is not None and definition["name"].casefold() in {str(header).casefold() for header in home["headers"]}:
                    keys.add(definition["name"].casefold())
            shadowed_cache.append(frozenset(keys))
        return shadowed_cache[0]

    one_to_one_unmatched_cache: dict[str, tuple[frozenset[int], bool]] = {}

    def one_to_one_unmatched(table_id: str) -> tuple[frozenset[int], bool]:
        """(rows of this table with no partner across a one-to-one relationship, whether the table at the other end has such rows)."""
        if table_id not in one_to_one_unmatched_cache:
            own: set[int] = set()
            other_has = False
            for relationship in relationship_definitions:
                if not isinstance(relationship, dict) or relationship.get("cardinality") != "one_to_one":
                    continue
                ends = {
                    str(relationship.get("from_table_id")): str(relationship.get("from_column")),
                    str(relationship.get("to_table_id")): str(relationship.get("to_column")),
                }
                if table_id not in ends or len(ends) != 2:
                    continue
                other_id = next(identifier for identifier in ends if identifier != table_id)
                if other_id not in contexts_by_id:
                    continue

                def keys(identifier: str) -> list[Any]:
                    context = contexts_by_id[identifier]
                    return [cell_key(ascii_fold(v) if isinstance(v, str) else v) for v in (
                        typed_cell(context, ends[identifier], row.get(ends[identifier])) for row in context["rows"])]

                mine, theirs = keys(table_id), keys(other_id)
                blank = cell_key(None)
                present_theirs, present_mine = set(theirs) - {blank}, set(mine) - {blank}
                own |= {index for index, key in enumerate(mine) if key == blank or key not in present_theirs}
                other_has = other_has or any(key == blank or key not in present_mine for key in theirs)
            one_to_one_unmatched_cache[table_id] = (frozenset(own), other_has)
        return one_to_one_unmatched_cache[table_id]

    def refuse_one_to_one_blank_reader(table_id: str, what: str, any_filter: bool = False) -> None:
        """Live Power BI (iteration 84, critic; 6 of 1,033 fresh ZM probes): reading the values of a table of a one-to-one relationship that has
        unmatched rows, while the pair is filtered, lists the blank members of both ends in a way not modelled here
        (CALCULATE(SELECTEDVALUE(U[K],"x"), NOT(U[X]="x1"), W[K]=BLANK()) is "x", ours "k4")."""
        for relationship in relationship_definitions:
            if not isinstance(relationship, dict) or not relationship.get("is_active") or relationship.get("cardinality") != "one_to_one":
                continue
            ends = (str(relationship.get("from_table_id")), str(relationship.get("to_table_id")))
            if table_id not in ends or len(set(ends)) != 2:
                continue
            if any(
                end in evaluation_filter_ids and not eff_transition.get(end) and not eff_group_keys.get(end) and end in evaluation_contexts_by_id
                and (any_filter or own_unknown_member_selected(evaluation_contexts_by_id[end]))
                and not (any_filter and end == table_id)  # ALLSELECTED: only the partner's filter is out of reach (the table's own filter stays)
                for end in ends
            ) and any(one_to_one_unmatched(end)[0] for end in ends):
                raise MeasureError(f"{what} over a table of a one-to-one relationship with unmatched rows is not supported while it is filtered in the local engine.")

    def refuse_one_to_one_values_iteration(table_node: tuple[Any, ...]) -> None:
        """Live Power BI (iteration 84, testing agent): SUMX(VALUES(W[Y]), CALCULATE(SUM(F[Amt]))) with the partner U filtered so that one of
        its rows without a partner in W stays visible adds the blank member of W to the iteration (CALCULATE(.., U[K]="k4") is 16 where
        COUNTROWS(VALUES(W[Y])) and CONCATENATEX over the same VALUES list no blank).  Which functions list it is not modelled, so this is refused."""
        if table_node[0] != "table_call" or table_node[1] not in {"VALUES", "DISTINCT"} or not table_node[2]:
            return
        source = table_node[2]
        try:
            if source[0] == "reference":
                iterated = resolve_table(source[1], source[2])[0]
            elif source[0] == "table":
                iterated = resolve_table_context(str(source[1]))
            else:
                return
        except MeasureError:
            return
        for relationship in relationship_definitions:
            if not isinstance(relationship, dict) or not relationship.get("is_active") or relationship.get("cardinality") != "one_to_one":
                continue
            ends = (str(relationship.get("from_table_id")), str(relationship.get("to_table_id")))
            if iterated["id"] not in ends or len(set(ends)) != 2:
                continue
            partner = next(end for end in ends if end != iterated["id"])
            held = evaluation_contexts_by_id.get(iterated["id"], {})
            if held.get("filter_column_rows") and not eff_transition.get(iterated["id"]) and all(
                isinstance(rows, BlankSet) and rows.blank and rows.peer for rows in held["filter_column_rows"].values()
            ):  # the iterated table was reached through the orphan row of its partner by a table filter (a fact filter FILTER(F, ..))
                raise MeasureError("Iterating the values of a table of a one-to-one relationship narrowed through its partner's orphan row is not supported in the local engine.")
            if partner not in evaluation_filter_ids or partner not in contexts_by_id:
                continue
            own = one_to_one_unmatched(partner)[0]
            partner_rows = contexts_by_id[partner]["rows"]
            orphans = {id(partner_rows[index]) for index in own}
            if any(id(row) in orphans for row in rows_by_table_id.get(partner, ())):
                raise MeasureError("Iterating the values of a table of a one-to-one relationship whose filtered partner keeps rows without a partner is not supported in the local engine.")

    def refuse_one_to_one_pair_filters(tables: list[dict[str, Any]], filter_table_ids: set[Any]) -> None:
        """Live Power BI (iteration 84, critic; fresh ZM probes): when a filter on one table of a one-to-one relationship keeps only rows that
        have no partner and the filter on the other table keeps real rows and selects its own blank member, which blank members and orphan rows
        meet is not modelled here (CALCULATE(DISTINCTCOUNT(F[K]), U[K]<>"k5", W[Y]="y5") is BLANK, ours 1), so that pair is refused."""
        by_id = {str(table.get("id")): table for table in tables}
        for relationship in relationship_definitions:
            if not isinstance(relationship, dict) or not relationship.get("is_active") or relationship.get("cardinality") != "one_to_one":
                continue
            ends = (str(relationship.get("from_table_id")), str(relationship.get("to_table_id")))
            if len(set(ends)) != 2 or any(end not in filter_table_ids or end not in by_id or eff_transition.get(end) for end in ends):
                continue

            def visible_rows(table: dict[str, Any]) -> Any:
                visible: Any = None
                for rows in table.get("filter_column_rows", {}).values():
                    visible = frozenset(rows) if visible is None else visible & frozenset(rows)
                if "filter_table_rows" in table:
                    held = frozenset(table["filter_table_rows"])
                    visible = held if visible is None else visible & held
                return visible

            for mine, theirs in (ends, ends[::-1]):
                own, _other_has = one_to_one_unmatched(mine)
                kept, partner = visible_rows(by_id[mine]), visible_rows(by_id[theirs])
                if kept and kept <= own and partner and own_unknown_member_selected(by_id[theirs]):
                    raise MeasureError("Filters on both tables of a one-to-one relationship are not supported in the local engine.")

    def propagate_relationship_filters(
        tables: list[dict[str, Any]], relationships: list[dict[str, Any]], filter_table_ids: Any,
        ignore_exclusions: Iterable[str] = (),
    ) -> dict[str, list[dict[str, Any]]]:
        """Relationship propagation that also carries the virtual blank member: fact rows whose key has no match in a
        one-side table stay while that table's own filters still select its blank member."""
        refuse_one_to_one_pair_filters(tables, set(filter_table_ids))
        ignored = set(ignore_exclusions)
        excluded = {table_id for table_id in unknown_member_exclusions if table_id in unknown_member_ids and table_id not in ignored}
        filter_table_ids = set(filter_table_ids) | excluded  # ALLNOBLANKROW leaves no filter on its table, only the missing blank member
        selected = {
            str(table.get("id")): own_unknown_member_selected(table, str(table.get("id")) in ignored)
            for table in tables if table.get("id") in filter_table_ids and table.get("id") in unknown_member_ids
        }
        peer_blank = {
            str(table.get("id")) for table in tables
            if table.get("id") in filter_table_ids and table.get("filter_column_rows")
            and all(getattr(rows, "peer", False) for rows in table["filter_column_rows"].values())
        }
        many_blank = {
            str(table.get("id")) for table in tables
            if table.get("id") in filter_table_ids and table.get("filter_column_rows")
            and all(getattr(rows, "many", False) for rows in table["filter_column_rows"].values())
        }
        return _propagate_relationship_filters(tables, relationships, filter_table_ids, selected, peer_blank=peer_blank, many_blank=many_blank)

    try:
        rows_by_table_id = propagate_relationship_filters(
            list(contexts_by_id.values()),
            relationship_definitions,
            filter_ids,
        )
    except RelationshipError as exc:
        raise MeasureError(f"Could not apply model relationships: {exc}") from exc

    value_cache: dict[tuple[str, int], Decimal | None] = {}
    resolving: set[str] = set()
    context_sequence = 0
    current_context = 0
    current_home_table_id = active_context["id"]

    for measure in definitions:
        home_table_id = measure.get("home_table_id")
        if home_table_id is not None and home_table_id not in contexts_by_id:
            raise MeasureError(
                f"Measure {measure['name']!r} has a home table that is not loaded."
            )

    def resolve_table_context(table: str) -> dict[str, Any]:
        if not table:
            return evaluation_contexts_by_id.get(
                current_home_table_id, active_context
            )
        matches = table_names.get(table.casefold(), [])
        if not matches:
            raise MeasureError(f"Table {table!r} is not loaded in the model.")
        if len(matches) > 1:
            raise MeasureError(f"Table name {table!r} is ambiguous in the model.")
        return evaluation_contexts_by_id.get(matches[0]["id"], matches[0])

    def resolve_table(table: str, column: str) -> tuple[dict[str, Any], str]:
        context = resolve_table_context(table)
        header_by_key = {header.casefold(): header for header in context["headers"]}
        actual = header_by_key.get(column.casefold())
        if actual is None:
            raise MeasureError(
                f"Column {column!r} does not exist in table {context['name']!r}."
            )
        return context, actual

    def eff_active() -> bool:
        return not eff_blocked and (bool(eff_layers) or any(eff_transition.values()) or any(eff_suppressed.values()) or any(eff_group_keys.values()))

    def allselected_rows_for(source_context: dict[str, Any], columns: list[str]) -> list[dict[str, Any]] | None:
        """ALLSELECTED(columns) inside an iterator: the table rows that satisfy every filter touching those columns, where
        the filters are the iterator shadows, the explicit CALCULATE filters and the outer filters the shadows did not
        replace. Filters on other columns and the context transition do not count. None when the filter context cannot say."""
        table_id = source_context["id"]
        wanted = {column.casefold() for column in columns}
        cleared = {header.casefold() for header in source_context["headers"]} - wanted
        for folded, outer in eff_suppressed.get(table_id, {}).items():
            if current_filter(table_id, folded) is outer:  # still the outer filter the shadow replaced
                cleared.add(folded)
        for folded, key_rows in eff_group_keys.get(table_id, {}).items():
            if current_filter(table_id, folded) is key_rows:  # a group key still stands as the SUMMARIZE row set
                if folded in wanted and eff_rank_table:
                    cleared.discard(folded)  # Power BI: RANKX(ALLSELECTED(col), ...) in a SUMMARIZE column ranks within the group's key
                elif folded in wanted or any((table_id, name) in eff_touched for name in wanted):
                    cleared.add(folded)  # a key inside the columns asked for, or after a modifier touched them, drops out
                else:
                    cleared.discard(folded)  # a key outside them narrows the answer to its group
        replaced_outer: list[Any] = []
        for folded, (set_by_transition, outer) in eff_transition.get(table_id, {}).items():
            if current_filter(table_id, folded) is set_by_transition:  # still only the row's context transition
                cleared.add(folded)
                shadowed = eff_suppressed.get(table_id, {}).get(folded, _NOTHING)
                if folded in wanted and outer is not None and shadowed is not outer:
                    replaced_outer.append(outer)  # the outer filter the transition covered up is still in force for ALLSELECTED
        other_tables: dict[str, dict[str, Any]] = {}
        for other_id, tagged_columns in eff_transition.items():  # a row context of a related table also filtered the one-side tables
            if other_id == table_id:
                continue
            for folded, (set_by_transition, outer) in tagged_columns.items():
                if current_filter(other_id, folded) is set_by_transition:  # still only the row's transition: ALLSELECTED sees the outer filter it covered
                    other_tables.setdefault(other_id, {})[folded] = outer
        try:
            rows, _contexts, _roots = rows_after_clearing_columns(source_context, cleared, other_tables=other_tables)
        except MeasureError:
            return None
        full = source_context["rows"]
        if replaced_outer:
            keep_positions = set.intersection(*(set(outer) for outer in replaced_outer))
            visible = {id(row) for row in rows}
            rows = [row for position, row in enumerate(full) if position in keep_positions and id(row) in visible]
        allowed = {id(row) for row in rows}
        result = [row for row in full if id(row) in allowed] if len(allowed) != len(full) or any(id(r) not in allowed for r in full) else list(full)
        for layer in eff_layers:
            if layer.table != table_id:
                continue
            positions = [index for index, column in enumerate(layer.columns) if column.casefold() in wanted]
            if not positions:
                continue
            seen = frozenset(tuple(item[index] for index in positions) for item in layer.tuples)
            names = [layer.columns[index] for index in positions]
            result = [row for row in result if row_key(typed_cell(source_context, name, row.get(name)) for name in names) in seen]
        return result

    def rows_after_clearing_columns(
        source_context: dict[str, Any],
        columns_to_clear: set[str],
        with_expansion: bool = False,
        other_tables: dict[str, dict[str, Any]] | None = None,
    ) -> tuple[
        list[dict[str, Any]],
        dict[str, dict[str, Any]],
        set[str],
    ]:
        """Recompute a table's visible rows after removing only selected columns.

        other_tables: table id -> casefolded column -> the filter rows to put back there (None = no filter), for the filters
        of one-side tables that a row context set and ALLSELECTED must not see."""
        table_id = source_context["id"]
        updated_contexts = [
            dict(context) for context in evaluation_contexts_by_id.values()
        ]
        updated_by_id = {context["id"]: context for context in updated_contexts}
        updated = updated_by_id[table_id]
        existing_column_rows = dict(updated.get("filter_column_rows", {}))
        if _context_shapes(updated):
            clear_columns_from_shapes(updated, columns_to_clear, existing_column_rows)
        has_direct_filter_state = (
            table_id in evaluation_filter_ids
            or "filter_rows" in updated
            or bool(existing_column_rows)
        )
        if has_direct_filter_state and not updated.get("filter_context_complete", False):
            raise MeasureError(
                "ALL column table expressions need complete per-column filter context."
            )
        remaining_column_rows = {
            column: _frozen(indexes)
            for column, indexes in existing_column_rows.items()
            if column.casefold() not in columns_to_clear
        }
        updated["filter_column_rows"] = remaining_column_rows
        prune_cleared_shapes(updated, columns_to_clear)
        updated["filter_column_blank_allowed"] = {
            column: allowed
            for column, allowed in updated.get(
                "filter_column_blank_allowed", {}
            ).items()
            if column.casefold() not in columns_to_clear
        }
        updated["filter_context_complete"] = True
        updated_filter_roots = set(evaluation_filter_ids)
        if with_expansion:  # ALL(column) / ALLSELECTED(column) as a table: filters of the one-side tables do not reach the column (live Power BI)
            for related_id in cleared_by_column_table(table_id):
                related = updated_by_id[related_id]
                for state in ("filter_rows", "filter_table_rows", "filter_shapes", "filter_column_extra"):
                    related.pop(state, None)
                related["filter_column_rows"] = {}
                related["filter_column_blank_allowed"] = {}
                related["filter_context_complete"] = True
                updated_filter_roots.discard(related_id)
        for other_id, replacements in (other_tables or {}).items():
            other = updated_by_id[other_id]
            other_rows = {
                column: rows for column, rows in other.get("filter_column_rows", {}).items()
                if column.casefold() not in replacements
            }
            for folded, outer in replacements.items():
                if outer is not None:
                    other_rows[next(h for h in other["headers"] if h.casefold() == folded)] = frozenset(outer)
            for layer in eff_layers:  # the rows an enclosing iterator walks still narrow this table for ALLSELECTED
                if layer.table != other_id:
                    continue
                allowed = BlankSet(
                    (index for index, base_row in enumerate(other["rows"])
                     if row_key(typed_cell(other, column, base_row.get(column)) for column in layer.columns) in layer.tuples),
                    row_key(None for _column in layer.columns) in layer.tuples,  # the iterated rows list the unknown member
                )
                for column in layer.columns:
                    existing = other_rows.get(column)
                    other_rows[column] = allowed if existing is None else meet_rows(allowed, existing)
            other["filter_column_rows"] = other_rows
            other["filter_context_complete"] = True
            if other_rows:
                other["filter_rows"] = [
                    row for row_index, row in enumerate(other["rows"])
                    if all(row_index in indexes for indexes in other_rows.values())
                ]
                updated_filter_roots.add(other_id)
            else:
                other.pop("filter_rows", None)
                updated_filter_roots.discard(other_id)
        if remaining_column_rows:
            updated["filter_rows"] = [
                row
                for row_index, row in enumerate(updated["rows"])
                if all(
                    row_index in indexes
                    for indexes in remaining_column_rows.values()
                )
            ]
            updated_filter_roots.add(table_id)
        else:
            updated.pop("filter_rows", None)
            updated_filter_roots.discard(table_id)
        try:
            filtered_rows_by_id = propagate_relationship_filters(
                updated_contexts,
                relationship_definitions,
                updated_filter_roots,
                ignore_exclusions=cleared_by_column_table(table_id) if with_expansion else (),
            )
        except RelationshipError as exc:
            raise MeasureError(f"Could not apply ALL column filters: {exc}") from exc
        return (
            filtered_rows_by_id[table_id],
            updated_by_id,
            updated_filter_roots,
        )

    def rows_after_restoring_visual_axis() -> tuple[
        dict[str, dict[str, Any]], set[str], dict[str, list[dict[str, Any]]]
    ]:
        """Restore a chart's selected column context without its current category."""
        axis = visual_axis_context
        if axis is None:
            return evaluation_contexts_by_id, set(evaluation_filter_ids), rows_by_table_id
        updated_contexts = [
            dict(context) for context in evaluation_contexts_by_id.values()
        ]
        updated_by_id = {context["id"]: context for context in updated_contexts}
        updated = updated_by_id[axis.table_id]
        if "filter_table_rows" in updated or _context_shapes(updated):
            raise MeasureError(
                "ALLSELECTED chart totals cannot replace an opaque FILTER rowset."
            )
        existing_columns = dict(updated.get("filter_column_rows", {}))
        has_direct_filter_state = (
            axis.table_id in evaluation_filter_ids
            or "filter_rows" in updated
            or bool(existing_columns)
        )
        if has_direct_filter_state and not updated.get(
            "filter_context_complete", False
        ):
            raise MeasureError(
                "ALLSELECTED chart totals need complete per-column filter context."
            )
        matching_column = next(
            (
                column for column in existing_columns
                if column.casefold() == axis.column.casefold()
            ),
            None,
        )
        if matching_column is not None:
            del existing_columns[matching_column]
        if axis.selected_rows is not None:
            existing_columns[axis.column] = axis.selected_rows
        updated["filter_column_rows"] = {
            column: _frozen(indexes)
            for column, indexes in existing_columns.items()
        }

        blank_allowed = dict(updated.get("filter_column_blank_allowed", {}))
        if matching_column is not None:
            blank_allowed.pop(matching_column, None)
        if axis.selected_rows is not None and axis.blank_allowed is not None:
            blank_allowed[axis.column] = axis.blank_allowed
        else:
            blank_allowed.pop(axis.column, None)
        updated["filter_column_blank_allowed"] = blank_allowed
        updated["filter_context_complete"] = True

        updated_filter_roots = set(evaluation_filter_ids)
        if existing_columns:
            updated["filter_rows"] = [
                row
                for row_index, row in enumerate(updated["rows"])
                if all(
                    row_index in indexes
                    for indexes in existing_columns.values()
                )
            ]
            updated_filter_roots.add(axis.table_id)
        else:
            updated.pop("filter_rows", None)
            if axis.table_id not in axis.filter_table_ids:
                updated_filter_roots.discard(axis.table_id)

        try:
            filtered_rows_by_id = propagate_relationship_filters(
                updated_contexts,
                relationship_definitions,
                updated_filter_roots,
            )
        except RelationshipError as exc:
            raise MeasureError(
                f"Could not apply ALLSELECTED chart selection: {exc}"
            ) from exc
        return updated_by_id, updated_filter_roots, filtered_rows_by_id

    def unknown_member_passes_remaining_filters(
        source_context: dict[str, Any],
        contexts_by_id: dict[str, dict[str, Any]],
        filter_roots: set[str],
        columns_being_cleared: set[str] | None = None,
    ) -> bool:
        """Check whether the virtual blank survives direct and related filters."""
        source_id = source_context["id"]
        if source_id not in unknown_member_ids:
            return False
        current_source_context = contexts_by_id[source_id]
        if "filter_table_rows" in current_source_context and not current_source_context.get("filter_table_unknown", False):
            # FILTER(T, ..) iterates the stored rows only: the generated unknown member is never one of them.
            return False
        if unknown_member_hidden(source_id):
            return False
        blank_allowed = current_source_context.get(
            "filter_column_blank_allowed", {}
        )
        for column in current_source_context.get("filter_column_rows", {}):
            if column not in blank_allowed:
                raise MeasureError(
                    "ALL column table expressions need blank-filter provenance when a virtual unknown member is present."
                )
            if not blank_allowed[column]:
                return False

        independent_filter_roots = filter_roots - {source_context["id"]}
        visible_rows_by_id: dict[str, list[dict[str, Any]]] = {}
        if independent_filter_roots:
            independent_contexts = [
                context
                for table_id, context in contexts_by_id.items()
                if table_id != source_context["id"]
            ]
            independent_relationships = [
                relationship
                for relationship in relationship_definitions
                if not (
                    isinstance(relationship, dict)
                    and source_context["id"]
                    in {
                        str(relationship.get("from_table_id", "")),
                        str(relationship.get("to_table_id", "")),
                    }
                )
            ]
            try:
                propagated_without_target = propagate_relationship_filters(
                    independent_contexts,
                    independent_relationships,
                    independent_filter_roots,
                )
            except RelationshipError as exc:
                raise MeasureError(
                    f"Could not apply relationship filters to the virtual blank member: {exc}"
                ) from exc
            visible_rows_by_id = propagated_without_target

        try:
            context_unknown_members = unknown_member_table_ids(
                list(contexts_by_id.values()),
                relationship_definitions,
                visible_rows_by_id,
            )
        except (RelationshipError, DecimalException) as exc:
            raise MeasureError(
                f"Could not inspect model relationships: {exc}"
            ) from exc
        partner_selects_blank = False
        blank_partner_links: set[int] = set()
        for relationship in relationship_definitions:
            # live Power BI (iteration 84, critic): the blank member of a table in a one-to-one relationship is shown while the filter on its
            # partner selects the partner's own blank member (CALCULATE(COUNTROWS(VALUES(U[X])),W[K]<>"k4",W[K]<>"k5") counts it although the
            # orphan row W[k5] is filtered out) and is not shown for the kept orphan rows alone (CALCULATE(COUNTROWS(VALUES(U[K])),W[K]="k5") is BLANK)
            if (
                isinstance(relationship, dict) and relationship.get("is_active") and relationship.get("cardinality") == "one_to_one"
                and source_id in {str(relationship.get("from_table_id", "")), str(relationship.get("to_table_id", ""))}
            ):
                partner_id = next(
                    (str(relationship.get(key)) for key in ("from_table_id", "to_table_id") if str(relationship.get(key)) != source_id), None
                )
                partner = contexts_by_id.get(partner_id) if partner_id is not None else None
                direction = "from_to" if partner_id == str(relationship.get("from_table_id", "")) else "to_from"
                if (
                    partner is not None and partner_id in independent_filter_roots
                    and direction in relationship_filter_directions(relationship)
                    and not eff_transition.get(partner_id)  # a row of an iterator over the partner does show it (SUMX(W, CALCULATE(COUNTROWS(VALUES(U[K])))))
                ):
                    if own_unknown_member_selected(partner):
                        partner_selects_blank = True
                        blank_partner_links.add(id(relationship))
                    elif partner_id in unknown_member_ids:
                        return False
        if source_context["id"] not in context_unknown_members and not partner_selects_blank:
            return False

        reachable_table_ids = set(independent_filter_roots)
        filter_edges: dict[str, set[str]] = {}
        for relationship in relationship_definitions:
            if (
                not isinstance(relationship, dict)
                or type(relationship.get("relationship_version")) is not int
                or relationship.get("relationship_version") != 1
                or not relationship.get("is_active")
            ):
                continue
            from_id = str(relationship.get("from_table_id", ""))
            to_id = str(relationship.get("to_table_id", ""))
            if (
                from_id == source_context["id"]
                or to_id == source_context["id"]
                or from_id not in contexts_by_id
                or to_id not in contexts_by_id
            ):
                continue
            directions = relationship_filter_directions(relationship)
            if "from_to" in directions:
                filter_edges.setdefault(from_id, set()).add(to_id)
            if "to_from" in directions:
                filter_edges.setdefault(to_id, set()).add(from_id)
        pending = list(reachable_table_ids)
        while pending:
            table_id = pending.pop()
            for target_id in filter_edges.get(table_id, set()):
                if target_id not in reachable_table_ids:
                    reachable_table_ids.add(target_id)
                    pending.append(target_id)

        def incoming_source(
            relationship: dict[str, Any], target_id: str
        ) -> tuple[str, str] | None:
            from_id = str(relationship.get("from_table_id", ""))
            to_id = str(relationship.get("to_table_id", ""))
            directions = relationship_filter_directions(relationship)
            if "to_from" in directions and target_id == from_id:
                return to_id, str(relationship.get("to_column", ""))
            if "from_to" in directions and target_id == to_id:
                return from_id, str(relationship.get("from_column", ""))
            return None

        for relationship in relationship_definitions:
            if not isinstance(relationship, dict) or not relationship.get("is_active"):
                continue
            source = incoming_source(relationship, source_context["id"])
            if source is None:
                continue
            source_id, source_column = source
            if source_id not in reachable_table_ids:
                continue
            if id(relationship) in blank_partner_links:
                continue  # the partner's filter selects its own blank member: that is what shows this table's blank member
            try:
                link_unknown_members = unknown_member_table_ids(
                    list(contexts_by_id.values()),
                    [relationship],
                    visible_rows_by_id,
                )
            except (RelationshipError, DecimalException) as exc:
                raise MeasureError(
                    f"Could not inspect model relationships: {exc}"
                ) from exc
            if source_context["id"] in link_unknown_members:
                continue
            source_table = contexts_by_id.get(source_id)
            if source_table is None:
                continue
            source_rows = visible_rows_by_id.get(
                source_id, source_table["rows"]
            )
            if not any(
                row.get(source_column) is None
                or str(row.get(source_column, "")) == ""
                for row in source_rows
            ):
                return False
        return True

    def all_table_value(
        expression: tuple[Any, ...],
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        """Materialize supported ALL-family table and column forms."""
        arguments = expression[2]
        function = expression[1]
        if len(arguments) == 1 and arguments[0][0] == "table":
            source_context = resolve_table_context(str(arguments[0][1]))
            output_headers = list(source_context["headers"])
            if function == "ALLSELECTED" and eff_active() and (
                shadowed_rows := allselected_rows_for(source_context, output_headers)
            ) is not None:
                output_rows = shadowed_rows
            elif function == "ALLSELECTED":
                output_rows = list(rows_by_table_id[source_context["id"]])
                current_context = evaluation_contexts_by_id.get(
                    source_context["id"], source_context
                )
                if (
                    source_context["id"] in unknown_member_ids
                    and not unknown_member_hidden(source_context["id"])
                    and unknown_member_passes_remaining_filters(
                        current_context,
                        evaluation_contexts_by_id,
                        evaluation_filter_ids,
                    )
                ):
                    output_rows.append({header: None for header in output_headers})
            else:
                output_rows = list(source_context["rows"])
                if function == "ALL" and source_context["id"] in unknown_member_ids:
                    output_rows.append({header: None for header in output_headers})
        else:
            resolved_columns = [
                resolve_table(reference[1], reference[2])
                for reference in arguments
            ]
            source_context = resolved_columns[0][0]
            if any(context["id"] != source_context["id"] for context, _ in resolved_columns):
                raise MeasureError(
                    f"{function} column arguments must resolve to one loaded table."
                )
            output_headers = [column for _context, column in resolved_columns]
            if function == "ALLSELECTED":
                refuse_one_to_one_blank_reader(source_context["id"], "ALLSELECTED", True)
            allselected_rows = None
            shadowed_rows = (
                allselected_rows_for(source_context, output_headers) if function == "ALLSELECTED" and eff_active() else None
            )
            if function == "ALLSELECTED" and shadowed_rows is None:
                # Power BI: the values of these columns once the filters on the table's other columns are cleared
                # (a filter on one of the columns themselves stays; Facts: CALCULATE(COUNTROWS(ALLSELECTED(Region)),
                # Quantity>3) = 3 but Region="East" gives 1; tools/parity/dax_battery_allselected.json)
                kept_columns = {column.casefold() for column in output_headers}
                cleared_columns = {header.casefold() for header in source_context["headers"]} - kept_columns
                try:
                    allselected_rows = rows_after_clearing_columns(source_context, cleared_columns, True)
                    source_rows, contexts_after_clear, filter_roots_after_clear = allselected_rows
                    # a FILTER table holds only the rows its predicate saw: it never includes the generated blank
                    add_unknown_member = (
                        source_context["id"] in unknown_member_ids
                        and not unknown_member_hidden(source_context["id"])
                        and not _context_shapes(evaluation_contexts_by_id.get(source_context["id"], source_context))
                        and unknown_member_passes_remaining_filters(
                            source_context, contexts_after_clear, filter_roots_after_clear, cleared_columns,
                        )
                    )
                except MeasureError:
                    allselected_rows = None  # a filter context without per-column detail: keep the visible rows
            if shadowed_rows is not None:
                source_rows = shadowed_rows
            elif function == "ALLSELECTED" and allselected_rows is not None:
                own_state = evaluation_contexts_by_id.get(source_context["id"], source_context)
                if (
                    source_context["id"] not in unknown_member_ids
                    and len(source_rows) != len(source_context["rows"])
                    and not own_state.get("filter_column_rows") and not own_state.get("filter_table_rows") and not _context_shapes(own_state)
                    and "filter_rows" not in own_state
                    and any(
                        root != source_context["id"] and not any(
                            isinstance(link, dict) and link.get("is_active") and {link.get("from_table_id"), link.get("to_table_id")} == {root, source_context["id"]}
                            for link in relationship_definitions
                        )
                        for root in evaluation_filter_ids
                    )
                ):  # a filter on a directly related table was measured (saved answer: ALLSELECTED(Dim[Cat]) under Fact[Id]<=7); one two links away was not
                    # live Power BI (ZB): ALLSELECTED(Dim[Prod]) lists all 5 products although a both-way link narrowed the table to 3
                    raise MeasureError("ALLSELECTED over a column that only another table's both-way filter narrows is not supported in the local engine.")
                if add_unknown_member:
                    source_rows.append({header: None for header in source_context["headers"]})
            elif function == "ALLSELECTED":
                source_rows = list(rows_by_table_id[source_context["id"]])
                current_context = evaluation_contexts_by_id.get(
                    source_context["id"], source_context
                )
                if (
                    source_context["id"] in unknown_member_ids
                    and not unknown_member_hidden(source_context["id"])
                    and unknown_member_passes_remaining_filters(
                        current_context,
                        evaluation_contexts_by_id,
                        evaluation_filter_ids,
                    )
                ):
                    source_rows.append({header: None for header in source_context["headers"]})
            else:
                (
                    source_rows,
                    contexts_after_clear,
                    filter_roots_after_clear,
                ) = rows_after_clearing_columns(
                    source_context,
                    {header.casefold() for header in source_context["headers"]},
                    True,
                )
                if function == "ALL" and len(source_rows) != len(source_context["rows"]) and source_context["id"] not in unknown_member_ids:
                    # live Power BI: ALL(column) returns every value of the column, also those a both-way relationship of another
                    # table's filter would hide (ZB: 5 products under Year=2023, not 3).  A table with an unknown member keeps the
                    # older, separately measured rule (Iteration 83: the member and the keys follow the both-way child filters).
                    source_rows = list(source_context["rows"])
                if function == "ALL" and unknown_member_passes_remaining_filters(
                    source_context,
                    contexts_after_clear,
                    filter_roots_after_clear,
                    {header.casefold() for header in source_context["headers"]},
                ):
                    source_rows.append({header: None for header in source_context["headers"]})

            def value_key(value: Any, column: str) -> tuple[str, Any]:
                _reject_power_query_error(value, column, None)
                return cell_key(value)

            output_rows = []
            seen_values: set[tuple[tuple[str, Any], ...]] = set()
            for row in source_rows:
                key = tuple(value_key(row.get(column), column) for column in output_headers)
                if key in seen_values:
                    continue
                seen_values.add(key)
                output_rows.append({column: row.get(column) for column in output_headers})

        if len(arguments) == 1 and arguments[0][0] != "table" and (function != "ALLSELECTED" or allselected_rows is not None or shadowed_rows is not None):
            output_rows = order_distinct_values(source_context, output_headers[0], output_rows)
        value_context = dict(source_context)
        value_context["headers"] = output_headers
        value_context["rows"] = output_rows
        if not (len(arguments) == 1 and arguments[0][0] == "table"):
            value_context["lineage"] = {header: (source_context, header) for header in output_headers}
        return value_context, output_rows

    derived_count = 0
    row_stack: list[tuple[dict[str, Any], dict[str, Any], int]] = []
    selected_iteration_depth = 0  # how many iterations over a SELECTCOLUMNS table are running

    def derived_table(
        headers: list[str],
        rows: list[dict[str, Any]],
        lineage: dict[str, tuple[dict[str, Any], str]] | None = None,
        base_types: dict[str, str] | None = None,
        row_identity: bool = False,
        certain_types: Iterable[str] = (),
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        """A table built by an expression: its rows hold typed DAX values; lineage names the loaded column each came from.

        certain_types: the columns whose type in base_types is Power BI's own (a stated or statically inferred one); every other
        type here is a guess from the first value, good enough to compare but not to print a number by (TOCSV / TOJSON).

        row_identity: its rows are whole rows of the loaded tables behind its lineage (ADDCOLUMNS, GENERATE, CROSSJOIN keep
        them; SELECTCOLUMNS and SUMMARIZE do not), so a row context on them reaches the tables on the one side too."""
        nonlocal derived_count
        derived_count += 1
        column_types: dict[str, str] = dict(base_types or {})
        for header in headers:
            if header in column_types:
                continue
            sample = next((row[header] for row in rows if row.get(header) is not None), None)
            column_types[header] = (
                "boolean" if isinstance(sample, bool) else "text" if isinstance(sample, str)
                else "date" if isinstance(sample, dax_dates.DaxDateTime) else "decimal_number"
            )
        context = {
            "id": f"derived-{derived_count}", "name": f"Table {derived_count}", "headers": list(headers),
            "rows": rows, "column_types": column_types, "derived": True,
            "explicit_types": frozenset(certain_types),
        }
        if lineage is not None:
            context["lineage"] = lineage
        if row_identity:
            context["row_identity"] = True
        return context, rows

    def current_filter(table_id: str, folded: str) -> Any:
        """The row-index set now filtering one column of a table, None when it is not filtered."""
        for column, rows in evaluation_contexts_by_id.get(table_id, {}).get("filter_column_rows", {}).items():
            if column.casefold() == folded:
                return rows
        return None

    def without_eff(thunk: Any) -> Any:
        nonlocal eff_blocked
        saved = eff_blocked
        eff_blocked = True
        try:
            return thunk()
        finally:
            eff_blocked = saved

    def project_layers(layers: tuple[_Shadow, ...], table_id: str, columns: Iterable[str]) -> tuple[_Shadow, ...]:
        dropped = frozenset(column.casefold() for column in columns)
        if not dropped:
            return layers
        kept: list[_Shadow] = []
        for layer in layers:
            projected = layer.projected(dropped) if layer.table == table_id else layer
            if projected is not None:
                kept.append(projected)
        return tuple(kept)

    def shadow_layers_of(context: dict[str, Any], rows: list[dict[str, Any]]) -> list[tuple[str, dict[str, Any], tuple[str, ...], _Shadow]]:
        """One shadow per loaded table the iterated rows' columns come from (nothing for ROW, {..}, computed columns)."""
        lineage = base_lineage(context)
        by_table: dict[str, tuple[dict[str, Any], list[str], list[str]]] = {}
        for header in context["headers"]:
            link = lineage.get(header)
            if link is None:
                continue
            entry = by_table.setdefault(link[0]["id"], (link[0], [], []))
            if link[1] not in entry[1]:
                entry[1].append(link[1])
                entry[2].append(header)
        found = []
        for table_id, (source, columns, headers) in by_table.items():
            def build(headers: list[str] = headers) -> frozenset[tuple[Any, ...]]:
                return frozenset(row_key(typed_row(context, row)[header] for header in headers) for row in rows)
            found.append((table_id, source, tuple(columns), _Shadow(table_id, tuple(columns), build)))
        return found

    def push_shadow(context: dict[str, Any], rows: list[dict[str, Any]], mode: str) -> tuple[Any, ...]:
        """Install (mode "install") or only clear (mode "clear") the shadow of an iterated table; returns what to restore."""
        nonlocal eff_layers, eff_suppressed, eff_blocked
        saved = (eff_layers, eff_suppressed, eff_blocked)
        if mode and not context.get("boolean_filter") and not context.get("no_shadow"):
            eff_blocked = False
            layers, suppressed = eff_layers, dict(eff_suppressed)
            for table_id, _source, columns, layer in shadow_layers_of(context, rows):
                layers = project_layers(layers, table_id, columns)
                suppressed[table_id] = {
                    **suppressed.get(table_id, {}), **{column.casefold(): current_filter(table_id, column.casefold()) for column in columns},
                }
                if mode == "install":
                    layers = (*layers, layer)
            eff_layers, eff_suppressed = layers, suppressed
        return saved

    def pop_shadow(saved: tuple[Any, ...]) -> None:
        nonlocal eff_layers, eff_suppressed, eff_blocked
        eff_layers, eff_suppressed, eff_blocked = saved

    def iterate_rows(
        context: dict[str, Any], rows: list[dict[str, Any]], shadow: str = ""
    ) -> Iterable[tuple[dict[str, Any], dict[str, Any], int]]:
        """Yield each row as a row context while keeping it on the stack EARLIER reads.

        shadow="install": an iterator over a table value filters ALLSELECTED to that table's rows for the loop;
        shadow="clear": CONCATENATEX only removes the outer filters on the columns it iterates."""
        nonlocal selected_iteration_depth
        saved_state = push_shadow(context, rows, shadow)
        selected = bool(context.get("selected_columns"))
        selected_iteration_depth += selected
        try:
            for row_index, row in enumerate(rows, 1):
                frame = (context, row, row_index)
                row_stack.append(frame)
                try:
                    yield frame
                finally:
                    row_stack.pop()
        finally:
            selected_iteration_depth -= selected
            pop_shadow(saved_state)

    def column_in_row_context(frame: tuple[dict[str, Any], dict[str, Any], int], table: str, name: str) -> bool:
        """Whether this row context holds the column (the rules a column reference follows in the innermost row context)."""
        context = frame[0]
        if not context.get("headers"):
            return False  # the empty row context a constant filter is evaluated in
        value_table = resolve_table_context(table) if table else context
        if table and value_table["id"] != context["id"]:
            if context.get("selected_columns"):
                return False  # live Power BI: T[col] is not found among the renamed columns of SELECTCOLUMNS
            lineage = context.get("lineage") or {}
            name = next((
                header for header, (base, column) in lineage.items()
                if base["id"] == value_table["id"] and column.casefold() == name.casefold()
            ), "")
            value_table = context
        if value_table["id"] != context["id"]:
            return False
        return any(str(header).casefold() == name.casefold() for header in context["headers"])

    outer_row_reads = [0]  # how many column reads were answered by an enclosing row context (the walk order of such an iteration is not modelled)

    def enclosing_row_context_for(
        row_context: tuple[dict[str, Any], dict[str, Any], int], table: str, name: str, count: bool = True,
    ) -> tuple[dict[str, Any], dict[str, Any], int]:
        """Iteration 88 (live Power BI, nested iterators): a column the innermost row context does not hold is read from the nearest enclosing
        row context that does (SUMX(Facts, SUMX(ROW("a", 1), Facts[Quantity])) is the sum of Quantity per outer row).  The innermost row
        context keeps winning; with no enclosing one the reference is refused as before."""
        if row_context[0].get("boolean_filter") or column_in_row_context(row_context, table, name):
            return row_context
        for frame in reversed(row_stack):
            if frame[1] is row_context[1] or frame[0] is row_context[0] or frame[0].get("boolean_filter"):
                continue  # the implicit iteration of a Boolean filter is no row context of the query
            if column_in_row_context(frame, table, name):
                outer_row_reads[0] += count
                return frame
        return row_context

    def typed_row(context: dict[str, Any], row: dict[str, Any]) -> dict[str, Any]:
        """A row of a loaded or derived table with every cell as a DAX value."""
        if context.get("derived"):
            return dict(row)
        return {header: typed_cell(context, header, row.get(header)) for header in context["headers"]}

    def base_lineage(context: dict[str, Any]) -> dict[str, tuple[dict[str, Any], str]]:
        existing = context.get("lineage")
        if existing is not None:
            return dict(existing)
        if context.get("derived"):
            return {}
        return {header: (context, header) for header in context["headers"]}

    def row_key(values: Iterable[Any]) -> tuple[Any, ...]:
        values = list(values)
        for v in values:
            if isinstance(v, _UnmodelledField):
                v._refuse()  # a whole-row comparison or hash over an unmodelled field would be invented
        return tuple(cell_key(ascii_fold(v) if isinstance(v, str) else v) for v in values)

    profile_cache: dict[tuple[str, str], Any] = {}

    def source_profile(source: dict[str, Any], column: str) -> Any:
        """The dictionary of one loaded column, built once per evaluation."""
        key = (source["id"], column)
        if key not in profile_cache:
            is_text = str(source.get("column_types", {}).get(column, "text")).casefold() == "text"
            profile_cache[key] = dax_iteration_order.Profile(  # the whole loaded column: filters never shrink a dictionary
                [
                    None if raw is None or (not is_text and isinstance(raw, str) and not raw.strip()) else typed_cell(source, column, raw)
                    for raw in (row.get(column) for row in source["rows"])
                ]
            )
        return profile_cache[key]

    def dictionary_ordered_rows(
        table_node: tuple[Any, ...], context: dict[str, Any], rows: list[dict[str, Any]], nodes: list[tuple[Any, ...]]
    ) -> list[dict[str, Any]]:
        """`rows` of `table_node` in the order Power BI walks them for an iterator reading `nodes` (dax_iteration_order).

        Rows come back unchanged whenever the order is not a measured one: that is the order the app always used."""
        plan = dax_iteration_order.plan(table_node, variable_nodes.get)
        header_by_key = {h.casefold(): h for h in context["headers"]}
        read = dax_iteration_order.columns_read(
            nodes,
            lambda name: name in dax_iteration_order.CROSS_TABLE_CALLS,
            lambda name: name in _AGGREGATING_CALLS or name in _TABLE_FUNCTION_ARITY,
            lambda name: name.casefold() in by_name and name.casefold() not in header_by_key,
        ) if plan is not None else None
        if not read:
            return rows
        lineage = base_lineage(context)
        derived = bool(context.get("derived"))
        origin = context.get("order_source")
        # (source table id, source column) -> (source table, column, reader of that column's value for one walked row)
        combination: dict[tuple[str, str], tuple[dict[str, Any], str, Callable[[dict[str, Any]], Any]]] = {}

        def take_header(header: str) -> None:
            base, column = lineage[header]
            combination.setdefault((base["id"], column), (base, column, (
                (lambda row, h=header: row.get(h)) if derived else (lambda row, h=header: typed_cell(context, h, row.get(h)))
            )))

        def take_source_column(name: str) -> bool:
            """A column named in a SELECTCOLUMNS expression: read from the table that was selected from."""
            if origin is None:
                return False
            source_context, source_of = origin
            header = next((h for h in source_context["headers"] if h.casefold() == name.casefold()), None)
            source_lineage = base_lineage(source_context)
            if header is None or header not in source_lineage:
                return False
            base, column = source_lineage[header]
            source_derived = bool(source_context.get("derived"))
            combination.setdefault((base["id"], column), (base, column, (
                lambda row, h=header: (
                    lambda source: source.get(h) if source_derived else typed_cell(source_context, h, source.get(h))
                )(source_of[id(row)])
            )))
            return True

        def take_expression(expression: tuple[Any, ...]) -> bool:
            sources = dax_iteration_order.columns_read([expression], lambda name: name in dax_iteration_order.CROSS_TABLE_CALLS)
            if sources is None:
                return False
            for _table, name in sources:
                header = header_by_key.get(name.casefold())
                if plan.projects:
                    if not take_source_column(name):
                        return False
                elif header is None or header not in lineage:
                    return False
                else:
                    take_header(header)
            return True

        for _table, name in read:
            if (_table, name) == dax_iteration_order.ALL_COLUMNS:
                if plan.computed or plan.projects or sum(1 for every in context["headers"] if every in lineage) > 3:
                    return rows  # only tables of up to three columns were measured (a four-column table stayed in source order)
                for every in context["headers"]:
                    if every in lineage:
                        take_header(every)
                continue
            header = header_by_key.get(name.casefold())
            if header is None:
                return rows
            if header.casefold() in plan.computed:
                if not take_expression(plan.computed[header.casefold()]):
                    return rows
            elif header in lineage and not plan.projects:
                take_header(header)
            else:
                return rows
        if not all(take_expression(expression) for expression in plan.eager):
            return rows
        if plan.dedup:
            for header in context["headers"]:
                if header in lineage:
                    take_header(header)
        if len({key[0] for key in combination}) != 1:
            return rows
        source = next(iter(combination.values()))[0]
        try:
            profiles = {key: source_profile(source, column) for key, (_base, column, _read) in combination.items()}
            in_dictionary_order = dax_iteration_order.grouped(len(source["rows"]), list(profiles.values()), plan.dedup)
            major_first = sorted(combination, key=lambda key: -source["headers"].index(key[1]))  # a later column is the major key

            def walk_key(row: dict[str, Any]) -> tuple[tuple[int, Any], ...]:
                return tuple(profiles[key].key(combination[key][2](row)) for key in major_first)

            return sorted(rows, key=walk_key) if in_dictionary_order else rows
        except (MeasureError, ArithmeticError, ValueError, TypeError, KeyError):  # a row this order cannot place: keep source order
            return rows

    def summarize_related_group(
        context: dict[str, Any], reference: tuple[Any, ...], own_header: str | None
    ) -> tuple[dict[str, Any], str, Callable[[dict[str, Any]], Any]] | None:
        """SUMMARIZE(Fact, Dim[col]): a column of a table on the one side of the summarized table, reached through its
        active relationships (several hops for a snowflake). None when the column is the summarized table's own (or the table
        is unknown, which keeps the old own-column reading). The reader gives the column's value for one typed input row:
        a key with no partner reaches the unknown member, whose columns are BLANK (live Power BI, tests/fixtures_summarize_related.json)."""
        if not reference[1]:
            return None
        try:
            target = resolve_table_context(str(reference[1]))
        except MeasureError:
            return None
        lineage = base_lineage(context)
        if own_header is not None and (lineage.get(own_header) or (None,))[0] is not None and lineage[own_header][0]["id"] == target["id"]:
            return None
        target_column = next((h for h in target["headers"] if h.casefold() == str(reference[2]).casefold()), None)
        if target_column is None:
            return None
        sources: dict[str, dict[str, str]] = {}  # table id -> casefolded column -> header of the input table
        for header, (base, column) in lineage.items():
            sources.setdefault(base["id"], {})[column.casefold()] = header
        if target["id"] in sources:
            return None
        found: list[tuple[str, str, str, str]] | None = None
        for start_id, columns in sources.items():
            queue: list[tuple[str, list[tuple[str, str, str, str]]]] = [(start_id, [])]
            seen = {start_id}
            while queue and found is None:
                node, path = queue.pop(0)
                for one_id, here, there in one_side_links(node):
                    if one_id in seen or one_id not in contexts_by_id or (not path and here.casefold() not in columns):
                        continue
                    seen.add(one_id)
                    step = path + [(node, here, one_id, there)]
                    if one_id == target["id"]:
                        found = step
                        break
                    queue.append((one_id, step))
            if found is not None:
                first_header = columns[found[0][1].casefold()]
                break
        if found is None:
            if own_header is not None and own_header in lineage:  # a column of a table that is not on its one side: not the same-named own column
                raise MeasureError(f"Column '{target['name']}'[{target_column}] is not reachable from the SUMMARIZE table through a many-to-one relationship.")
            return None
        hops = found

        def read(typed: dict[str, Any]) -> Any:
            key = typed[first_header]
            row: dict[str, Any] | None = None
            for position, (_node, _here, one_id, there) in enumerate(hops):
                one_context = contexts_by_id[one_id]
                matches = one_side_value_index(one_context, there).get(cell_key(key))
                if not matches:
                    return None  # the unknown member
                row = one_context["rows"][min(matches)]
                if position + 1 < len(hops):
                    next_here = hops[position + 1][1]
                    key = typed_cell(one_context, next_here, row.get(next_here))
            one_context = contexts_by_id[hops[-1][2]]
            return typed_cell(one_context, target_column, row.get(target_column)) if row is not None else None

        read.key_column = hops[0][1] if len(hops) == 1 and target_column.casefold() == hops[0][3].casefold() else None  # type: ignore[attr-defined]
        return target, target_column, read

    def loaded_table_ids(name: str) -> list[str]:
        return [item["id"] for item in table_names.get(name.casefold(), [])]

    def expression_table_ids(node: Any, seen: set[str] | None = None) -> set[str] | None:
        """The ids of the tables an expression reads, through the measures it names; None when it reads them all (ALL(), ALLSELECTED())."""
        seen = set() if seen is None else seen
        found: set[str] = set()
        stack = [node]
        while stack:
            item = stack.pop()
            if not isinstance(item, tuple) or not item:
                continue
            if item[0] == "table" and len(item) > 1:
                found.update(loaded_table_ids(str(item[1])))  # not a loaded table: a keyword such as Dense
            elif item[0] == "reference" and len(item) > 2:
                if item[1]:
                    found.update(loaded_table_ids(str(item[1])))
                elif str(item[2]).casefold() in by_name:
                    key = str(item[2]).casefold()
                    if key not in seen:
                        seen.add(key)
                        inner = expression_table_ids(parsed[key], seen)
                        if inner is None:
                            return None
                        found |= inner
            elif item[0] == "call" and item[1] in {"ALL", "ALLSELECTED", "REMOVEFILTERS", "ALLNOBLANKROW"} and not item[2]:
                return None
            stack.extend(child for child in item if isinstance(child, tuple))
        return found

    def summarize_reach(table_id: str, allowed: frozenset[int]) -> dict[str, frozenset[int] | None]:
        """The rows of every table on the one side of table_id that the given rows point at; keys with no partner (the unknown member)
        are left out. None for a table all of whose rows are pointed at (nothing to narrow)."""
        reached: dict[str, frozenset[int] | None] = {}
        queue: list[tuple[str, frozenset[int]]] = [(table_id, allowed)]
        while queue:
            current_id, rows_here = queue.pop()
            current = contexts_by_id.get(current_id)
            for one_id, here_column, there_column in one_side_links(current_id):
                one_context = contexts_by_id.get(one_id)
                if current is None or one_context is None or one_id == table_id or one_id in reached:
                    continue
                index = one_side_value_index(one_context, there_column)
                found: set[int] = set()
                for position in rows_here:
                    found |= index.get(cell_key(typed_cell(current, here_column, current["rows"][position].get(here_column))), frozenset())
                reached[one_id] = None if len(found) == len(one_context["rows"]) else frozenset(found)
                queue.append((one_id, frozenset(found)))
        return reached

    def summarize_group_value(
        expression: tuple[Any, ...], group_context: dict[str, Any], group_row: dict[str, Any], source: dict[str, Any], members: list[int],
        key_columns: dict[str, str], unknown_tables: frozenset[str] = frozenset(),
    ) -> Any:
        """An extension column of SUMMARIZE: the group is the set of rows of the summarized table it holds, which also filter the
        tables on that table's one side to the rows they reach (live Power BI: SUMMARIZE(Fact, Fact[Qty], "x", CALCULATE(SUM(Cal[Year])))
        sees only the dates of the group's fact rows)."""
        by_column = transition_filters(group_context, group_row)
        allowed = frozenset(members)
        read = expression_table_ids(expression)  # a table the column never reads needs no narrowing (and may be ambiguous to reach)
        extra: dict[str, tuple[dict[str, Any], dict[str, frozenset[int]]]] = {}
        if read is None or source["id"] in read or unknown_tables:
            extra[source["id"]] = (source, {column: allowed for column in source["headers"]})
        for one_id, one_rows in summarize_reach(source["id"], allowed).items():
            if one_rows is not None and (read is None or one_id in read):
                one_context = contexts_by_id[one_id]
                extra[one_id] = (one_context, {column: one_rows for column in one_context["headers"]})
        merged: dict[str, tuple[dict[str, Any], dict[str, frozenset[int]]]] = {}
        for table_id, (base_context, column_rows) in extra.items():
            held = by_column.get(table_id, (base_context, {}))[1]
            merged[table_id] = (base_context, {
                column: (rows & held[column] if column in held else rows) for column, rows in column_rows.items()
            })
        # a group on the key column of the relationship (Dim[Prod] for Fact[Prod]) is the same key as the summarized table's own column;
        # any other column of a table on the one side only reaches the summarized table by the context transition
        own = {t: (c, dict(r)) for t, (c, r) in by_column.items() if t == source["id"]}
        # a group whose one-side column is BLANK is the unknown member: it has no row of that table, only the group's fact rows
        hidden_keys = {t: v for t, v in by_column.items() if t != source["id"] and t not in unknown_tables}
        for header, source_column in key_columns.items():
            key_rows = one_side_value_index(source, source_column).get(cell_key(group_row[header]), frozenset()) if group_row.get(header) is not None else allowed
            own.setdefault(source["id"], (source, {}))[1][source_column] = key_rows
        if not any(t != source["id"] for t in merged) and not unknown_tables:
            merged = {}
        elif source["id"] in merged and source["id"] in own:  # a key column of the group keeps standing as the key
            kept = {c: r for c, r in merged[source["id"]][1].items() if c not in own[source["id"]][1]}
            merged = {**merged, source["id"]: (source, kept)}
        visible = {t: v for t, v in merged.items() if t != source["id"] and t not in hidden_keys}
        hidden = {t: v for t, v in merged.items() if t not in visible}
        return with_column_filters(own, lambda: with_column_filters(hidden_keys, lambda: with_column_filters(
            hidden, lambda: with_column_filters(visible, lambda: evaluate(expression), False), True), True), "keys")

    def is_variant_column_expression(expression: tuple[Any, ...], frame: Any, inherited: Iterable[str]) -> bool:
        """Whether a column added by ADDCOLUMNS / SELECTCOLUMNS is a Variant in Power BI: an IF / SWITCH / COALESCE / IFERROR whose
        branches differ in type (text beside a number, a True/False beside a number ...), or one that reads such a column.  The type
        is that of the branches, not of the values the rows happen to hold (live probes, iteration 85)."""
        if any(str(reference[2]).casefold() in inherited for reference in _iter_reference_nodes(expression) if len(reference) > 2):
            return True
        if expression[0] != "call" or expression[1] not in {"IF", "SWITCH", "COALESCE", "IFERROR"}:
            return False
        try:
            if conditional_type(expression, frame) == "variant":
                return True
            if expression[1] == "COALESCE":  # the category of a COALESCE is that of its first argument; every argument counts here
                merge_branch_categories([iterator_expression_category(argument, frame) for argument in expression[2]], "COALESCE")
            else:
                iterator_expression_category(expression, frame)
        except MeasureError as error:
            return "matching local data types" in str(error) or "same local data type" in str(error)
        return False

    def refuse_variant_aggregation(function: str, context: dict[str, Any], expression: tuple[Any, ...]) -> None:
        """MAXX / MINX / SUMX / AVERAGEX / COUNTX over a Variant column read only its numbers (live Power BI, iteration 85); the local
        engine reads the values of the rows instead, which gave wrong answers, so it refuses."""
        variant = context.get("variant_columns")
        if not variant:
            return
        def result_branch_nodes(node: tuple[Any, ...]) -> list[tuple[Any, ...]]:
            if not isinstance(node, tuple) or not node:
                return []
            if node[0] == "call":
                fn, args = node[1], node[2]
                if fn in {"IF", "IF.EAGER"} and len(args) >= 2:
                    return [r for branch in args[1:3] for r in result_branch_nodes(branch)]
                if fn == "SWITCH" and len(args) >= 3:
                    branches = list(args[2::2]) + (list(args[-1:]) if len(args) % 2 == 0 else [])
                    return [r for branch in branches for r in result_branch_nodes(branch)]
                if fn == "COALESCE":
                    return [r for branch in args for r in result_branch_nodes(branch)]
            return [node]

        branch_nodes = result_branch_nodes(expression)
        if any(str(reference[2]).casefold() in variant for b in branch_nodes for reference in _iter_reference_nodes(b) if len(reference) > 2):
            raise MeasureError(f"{function} over a column whose branches have different types is not supported in the local engine.")

    def table_function_rows(argument: tuple[Any, ...]) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        nonlocal eff_touched
        function, arguments = argument[1], argument[2]
        if function in {"LINEST", "LINESTX"}:
            const_after = 3 if function == "LINESTX" else 2  # arguments that cannot be the optional const
            has_const = len(arguments) > const_after and _linest_is_const_literal(arguments[-1])
            if len(arguments) > const_after and not has_const and arguments[-1][0] == "var":
                raise MeasureError("Power BI folds a variable holding TRUE() or FALSE() into LINEST's const argument; the local engine does not model that.")
            const = bool(evaluate(arguments[-1])) if has_const else True
            if function == "LINEST":
                expr_args = arguments[:-1] if has_const else arguments
                if len({resolve_table_context(col[1])["id"] for col in expr_args}) != 1:
                    raise MeasureError("LINEST columns from different tables are not modelled in the local engine.")
                src_table_context, iteration_rows = table_argument_value(("table", expr_args[0][1]))
            else:
                src_table_context, iteration_rows = table_argument_value(arguments[0])
                expr_args = arguments[1:-1] if has_const else arguments[1:]
            y_vals = []
            x_cols = [[] for _ in expr_args[1:]]
            for frame in iterate_rows(src_table_context, iteration_rows, "install"):
                y_vals.append(_linest_number(in_row_expression(lambda frame=frame: evaluate(expr_args[0], frame, allow_text=True, allow_boolean=True))))
                for i, x_expr in enumerate(expr_args[1:]):
                    x_cols[i].append(_linest_number(in_row_expression(lambda frame=frame, expr=x_expr: evaluate(expr, frame, allow_text=True, allow_boolean=True))))
            try:
                headers, result_rows = dax_linest.solve_linest(y_vals, x_cols, const)
            except dax_linest.LinestRefused as error:
                raise MeasureError(str(error)) from error
            return derived_table(headers, result_rows, lineage=None, base_types={h: "double" for h in headers}, certain_types=headers)
        if function == "TABLEOF":
            context = resolve_table_context(arguments[0][1])
            col_name = arguments[0][2]
            base_rows = list(rows_by_table_id[context["id"]])
            header = next((h for h in context["headers"] if h.casefold() == col_name.casefold()), None)
            if header is not None:
                vals = [r.get(header) if context.get("derived") else typed_cell(context, header, r.get(header)) for r in base_rows]
                profile = dax_iteration_order.Profile(vals)
                indexed_rows = list(enumerate(base_rows))
                indexed_rows.sort(key=lambda item: (profile.key(vals[item[0]]), item[0]))
                return context, [r for _, r in indexed_rows]
            return context, base_rows
        if function == "COLUMNSTATISTICS":
            if evaluation_filter_ids:
                raise MeasureError("COLUMNSTATISTICS() cannot be used with a filter context.")
            if len(arguments) > 0:
                raise MeasureError(f"Too many arguments were passed to the {function} function. The maximum argument count for the function is 0.")
            headers = ["Table Name", "Column Name", "Min", "Max", "Cardinality", "Max Length"]
            out_rows = []
            seen_ids = set()
            model_tables = []
            for ctx in contexts_by_id.values():
                if ctx["id"] not in seen_ids and not ctx.get("derived"):
                    seen_ids.add(ctx["id"])
                    model_tables.append(ctx)
            if len(model_tables) > 1:
                raise MeasureError("COLUMNSTATISTICS over a model with several tables is not modelled in the local engine (the row order and the tables listed are not settled).")
            for ctx in model_tables:
                table_name = str(ctx["name"])
                table_rows = list(ctx["rows"])
                out_rows.append({
                    "Table Name": table_name,
                    "Column Name": "RowNumber-2662979B-1795-4F74-8F37-6A1BA8059B61",
                    "Min": None,
                    "Max": None,
                    "Cardinality": Decimal(len(table_rows)),
                    "Max Length": None,
                })
                for col in ctx["headers"]:
                    col_type = str(ctx.get("column_types", {}).get(col, "text")).casefold()
                    if col_type in {"date", "datetime", "boolean"}:
                        raise MeasureError(f"COLUMNSTATISTICS over column '{col}' of type {col_type} is not modelled in the local engine.")
                    raw_values = [r.get(col) for r in table_rows]
                    non_blanks = [v for v in raw_values if v is not None]
                    has_blank = len(non_blanks) < len(raw_values)

                    is_numeric = col_type in {
                        "whole_number", "decimal_number", "decimal", "fixed_decimal",
                        "currency", "number", "numeric", "int64", "double",
                    }
                    if not is_numeric and non_blanks and all(isinstance(v, (Decimal, int, float)) for v in non_blanks):
                        is_numeric = True

                    if is_numeric:
                        num_vals = [v if isinstance(v, Decimal) else Decimal(str(v)) for v in non_blanks]
                        distinct_nums = set(num_vals)
                        cardinality = Decimal(len(distinct_nums) + (1 if has_blank else 0))
                        c_min = min(num_vals) if num_vals else None
                        c_max = max(num_vals) if num_vals else None
                        max_len = None
                    else:
                        str_vals = [str(v) for v in non_blanks]
                        distinct_strs = {dax_typed.text_collation_key(s) for s in str_vals}
                        cardinality = Decimal(len(distinct_strs) + (1 if has_blank else 0))
                        c_min = min(str_vals, key=column_order_key) if str_vals else None
                        c_max = max(str_vals, key=column_order_key) if str_vals else None
                        max_len = Decimal(max(len(s) for s in str_vals)) if str_vals else None

                    out_rows.append({
                        "Table Name": table_name,
                        "Column Name": col,
                        "Min": c_min,
                        "Max": c_max,
                        "Cardinality": cardinality,
                        "Max Length": max_len,
                    })
            base_types = {
                "Table Name": "text",
                "Column Name": "text",
                "Min": "variant",
                "Max": "variant",
                "Cardinality": "int64",
                "Max Length": "int64",
            }
